    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Guide16504623619', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 4, 'Hoàng thành Thăng Long, nằm ở Hà Nội, là Di sản Văn hóa Thế giới UNESCO và là di tích lịch sử quan trọng. Được xây dựng từ thế kỷ 11, nơi đây từng là trung tâm chính trị của Việt Nam trong nhiều thế kỷ.Du khách có thể khám phá các di tích kiến trúc, tường thành và khu vực khảo cổ, phản ánh lịch sử qua các triều đại. Hoàng thành không chỉ thể hiện di sản văn hóa phong phú của Việt Nam mà còn là điểm đến lý tưởng cho những ai yêu thích lịch sử và kiến trúc.', '8 tháng 10, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
