    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vũ Khánh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/af/f7/d0/vukhanh556977.jpg?w=100&h=-1&s=1', 5, 'Một kiến trúc đặc trưng của nhà khu tây bắc. Ở giữa là giếng trời nên rất thoáng. Tiếc là không được vào bên trong ngôi nhà để xem. Ngôi nhà đã là biểu tượng cho người dân khi lên bộ phim Nhà của Pao.', '27 tháng 2, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KianHian L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0e/7b/8e/d5/kianhian-l.jpg?w=100&h=-1&s=1', 3, 'Làng Lũng Cẩm Làng 100 tuổi nép mình ở xã Sung La thuộc thung lũng Sung La thuộc huyện Đồng Văn, cách thị trấn Đồng Văn 25 km. Phần lớn dân tộc ở đây là người H''mông bao gồm hơn 80% và theo sau là người dân tộc Lolo và người Hán. Tại thời điểm viết phí vào cửa là 10 K VND cho ngôi làng nhỏ này. Nó nổi tiếng với ngôi nhà của Pao nơi bộ phim Câu chuyện về Pao được chọn. Người H''mong địa phương bán các sản phẩm địa phương của họ như quả óc chó, lạc, hạt bí ngô, măng khô, rượu gạo, rượu ngô và quà lưu niệm, vv Vé vào cổng 10000 đồng.', '29 tháng 11, 2019', CURRENT_TIMESTAMP);

