    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GoPlaces08757386015', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Từ Phượt Hà Giang mình đi Quản Bạ sau đi Yên mình sau đi mèo vạc tiếp tục đi đồng văn. Địa điểm du lịch này rất thuận tiện gần Bến xe cho việc đi lại và ngắm cảnh  . Với chuyến đi 4 ngày 3 đêm thật là thú vị các bạn nên đi một chuyến đi du lịch về Hà Giang để chiêm ngưỡng vẻ đẹp tự nhiên các Bạn nhé', '23 tháng 7, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
