    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoà N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'tuyệt vời. Mình đến vào lúc khá muộn khoảng 21h40 nhưng bạn chủ và nhân viên vẫn rất niềm nở và ân cần với mình, đồ ăn ngon hợp khẩu vị của mình, đây là một nơi tốt để bạn trải nghiệm khi đến với hà giang', '3 tháng 1, 2023', CURRENT_TIMESTAMP);

