    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/e3/48/12/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tue Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ba/5e/d9/caption.jpg?w=100&h=-1&s=1', 5, 'Là 1 địa điểm du lịch ngắm cảnh chưa được du lịch thương mại hoá nên cảnh vật còn hoang sơ và rất bắt mắt. Trải nghiệm có thể thực hiện bao gồm cắm trại hoặc đi thuyền vào thời điểm hồ nhiều nước.', '21 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Full day motorbike Cao Bang Loop', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/e3/48/12/caption.jpg?w=100&h=-1&s=1', 5, 'Tour của chúng tôi có tham quan Núi Mắt Thần và camping qua đêm ở đây. Khách hàng của chúng tôi đánh giá cao về địa điểm này; Họ cảm thấy rất ấn tượng và lãng mạn khi camping ở đây. Tối hôm đó chúng tôi cùng nhau ăn tối BBQ, uống rượu ngô, đốt lửa trại và trải qua một đêm vui vẻ', '28 tháng 7, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jeff R', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/23/default-avatar-2020-28.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đã ở đó trong mùa khô và không có hồ nhưng điều đó cho phép bạn đi bộ quanh núi. Nó không phải là dễ dàng nhất để tìm thấy nhưng chỉ cần tự hỏi xung quanh bất cứ nơi nào trong đường trở lại huyện Trà Linh là tuyệt đẹp! Oh. . . Hình ảnh là "Góc mắt" hoặc "Lỗ Mt", bản mô tả cho biết Thác nước. . . không có thác nước. . . mà tôi đã thấy', '8 tháng 1, 2020', CURRENT_TIMESTAMP);

