    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/4d/58/95/caption.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/4f/33/55/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/8d/6f/07/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vương Hiểu Vy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Bánh mì đỉnh waa. Mình đi học xa cũng 4,5 năm nay rồi mà mỗi lần về nhà là lại phải ghé quán. Bánh mì siêu cuốn siêu dính mà bít tết, mì ý cũm ngon 😋😋😋', '15 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khánh An', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 5, 'đỉnh. Mình ăn ở quán từ lúc ở địa chỉ cũ đến giờ cũng 2, 3 năm rồi. Cá nhân mình siêu siêu mê bánh mì chảo ở đây. Bánh mì giòn, nước sốt thì có hương vị rất đặc trưng. Bánh mì Thu Thắng luôn là địa chỉ mình lựa chọn đầu tiên của mình và nhóm bạn khi rủ nhau đi ăn. Chủ quán còn rất thân thiện, phục vụ nhiệt tình, quán lúc nào cũng sạch sẽ. Siêu siêu rcm mọi người đến đây thưởng thức', '14 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hằng', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Cảm nhận. Bánh mì Thu Thắng là một trong những quán bánh mì nổi tiếng tại Cao Bằng, thu hút nhiều thực khách bởi hương vị thơm ngon và chất lượng ổn định. Điểm nổi bật đầu tiên phải kể đến là lớp vỏ bánh giòn rụm, vàng ươm, được nướng nóng hổi trước khi phục vụ, tạo cảm giác vừa miệng ngay từ miếng đầu tiên.Phần nhân bánh được chế biến tinh tế, đầy đặn với đa dạng lựa chọn như thịt nướng, chả lụa, pate, và rau sống tươi ngon. Đặc biệt, nước sốt đặc trưng của quán chính là yếu tố tạo nên sự khác biệt, mang hương vị đậm đà, béo ngậy nhưng không ngấy, khiến người ăn nhớ mãi.Ngoài bánh mì, quán còn phục vụ thêm nhiều món ăn kèm như trứng chiên, xúc xích hay đồ uống giải khát, mang lại sự tiện lợi cho thực khách. Dịch vụ tại đây nhanh nhẹn, thân thiện, và giá cả hợp lý, phù hợp với học sinh, sinh viên', '14 tháng 1, 2025', CURRENT_TIMESTAMP);

