    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/43/ed/66/photo0jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jeff R', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/23/default-avatar-2020-28.jpg?w=100&h=-1&s=1', 5, 'Bánh pizza đẹp!. Gia đình sở hữu tiệm pizza ở Cao Bằng Việt Nam làm cho một chiếc bánh ngon! Nhà hàng rất đẹp và chủ rất đẹp', '8 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'goldghost', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Bánh pizza đúng cách!. Tôi đã rất ngạc nhiên khi có thể tìm thấy những chiếc bánh pizza vỏ mỏng thích hợp ở một nơi xa lạ như thành phố Việt Nam. Các loại pizza thực sự là tốt và giá cả hợp lý - 150 k đến 180 k. Chai rượu vang đỏ (địa phương) là 180 K. Rất khuyến khích', '5 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tim L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/10/default-avatar-2020-8.jpg?w=100&h=-1&s=1', 5, 'Pizza tuyệt vời. Chúng tôi không ngờ rằng pizza sẽ ngon đến vậy. Chúng tôi đến đây với hy vọng có được một cái gì đó gần với một chiếc bánh pizza nhưng là cách tốt hơn thế! ! Tôi lấy margherita (có thêm hành tây trên hình) và nó thực sự tốt. Ngày sau khi chúng tôi trở lại và lấy như vậy. Verry tốt, sạch và rẻ. Nếu bạn đang tìm kiếm một cái gì đó không phải là vietname để ăn, đây là nơi để được! !', '20 tháng 11, 2019', CURRENT_TIMESTAMP);

