    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Yến Nhi homesta... L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 5, 'Do uong ngôn. Do uong ngôn gia ca hợp li.

Năm trong trung tam Tp cao bang

Một noi li tuong thu giab

Tất khuyên khich', '31 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jan R', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/3f/73/e7/caption.jpg?w=100&h=-1&s=1', 5, 'Quán cà phê & đồ uống tuyệt vời ở Cao Bằng. Nơi này có sinh tố chuối và xoài tuyệt vời! nó có vẻ tốt và dịch vụ là tuyệt vời (tiếng Anh của họ không phải là tốt nhưng hey, đây là Việt Nam, không phải là Anh hoặc Mỹ). Google Dịch sẽ giúp bạn đặt hàng: -)', '8 tháng 8, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mariss D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Cà phê tuyệt vời !!. Chúng tôi đã dành một buổi chiều cà phê này và nó thực sự tuyệt vời! Mango Smoothie mà tôi có là rất tốt và cũng là Caramel Latte của họ.

Họ có một sân thượng nhỏ ngọt ngào với một cái nhìn rất đẹp trên sông!

Dịch vụ cũng tốt và giá cả hợp lý.

Thực sự đề nghị! !', '28 tháng 7, 2018', CURRENT_TIMESTAMP);

