    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 4, 'Đi thuyền trên hồ mang lại cảm giác thư giãn rất tuyệt. Đây là hồ nước ngọt tụ nhiên lớn nhất Việt Nam. Trên hành trình, mình ghé thăm động Puông và đảo Bà Goá - những điểm nhấn khá ấn tượng. Rất vui vì đã ghé thăm địa chỉ này.', '29 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoàng Thái', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 5, 'Được ví như vịnh hạ long của Bắc Cạn, khu vực vườn quốc gia ba bể vẫn còn rất hoang sơ. nhiều loài động thực vật được bảo tồn tốt ở đây', '27 tháng 10, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jon N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/36/37/ff/jon-n.jpg?w=100&h=-1&s=1', 3, 'Chúng tôi đã đặt tour du lịch 3 D 2 N từ Hà Nội đến thác Bản Giốc, trong đó bao gồm một chuyến tham quan Vườn quốc gia Ba Bể. Chúng tôi đi thuyền trong hồ, bao gồm ba điểm dừng (Farry Pond, Đền An Ma và Đảo Widow). Chúng tôi không thực sự tìm thấy cảnh quan và điểm dừng chân rất hấp dẫn cho chúng tôi sau khi ghé thăm Ninh Bình và Vịnh Hạ Long. Cá nhân sẽ không thực hiện một chuyến thăm riêng ở đây.', '19 tháng 11, 2019', CURRENT_TIMESTAMP);

