    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Achong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 5, 'Fansipan là một điểm đến hùng vĩ và thách thức, được mệnh danh là "nóc nhà Đông Dương" với vẻ đẹp của núi rừng Tây Bắc và cảnh quan mây trời ngoạn mục. Du khách có thể chọn chinh phục đỉnh núi bằng cách leo núi đầy thử thách hoặc di chuyển nhanh chóng bằng hệ thống cáp treo hiện đại, trải nghiệm này mang lại cảm giác choáng ngợp và tự hào khi đặt chân đến đỉnh cao 3.143m. Ngoài vẻ đẹp tự nhiên, Fansipan còn là một quần thể tâm linh lớn với nhiều công trình kiến trúc ấn tượng.Điểm cộng', '19 tháng 11, 2025', CURRENT_TIMESTAMP);
