    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/bd/43/c5/sapa-classic-vegan-t.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Peter Hanh Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 5, 'Bản cách  trung tâm thị trấn sapa tầm 15km. Bả chủ yếu là của người dao sinh sống, mình rất thích khung cảnh nơi đây, rất hoang sơ và trong lành. Tuy đường đi có hơi xa, nhưng cũng là một bản đáng để trải nghiệm.', '4 tháng 3, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Thùy Nghiên', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Đi sapa mà không đi Tả Phìn thì đúng là một thiếu sót lớn. TẢ phìn quá đẹp, đi trekking qua bản mới cảm nhận hết được cuộc sống của người bản địa nơi đây. Từ bản view được nhiều cảnh ruộng bậc thang, núi non ... rất đẹp', '3 tháng 1, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Beth A', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 2, 'Khi chúng tôi bắt đầu, chúng tôi đã đi cùng với một nhóm phụ nữ và trẻ em đang cố gắng bán cho chúng tôi một số sản phẩm của họ. Cuối cùng họ cũng cho chúng tôi đi cùng sau khoảng một giờ ở bên chúng tôi. phần còn lại của cuộc đi bộ là dễ chịu nhưng rất dài. Hơn hai giờ và mùi cuối cùng đã đến với tôi vì vậy tôi rất vui khi đi đến cuối cùng.', '7 tháng 3, 2020', CURRENT_TIMESTAMP);

