    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Chân Phương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 5, 'Đang mùa lúa đẹp, các bạn tranh thủ đi thăm các bản làng trên này, lúa trên ruộng bậc thang tuyệt đẹp luôn.', '15 tháng 9, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Minh Nguyễn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/22/ab/bd/4a/minhnd022.jpg?w=100&h=-1&s=1', 5, 'Từ trung tâm Sapa, bạn phải di chuyển bằng xe máy đi men theo tuyến đường thung lũng Mường Hoa khoảng 8km. Khi đến ngã 3, bạn rẽ vào đường Lao Chài và đi khoảng 2km nữa là đến cầu Mây. Đường đi cầu Mây khá dốc nên bạn cần có tay lái vững để đảm bảo an toàn. Nếu bạn không quen đường thì có thể hỏi người dân địa phương. Họ sẽ nhiệt tình chỉ đường thậm chí dẫn bạn đến cầu Mây.', '24 tháng 3, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phương Lê', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 5, 'Mình phải tranh thủ thời gian lên trước 30 tháng tư không thì đông lắm mà giá phòng lúc đó cũng đắt. Lúa chưa chín nhưng nhìn cả một giải đồi ngan ngát một màu xanh của lúa, từng ruộng lúa bậc thang một.đường đi du thì cực đẹp. Phải tranh thủ đi đến tháng sau lúa vàng chín ta lại làm một chuyến nữa.', '24 tháng 4, 2021', CURRENT_TIMESTAMP);

