    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DayTrip39393486314', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'tứ đại đỉnh đèo rât đẹp hùng vĩ đón hoàng hôn săn mây đẹp nhất sp bạn nên đến nếu có cơ hội sẽ không thất vọng đâu', '21 tháng 6, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Chân Phương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 5, 'Một trong tứ đại đỉnh đèo, đi xe máy qua đèo Ô quy hồ đúng là một trải nghiệm đáng nhớ, 2 người đi xe máy, cài số 1 mà không lên nổi, người ngồi sau phải xuống ủn xe mới đi đc :))', '15 tháng 9, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phương Lê', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 5, 'Thật xứng đáng là tứ đại đỉnh đèo. Đèo ô Quy hồ xứng đáng là số một trong tứ đại đỉnh đèo đó. Đi lên đây bằng xe máy, chạy với số một mà còn không lên nổi. Người ngồi sau phải xuống đầy xe. Lên đến nơi, xe máy như là rãi hết xích :(', '24 tháng 4, 2021', CURRENT_TIMESTAMP);

