    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/84/3c/58/day-la-homestay-c-a-nha.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Elena Lalle Daring', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Không gian bảo tàng thoáng mát', '31 tháng 5, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ChicoRanMan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e9/41/95/chicoranman.jpg?w=100&h=-1&s=1', 5, 'Đây là một bảo tàng rất hay về trận chiến giữa người Pháp và người Việt Nam năm 1954. Rất nhiều hiện vật. Bảng hiệu tiếng Anh. Nhà vệ sinh sạch sẽ. Phí vào cửa 75 xu.', '3 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'John W', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/10/default-avatar-2020-8.jpg?w=100&h=-1&s=1', 4, 'Bảo tàng này kể câu chuyện về trận chiến theo quan điểm của Việt Minh. Một số sự chú ý được dành cho những đau khổ chịu đựng của Pháp và quân đội thực dân của họ, nhưng không đủ để cân bằng tài khoản chiến thắng của chiến thắng. Việc sử dụng lao động nhập ngũ để cung cấp cho lực lượng tấn công được tự do thừa nhận. Nhưng có một bóng tuyên truyền, đặc biệt là liên quan đến các bộ lạc. Có diorama minh họa và một bộ sưu tập hiện vật quân sự và cá nhân chiết trung. Chú thích bằng tiếng Việt, tiếng Anh và tiếng Pháp giải thích các cuộc triển lãm.', '16 tháng 12, 2019', CURRENT_TIMESTAMP);

