    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/5c/1b/51/one-of-the-600-graves.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/26/cf/a0/08/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/90/14/bd/img-20190223-160142-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ChicoRanMan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e9/41/95/chicoranman.jpg?w=100&h=-1&s=1', 5, 'Vào cửa miễn phí tại nghĩa trang này cho người Việt Nam trong trận chiến chống Pháp năm 1954. Nghĩa trang được chăm sóc cẩn thận và có mùi nhang đáng yêu đang cháy ở bia mộ. Đây là ngay bên kia đường từ bảo tàng. Cả hai đều đáng để ghé thăm.', '3 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mây Nguyễn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/06/7a/e0/thu-van-n.jpg?w=100&h=-1&s=1', 4, 'Nghĩa trang nằm trong khuôn viên rộng lớn bên cạnh đồi A1, đối diện bảo tàng. Sau khi tham quan bảo tàng nghe thuyết minh về cuộc chiến, về những mất mát, những hy sinh và những chiến thắng, thật xúc động về tất cả những giá trị ấy. Nơi đây rất nhiều hài cốt liệt sĩ được quy tập về nhưng rất nhiều liệt sĩ chưa xác định được danh tính trên mộ phần. Tại cổng có bàn bán hương (nhang), tiện cho bạn mua vào viếng. Không gian tĩnh lặng, thanh tịnh.', '16 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'R M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/09/1d/fd/r-m.jpg?w=100&h=-1&s=1', 4, 'Nghĩa trang là miễn phí và ngay bên kia đường từ bảo tàng. Điều làm tôi ấn tượng nhất là nó giống với các nghĩa trang chiến tranh khác trên thế giới. Giữ một cách vô song và bức tường của những cái tên rất khiêm nhường.', '8 tháng 6, 2019', CURRENT_TIMESTAMP);

