    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/ab/5e/2a/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Peter M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/73/default-avatar-2020-13.jpg?w=100&h=-1&s=1', 5, 'ở vùng núi gần biên giới lao và khó có thể tìm thấy là một viên ngọc ẩn, một hồ bơi khoáng nóng, và một hồ bơi lạnh. Tôi đã đến rất nhiều hồ bơi nóng ở Úc nhưng không sắc nét và sạch sẽ như thế này, tôi không muốn nhận ra và phần tốt nhất, khi bạn phần lan bơi của bạn, bạn có thể nhận được một ly bia lạnh đẹp', '14 tháng 3, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thangcosapa', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 3, 'Sau một ngày rong ruổi trên nhiều cung đường của tỉnh Điện Biên , đoàn chúng tôi lựa chon khu du lịch khoáng nóng để thư giãn . Cảm giác thật tuyệt vời khi được ngâm mình trong dòng nước nóng tự nhiên , mọi mệt mỏi đều tan biến hết .Về cơ sở vật chất cần được nâng cấp thêm , chất lượng dịch vụ còn kém . Bồn tắm còn bẩn và sơ sài .', '13 tháng 10, 2017', CURRENT_TIMESTAMP);

