    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/0e/b9/8a/img-20190821-085804-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'HUGO 3', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 5, '3 ngày rong ruổi bằng xe winCảm giác 2 cổ tay như hóa đáDọc đường là núi mây bụi gió và những giây phút khó quênTuổi trẻ để đi để cảm nhận đất nướcTuy gần nhà nhưng lần đầu chinh phục a pa chải và cột mốc tưởng dễ ai ngờ thở ko ra hơiĐổi lại là cảnh đẹp đến mê hồnNhất định sẽ thu xếp để quay lại', '30 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cty DL Thám Hiểm Việt Nam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/83/4d/e4/dulichthamhiem.jpg?w=100&h=-1&s=1', 5, 'Đã lên đến điện biên mà không tới đây check-in thì thật uổng phí. Cảm giá được chạm tay vào cột mốc khó tả biết bao, một tay bên lãnh thổ việt nam, một tay bên nước ban :)))', '15 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Langbam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/39/ce/b4/avatar.jpg?w=100&h=-1&s=1', 4, 'Là một trong 2 cột mốc tam giác đặc biệt (cùng với cột mốc tại Bờ Y, Kon Tum) mà bất kì người dân Việt Nam nào cũng muốn đặt chân đến. Tuy nhiên việc tiếp cận không mấy dễ dàng, cách thành phố Điện Biên khoảng 250km, đường khá khó đi. Không có nơi lưu trú nên ngủ nhờ đồn biên phòng, phòng ngủ khá tệ (không có sự lựa chọn). Bạn dẫn đường không nhắc nhở và giám sát du khách nên đường đi còn khá nhiều rác do du khách để lại.', '28 tháng 7, 2018', CURRENT_TIMESTAMP);

