    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/33/36/ad/photo0jpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/61/03/03/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tourist04795728843', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/b8/ca/ef/tourist04795728843.jpg?w=100&h=-1&s=1', 5, 'Trải nghiệm tốt. Mình đến đây thưởng thức cùng gia đình thật sự hương vị ở đây rất tuyệt vời, đây là nhà hàng chay ngon nhất mình từng ăn, mình chắc chắn sẽ quay lại', '27 tháng 3, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Rob K', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/e8/e9/b9/photo0jpg.jpg?w=200&h=-1&s=1', 5, 'Đơn giản là hoàn hảo. Trong 2 đêm liên tiếp, chúng tôi ăn tối tại Yên Ninh. . . chúng ta không có điểm nào cho sự sáng tạo, nhưng tại sao lại gây rối với một điều tốt? !
Thức ăn luôn tuyệt vời . . món ngon nhất chúng tôi đã ăn trong suốt chuyến lưu diễn qua miền bắc Việt Nam. Đặc biệt ấn tượng là sự nhẹ nhàng của các món chiên, sự pha trộn tinh tế của hương vị và nhiều lựa chọn.
Tôi không ăn chay, nhưng sẽ cân nhắc chuyển đổi sau khi ăn ở đây thêm vài lần nữa!
Chủ sở hữu và nhân viên của cô ấy rất thân thiện và có sức chứa, và được chứng minh là nguồn thông tin du lịch & du lịch địa phương tốt nhất của chúng tôi', '16 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Helen M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Một viên ngọc thực sự của một nơi với thức ăn ngon.. Nhà hàng nhỏ tuyệt vời với thức ăn chay ngon. Giá trị đồng tiền và nhân viên rất thân thiện, nói tiếng Anh tốt. Nó rất gần với nơi chúng tôi ở (Homestay Rose Villa) vì vậy chúng tôi đã đến đó cả hai buổi tối chúng tôi đã ở dienBien. Chúng tôi yêu thích mọi món ăn chúng tôi có', '7 tháng 1, 2020', CURRENT_TIMESTAMP);

