    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/0e/86/2a/20180806-193328-largejpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/33/c4/f9/dc-116-b-n-kha-phu-ng.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'chandon franck', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/97/40/8d/caption.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng dễ thương và dân tộc. Nơi tuyệt vời. Vì vậy, loại phi hành đoàn trên trang phục ethnie
Các bữa ăn rất đẹp và ngon.
Chúng tôi thử chụp địa phương và vui vẻ với phụ nữ.
H cao r khen', '9 tháng 8, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Me_n_my_rucksack', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/01/70/23/2e/me-n-my-rucksack.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng lớn - được xây dựng để mang đến bầu không khí Việt truyền thống - món ăn ngon. Đầu tiên là tin xấu - không có Menu tiếng Anh và không ai trong số nhân viên nói tiếng Anh. Nhà hàng này là nhằm vào các gia đình và các nhóm lớn ở đó cho một bữa ăn tối hoặc tối.

Tin tốt là bất chấp rào cản ngôn ngữ mà nhân viên rất thân thiện - chúng tôi đã chọn bữa tối ăn tối bởi phỏng đoán và dịch google và đó là một bữa ăn đủ tốt. Tiêu chuẩn cơm chiên thịt và rau. Giá đã cao hơn một chút so với chúng tôi đã từng được sử dụng nhưng không đáng kể như vậy.

Tất cả trong tất cả một bữa ăn tối hợp lý - thách thức trong đặt hàng thêm vào expoerience tổng thể!', '31 tháng 3, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngocdung0607', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/59/default-avatar-2020-49.jpg?w=100&h=-1&s=1', 4, 'Món ăn địa phương tuyệt vời. Tôi đã ở đó với một nhóm. Tất cả chúng tôi đều hài lòng với thức ăn. Trang trí hơi lạ với chúng tôi, nhưng không sao cả. Đặc sản địa phương được đề xuất cao inc. gạo nếp tím, cá nướng kiểu Thái. Tất cả đều tốt!', '22 tháng 1, 2018', CURRENT_TIMESTAMP);

