    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thuy K', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/cf/e6/05/thuy-k.jpg?w=100&h=-1&s=1', 5, 'Tấp nập nhưng không quá ồn ào, đa sắc màu trang phục nổi bật giữa trập trùng núi rừng là chợ phiên Tam Đường với  những sản vật chắc chắn làm bạn thấy thú vị', '14 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hùng Tom Travel', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/4a/00/3b/tomtraveonline.jpg?w=100&h=-1&s=1', 5, 'Khám phá chợ Tam Dương Đạt hoặc chợ San Thăng cách Sapa 70 km, đây là chợ lớn nhất ở Lai Châu Từ sáng sớm, người dân tộc Lu, Giay, H''Mông, Đào và Thái, trong trang phục đẹp nhất của họ, đổ về thị trường với các sản phẩm nông nghiệp đa dạng của họ. còn động vật như nhặt, gà, trâu, vịt, trứng, rau, mật ong, sắn. và đặc sản truyền thống và các đối tượng thủ công.Đối với người dân địa phương, chợ cũng có cơ hội để họ gặp gỡ và trò chuyện với nhau và thậm chí thư giãn. Tham gia để khám phá thị trường và tìm hiểu thêm về người dân tộc thiểu số của miền Bắc Việt Nam.', '16 tháng 4, 2019', CURRENT_TIMESTAMP);

