    VALUES (gen_random_uuid(), v_place_id, 'Lai Chau Trekking', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/13/28/6e/laichautour.jpg?w=100&h=-1&s=1', 5, 'Thức ăn ngon trong nhà hàng. Tôi rất hài lòng với dịch vụ và đồ ăn ở đây, nhà hàng không quá sang trọng nhưng sạch sẽ với các món ăn địa phương, giá cả hợp lý cho khách du lịch và gia đình, họ làm việc chuyên nghiệp nhưng cần thêm nhân viên nói tiếng Anh vào tương lai của nhà hàng', '31 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lai Chau Trekking Tour', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/0e/af/4b/laichautrekking.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng tốt ở Lai Châu. Nhà hàng nằm giữa trung tâm, nhà hàng sạch sẽ với những món ăn địa phương ngon, ông Hùng không nói nhiều tiếng Anh nhưng rất thân thiện, ông thường cười với chúng tôi, đồ ăn rất ngon và rẻ', '29 tháng 8, 2019', CURRENT_TIMESTAMP);

