    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/13/a0/1f/e9/photo2jpg.jpg', 0, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/e1/20/61/such-incredible-town.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/8a/e5/33/m-c-chau.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/b9/9c/1f/mai-chau-vista-dal-thung.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/15/ff/a3/m-t-d-a-di-m-r-t-dang.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Viefarm', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/66/default-avatar-2020-53.jpg?w=100&h=-1&s=1', 5, 'Mộc Châu, với khí hậu mát mẻ quanh năm và cảnh sắc thiên nhiên thơ mộng, là điểm đến lý tưởng cho những ai yêu thích sự yên bình và vẻ đẹp hoang sơ. Chuyến đi đến Mộc Châu để lại trong tôi nhiều ấn tượng khó quên, từ những đồi chè xanh ngát, thác Dải Yếm hùng vĩ đến những vườn hoa rực rỡ sắc màu.Một trong những trải nghiệm tuyệt vời nhất là đi dạo trên đồi chè vào buổi sáng sớm, khi sương mờ còn vương trên lá, tạo nên khung cảnh huyền ảo. Ngoài ra, mùa hoa mận và hoa đào nở rộ cũng là thời điểm lý tưởng để ghé thăm, khi cả vùng cao nguyên như khoác lên mình một tấm áo trắng hồng tinh khôi.Ẩm thực ở Mộc Châu cũng là điểm nhấn không thể bỏ qua. Những món đặc sản như bê chao, cá suối nướng, sữa chua nếp cẩm mang đến hương vị đặc trưng của núi rừng Tây Bắc.', '12 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Moo Moo', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/a2/f2/e8/moomoo0209.jpg?w=100&h=-1&s=1', 5, 'Cao nguyên Mộc Châu là một điểm đến tuyệt vời với vẻ đẹp thiên nhiên hùng vĩ và không khí trong lành. Nơi đây nổi tiếng với những cánh đồng cỏ xanh mướt, vườn hoa cải trắng nở rộ, và các bản làng dân tộc duyên dáng. Cảnh quan nơi đây thay đổi theo mùa, mang đến những trải nghiệm khác biệt cho du khách. Thời tiết mát mẻ và khí hậu ôn hòa làm cho Mộc Châu trở thành một nơi lý tưởng để thư giãn và khám phá. Ẩm thực địa phương cũng là một điểm cộng lớn với những món ăn ngon miệng và độc đáo.', '11 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ASIA HOLIDAY TRAVEL', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/ca/a8/cf/asia-holiday-tr-v.jpg?w=100&h=-1&s=1', 4, 'Mộc Châu - cao nguyên yên bình và xinh đẹp', '6 tháng 4, 2024', CURRENT_TIMESTAMP);

