    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anh Japan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Đồi chè bát ngát , xanh mát cả một góc trời. Đi qua khu vực này đc, dừng lại chụp ảnh, check in lúc thôi chứ quanh đây cũng không có dịch vụ gì cả .', '1 tháng 8, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hậu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 4, 'View đẹp, bát ngát các ngọn đồi chè. Nhưng cũng chỉ có vậy, thật là tiếc vì không có dịch vụ gì khác. Vào thăm quan khoảng 1 tiếng chụp ảnh rồi lại đi.', '7 tháng 7, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Van Phong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/1e/d1/a2/caption.jpg?w=100&h=-1&s=1', 4, 'Chụp ảnh miễn phí, người dân thân thiện, dịch vụ trải nghiệm ở mức bình dân. Đồi chè vừa được cắt tỉa nhìn trụi húi ạ. Có rất nhiều bạn thanh thiếu niên dân tộc quoanh khu vực này. Thớt nghiến và các loại hoa lan rừng, mận và nông sản được bày bán ở đây. Các bạn nên ghé thăm vào dịp mùa thu thì hợp lý vì thời tiết dịu hơn', '12 tháng 5, 2020', CURRENT_TIMESTAMP);

