    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/1b/b1/cd/img20190410125036-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 3, 'Không có gì đặc biệt ngoài đồi chè trải dài như những đồi chè khác ở Mộc Châu. Xen lẫn có những khoảng trồng cỏ và mía (chắc để nuôi bò). Những bạn trẻ thích chụp ảnh tự sướng ở đây. Còn mình không có ý định quay lại.', '9 tháng 5, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ng Hồng Phượng', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/6a/default-avatar-2020-47.jpg?w=100&h=-1&s=1', 4, 'Điều đầu tiên thấy thích là cảnh đồi chè bát ngát rất đẹp, hôm mình đi lại được ngày nắng nhẹ nên đẹp lắm, lại còn được xem người dân hái chè bằng máy ở đây nữa. Các dịch vụ cho thuê đồ mặc chụp ảnh ở đây giá cả hợp lý, bán đồ giá cũng không bị đắt.Điều tiếc nhất là không có nhà vệ sinh và phòng thay đồ (hoặc có nhưng nó ở cái chỗ hẻo lánh nào vậy mình chẳng biết nữa).', '23 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thangcosapa', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 5, 'Quá đẹp ! chúng tôi dừng chân tại lâm trường Mộc Châu với một cảm giác bâng khuâng đến khó tả , nhìn những đồi chè xanh ngút ngàn tầm mắt cộng với hương thơm thoang thoảng của hoa chè làm cho chúng tôi ngây ngất .Con người nơi đây thật là tình cảm , thân thiện mời chúng tôi những ly trà thơm ngát của mảnh đất này .Chúng tôi sẽ quay lại Mộc Châu vào một ngày gần nhất.', '11 tháng 10, 2017', CURRENT_TIMESTAMP);

