    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/98/86/7b/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/7a/6d/40/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hung N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/98/86/7b/caption.jpg?w=100&h=-1&s=1', 5, 'Hang động này không phải là rất lớn. Chỉ cần dành 1 - 2 giờ bạn có thể hoàn thành việc truy cập. Giá tôi nhớ là 1. 2 USD (30000 đồng).Chỉ cần đi bộ vài bước và bạn có được hang động và có thể thưởng thức đá thiên nhiên tuyệt đẹp ở bên cạnh. Bạn có thể truy cập vào buổi sáng sớm hoặc buổi tối khi ánh sáng đi vào làm cho nó trông tuyệt vời', '9 tháng 7, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/70/4f/a4/tony-hanoi-98.jpg?w=100&h=-1&s=1', 4, 'Hang chỉ có hơn 100 con dơi sống bên trong. Theo truyền thuyết, có một con rồng bay đến khu vực hang và sống ở đó một thời gian dài. Sau đó, để cảm ơn đất, con rồng đã cho 7 ngọn núi nhỏ xung quanh khu vực đó. Nó có thể được thay đổi màu sắc trong ngày, như vậy chúng tôi trắng trong moring, màu xanh lá cây vào buổi trưa, và màu vàng.Trong quá khứ đã có hàng ngàn con dơi sống trong hang động, nhưng chúng bay ra vì ảnh hưởng của việc hút thuốc từ nhang.', '24 tháng 6, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thara_Doan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/95/b8/c6/thara-doan.jpg?w=100&h=-1&s=1', 4, 'This Cave is good for visiting. It take you about 1-1h30 with the price at 10.000 VND (both for vietnamese and foreigner. It is right in the city central, next to motorway. There is also many restaurant around there. You have to climb a little bit to enter the cave.Cette grotte est bonne pour visiter. Il vous faut environ 1-1h30 avec le prix à 10.000 VND (à la fois pour les Vietnamiens et les étrangers.) Il se trouve en plein centre-ville, à côté de l''autoroute, il est pres des restaurants. Il faut monter un peu pour entrer la grotte.Mất khoảng 1-1h30 để thăm hang với giá 10.000 đồng (cả cho người Việt Nam và người nước ngoài). Hang nằm ngay tại trung tâm thành phố, bên cạnh quốc lộ. Ngoài ra còn có nhiều nhà hàng xung quanh. Bạn phải leo một chút để vào hang, sẽ hơi mệt đấy', '24 tháng 4, 2018', CURRENT_TIMESTAMP);

