    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/50/2f/38/dai-yem-waterfall.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/46/c2/63/spring-at-bach-long-glass.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/27/6d/bd/b7/moc-chau-island-attractions.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'AugereauBui', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/79/42/b8/caption.jpg?w=100&h=-1&s=1', 5, 'Do được đầu tư để phát triển du lịch nơi đây nên bên trong thác đã có sự đầu tư tỉ mỉ và khang trang, các lối đi bên thác đã được trùng tu lại sao cho du khách để di chuyển tới thác. Để du khách có thể cảm nhận được vẻ đẹp tựa núi rừng, thác nước nơi đây người ta đã xây dựng cầu kính Tình Yêu bắc qua nơi ngọn thác để khách du lịch có thể cảm nhận được cái đẹp của nơi đây. Bên cạnh đó còn có cái hoạt động vui chơi, ăn uống bên trong khuôn viên như các món ăn của người đồng bào miền núi Tây Bắc, các trò chơi như đường trượt zipline. Thời gian tham quan tại điểm du lịch này là vào khoảng 1 giờ trở lên là du khách đã có thể cảm nhận được trọn vẹn vẻ đẹp hùng vĩ của nơi này.', '17 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 4, 'Thác nước đẹp, rất thích khi được đứng ngay cạnh để cảm nhận những tia nước bắn ra mát rượi. Có thể chơi đu dây hoặc đi qua cầu kính, nhưng mình không thích lắm vì cảnh được tạo ra không tự nhiên và cũng không ăn nhập gì với cảnh đẹp của thác dải mây. Nhưng nếu chỉ đến để ngắm thác nước thì cũng ổn. Vé vào cửa 50.000đ/ người, còn chơi đu dây hay qua cầu kính thì mua vé riêng. Trong khu vực thác có một chợ nông sản nhỏ nhưng mình không nghĩ giá các mặt hàng ở đây thực sự là giá tốt. 1 tiếng trong khu vực này là đủ.', '9 tháng 5, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Onie T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/b7/69/da/onie-t.jpg?w=100&h=-1&s=1', 4, 'Bản thân thác nước và thung lũng xung quanh thật đẹp.Nhưng đáng buồn là nó đã được phát triển quá mức. Thật tốt khi họ thêm đường dẫn và nhà vệ sinh; nhưng những thứ khác như cây cầu, cầu thang và những khu vườn nhân tạo không thực sự cần thiết. Họ làm cho nơi này trông giống như bạn đang ở trong một công viên trong thành phố.Tôi hy vọng họ cũng làm gì đó về giao thông xe trên con đường dẫn đến thác. Mọi người cần đi bộ trên đường về phía lối vào nhưng không có vỉa hè.', '28 tháng 11, 2019', CURRENT_TIMESTAMP);

