    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/bf/34/69/d-c-s-n-m-c-chau-t-hoa.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nam Hoàn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 4, 'Rất tuyệt vời đi để trải nghiệm,thoả sức vui chơi hoà vào nền văn hoá và bản sắc dân tộc nơi đây.và con người nơi đây cũng rất thân thiện hoà đồng quý mến các du khách thập phương.', '3 tháng 4, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'The Baobab Republic', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/26/f9/1e/1a/leethebaobab.jpg?w=100&h=-1&s=1', 3, 'Trước hết, chúng tôi không nhận được thái độ chào đón ở lối vào. Thứ hai, hầu hết mọi người đều cần mua vé cho tour club club, hoặc xe đạp nếu bạn muốn khám phá toàn bộ điều.Chúng tôi không thấy bất kỳ thái độ phục vụ chuyên nghiệp nào thông qua tất cả các nhân viên. Ngày chúng tôi đến, có một số công trình nhỏ mà chúng tôi có thể hiểu nhưng chúng tôi đã thấy một vài kẻ gây ồn ào xung quanh với những chiếc xe đạp thể thao trần trụi của họ.Vườn dâu tây rất nghèo.Nếu bạn không có nhiều thời gian ở Mộc Châu, tốt hơn hết là bỏ qua món ngon này.', '24 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Evie P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/d0/68/63/avatar.jpg?w=100&h=-1&s=1', 2, 'Nếu bạn đang tìm kiếm vẻ đẹp thiên nhiên, đừng đến nơi này. Nó có những thứ cho du lịch đại chúng: một hồ nước ở trung tâm, một ngôi nhà nhỏ để nuôi sữa bò (sữa được vắt từ bò và nấu để phục vụ), trang phục cho thuê và chụp ảnh, một vườn dâu tây và một ngôi nhà để uống từ dâu tây (sữa chua là rất tốt mặc dù).', '7 tháng 6, 2019', CURRENT_TIMESTAMP);

