    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roam22540032652', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/0a/default-avatar-2020-35.jpg?w=100&h=-1&s=1', 1, 'Trải nghiệm rất tệ. Mình ăn tối qua, món thắng cố vừa dai vừa không tươi, có tí thức ăn, xin miếng chanh thì mãi ko lấy ra mặc dù quán không hề đông cuối cùng mình đành bỏ dở bát mì tôm vì quá mặn', '1 tháng 5, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
