    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'JeremyBlues', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/be/6d/42/jeremybe3063ag.jpg?w=100&h=-1&s=1', 5, 'Tinh hoa ẩm thực Tây Bắc. Chúng tôi có buổi tối thứ 2 của mình ở Mộc Châu. Cùng món Gà Nướng Lu và Xôi... Món ăn đặc sắc của quán mang hương vị đặc trưng của núi rừng Tây Bắc, Món ăn rất ngon, giá cả hợp lý. Nếu có cơ hội nhất định chúng tôi sẽ còn quay trở lại', '14 tháng 3, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Khánh Linh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/97/73/bb/caption.jpg?w=100&h=-1&s=1', 5, 'Gà nướng lu giòn thơm. Gà nướng lu bán nguyên con 250.000đ có gồm cả xôi ăn kèm. Mình đi 2 người gọi 1 gà nướng lu thêm 1 đĩa su su xào. Gà ăn giòn ngọt thịt, xôi dẻo, thơm, rau tươi ngon. Lần tới đến Mộc Châu mình sẽ quay lại quán này 🤤', '17 tháng 8, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phạm D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/32/default-avatar-2020-12.jpg?w=100&h=-1&s=1', 5, 'Mộc Châu là một mảnh đất mà câc bạn rất nên đến một lần trong đời. Không khí trong lành sạch sẽ, cảnh đẹp tự nhiên. Đồ ăn của nhà Hàng Tuân Gù rất ngon và nóng hổi, phong cách phục vụ chuyên nghiệp, giá cả rất hợp lý', '27 tháng 3, 2018', CURRENT_TIMESTAMP);

