    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Navigator36500651529', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 5, '…….trải nghiệm tuyệt vời tại mộc châu”””””””””””””. Quán ăn ngon chủ quán nhiệt tình giá thành hợp lí mỗi lần đến mộc châu nhất định sẽ ghé quán ủng hộ 💐💐💐💐💐💐💐💐💐💐💐💐', '3 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trần Cường Hà Nội', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/66/default-avatar-2020-53.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng ngon Mộc Châu. Nhà hàng có thực đơn phong phú, đầy đủ các đặc sản của Mộc Châu: bê chao, cá suối, lợn cắp nách, trâu các món, lẩu các loại ....hôm đấy chúng chọn chủ đề các món dân tộc Thái có gà nướng mắc khén, cá nướng, thịt gói lá nướng, rau thì toàn là loại rau rừng, canh bon nấu với đuôi bò, rất lạ lần đầu mới được ăn thấy rất ngon, ấn tượng với món xôi ngũ sắc thật đẹp mắt mà ăn thì xôi dẻo và thơm mùi lá. Nói chung là vote cho nhà hàng 5 sao vì đồ ăn ngon và phục vụ nhiệt tình', '3 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cải bông', NULL, 5, 'Nhà hàng bê chao ngon. Đến Mộc Châu vào những ngày trời sang thu se lạnh, chúng tôi tìm đến nhà hàng Đông Hải và chọn món lẩu bê sữa, đây thực sự là món ăn ngon có 102, rất ngon, thịt bê mềm ngọt, chế biến rất nhiều món ăn ngon ko hề ngán.Thực sự chấm điểm 10 cho món lẩu bê này', '21 tháng 8, 2019', CURRENT_TIMESTAMP);

