    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/1b/b1/ca/img20190410125528-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'hiep h', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 4, 'Quán cá hồi 64 mộc châu - Moc Chau 64 salmon restaurant. Cá hồi được nuôi ở khu vực lân cận và được Quán chế biến thành nhiều món khá ngon. Ngoài cá hồi, Quán còn có nhiều món ăn khác cũng rất tuyệt vời . Giá cả ko mắc, nên ghé để ăn trưa hoặc tối trên đường đi Sơn La nếu bạn còn cách xa trung tâm thành phố Sơn La.
Salmon is farmed in the surrounding area and processed into many delicious dishes by the Restaurant. In addition to salmon, the Restaurant  is also has many other great dishes. Price is not expensive, so stop by for lunch or dinner on the way to Son La if you are still far from Son La city center', '16 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hà Local Việt Nam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/07/73/09/d1/ha-p.jpg?w=100&h=-1&s=1', 4, 'Vị trí thuận lợi - đồ ăn ngon. Trên đường từ Hoà Bình qua Sơn La, đoàn dừng lại ăn trưa trước khi di chuyển về khách sạn. Bãi đậu xe rộng rãi, nhà vệ sinh sạch sẽ và quan quan trọng là đồ ăn ngon. 
Nói chung là hài lòng. Ở đây cũng bán mấy loại rượu khá ngon ví dụ như táo mèo áo ba kích. Có thể mua về làm quà', '10 tháng 4, 2019', CURRENT_TIMESTAMP);

