    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'phang anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/a7/b3/87/caption.jpg?w=100&h=-1&s=1', 5, 'Tắm khoáng và leo núi là hai hoạt động nổi bật gại Trạm Tấu với nhiều khu suối khoáng nóng tự nhiên và đây là nơi bắt đầu của chân Núi Tà xùa, Tà chì Nhù và Samu. Một nơi rất đáng để trải nghiệm', '11 tháng 4, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Michal U', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 4, 'Đối tác đáng tin cậy để điều phối chuyến thăm của bạn tại Việt Nam', '7 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'lucky s', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'Tôi đã đi tour 4 ngày để thực hiện vòng lặp Hà Giang vào tháng 12 năm 2019. Chỉ từng lái một chiếc xe tay ga trở về nhà, tôi quyết định rằng sẽ tốt hơn nếu thuê một người lái dễ dàng đưa tôi đi khắp nơi - và đó là quyết định tốt nhất tôi có thể đưa ra. Hạnh phúc là một người hướng dẫn / bạn đồng hành tuyệt vời, người đảm bảo tôi có trải nghiệm tốt nhất mà khu vực tuyệt vời này có thể mang lại. Nhiều lúc con đường rất sơ sài, đầy lỗ hổng và chật hẹp, nhưng tôi luôn cảm thấy an toàn khi ngồi trên lưng, chụp ảnh và là một khách du lịch vô tư. Nhìn chung một chuyến đi tuyệt vời! !', '6 tháng 1, 2020', CURRENT_TIMESTAMP);

