    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/01/b3/eb/caption.jpg', 0, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hà Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 5, 'Chuyến này đi công tác ghé đây ở thích ghê, mấy cái chăm chút nhỏ nhỏ thôi mà làm mình thấy thoải mái hẳn. Buổi sáng ra khu sân vườn làm tách cà phê tươi ngon bất ngờ luôn. Sau một ngày làm việc túi bụi, tối về đây nghỉ ngơi đúng kiểu giải tỏa căng thẳng.', '17 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'My Lam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Một địa điểm nhỏ nhắn và vô cùng ấm cúng. Đi du lịch một mình nên tôi cực kỳ thích không gian tách biệt khỏi sự xô xập phố thị ở đây. Ngay từ khoảnh khắc mới bước vào, tôi đã cảm nhận được sự bình yên, cuối cùng cũng có thể sống chậm lại và tận hưởng trọn vẹn những phút giây yên tĩnh đúng nghĩa.', '16 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thích vi vu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Minh cực kỳ thích thiết kế mộc mạc của căn bungalow. Nơi đây thật yên tĩnh, riêng tư và hoàn hảo để nạp lại năng lượng.', '11 tháng 8, 2026', CURRENT_TIMESTAMP);

