    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/29/5f/6c/photo0jpg.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/40/14/a9/photo2jpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/29/5f/72/photo4jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Erbus22', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 5, 'Ôi ...!. Nhà hàng này là một nơi đáng yêu.
nhân viên siêu thân thiện và luôn tìm kiếm khách và sự thoải mái của nó.
chúng tôi cảm thấy thực sự hài lòng và không thể ăn nhiều hơn thậm chí tôi ước có thêm một khoảng trống trong bụng. . . .
tất cả thức ăn được chuẩn bị mới bởi đầu bếp trên bàn.

chắc chắn đây là nơi tốt nhất cho bbq ở đây

Cảm ơn bạn rất nhiều vì những món ăn tuyệt vời và dịch vụ tuyệt vời. . . . hạnh phúc hạnh phúc hạnh phúc', '22 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'euromat', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/02/3c/a2/f5/avatar.jpg?w=100&h=-1&s=1', 5, 'Cũng đáng để ghé thăm!. Một tìm kiếm nhỏ đáng yêu, mặc dù không theo bản đồ tripadvisor để tìm nó
Bạn sẽ không! ! Tôi đã thêm một bức ảnh của khách sạn mà nó nằm ngay bên cạnh. BBQ mà bạn tự nấu ăn tại bàn, một lựa chọn tốt của các loại thịt và salad, và ở một mức giá tuyệt vời quá!', '2 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sin J', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Nơi tuyệt vời cho bữa tối. Một nơi tuyệt vời cho bữa ăn tối với tất cả các bạn có thể ăn buffet. Tiệc tự chọn BBQ Hàn Quốc đi kèm với lẩu Việt Nam. Nhân viên tuyệt vời có thể nói song ngữ bằng cả tiếng Anh và tiếng Trung. Họ thậm chí còn cung cấp để nấu cho chúng tôi vì đây là lần đầu tiên chúng tôi thử BBQ Hàn Quốc. Với giá 150000 đồng / người. Nơi này chắc chắn sẽ làm hài lòng tất cả cảm giác thèm thịt của bạn. Bầu không khí ở đây cũng ấm lên, mọi thứ có vẻ sạch sẽ và có tổ chức. Nơi sạch sẽ và hương vị thức ăn tuyệt vời. Quan trọng nhất là nó được phục vụ tươi!', '7 tháng 8, 2017', CURRENT_TIMESTAMP);

