    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/19/5e/79/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/19/5e/78/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phạm Thị Thu Hiền', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Không khí trong lành, mát mẻ đã giúp tôi thư giãn và tận hưởng những ngày nghỉ tuyệt vời. Mình bị ấn tượng mạnh bởi vẻ đẹp hoang sơ của những bản làng nhỏ. Cảnh vật hữu tình, yên bình khiến tôi cảm thấy như lạc vào một thế giới khác, tách biệt hoàn toàn với sự ồn ào của thành phố. Được trải nghiệm cuộc sống thường ngày của người dân bản địa, thưởng thức các món ăn đặc sản và tìm hiểu về văn hóa truyền thống của người Thái là những trải nghiệm đáng nhớ nhất trong chuyến đi.', '29 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Explorer68504669636', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/6a/default-avatar-2020-47.jpg?w=100&h=-1&s=1', 5, 'Bản Lác là một điểm đến hấp dẫn đặc biệt là với những ai muốn trải nghiệm văn hoá dân gian hoà mình vào thiên nhiên thích cảm giác trong lành , tuy nhiên nếu bạn là người tìm kiếm sự yên tĩnh tuyệt đối hoặc dịch vụ cao cấp thì nơi này có thể không phù hợp hoàn toàn', '29 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Minh Phương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 4, 'Mai Châu và những điều thú vị', '29 tháng 11, 2024', CURRENT_TIMESTAMP);

