    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/ca/aa/f8/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/ca/aa/f6/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Namphuctourist', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0e/c1/ee/30/namphuctourist.jpg?w=100&h=-1&s=1', 5, 'Hang Chiều tại thị trấn Mai Chau, ở độ cao 1200 bậc. Đường vào hang rất đẹp. Những người khỏe mạnh và thích mạo hiểm mới đến! Một trải nghiệm không dễ quên!', '4 tháng 12, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Angie', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/51/2a/55/caption.jpg?w=100&h=-1&s=1', 5, 'Chinh phục những bước đó và xem xét số giờ của bạn được bấm giờ? /Khá thú vị và khi bạn đến gần lối vào của các hang động, chỉ cần nhìn lại và chiêm ngưỡng khung cảnh đẹp như tranh vẽ của Mai Châu. Các hang động khá mát mẻ, chỉ cần chú ý đến những con đường lầy lội và trơn trượt khi trời mưa trước đó.Chỉ cần chuẩn bị để có được một bản chất lil trong tay và chân của bạn. Nếu không thì một cuộc đi bộ khá thú vị! ! ! ! ! Rất thích nó hehe', '2 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Harry H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/73/default-avatar-2020-13.jpg?w=100&h=-1&s=1', 4, 'Có rất nhiều bước. . . rất nhiều. . . . nó có thể rất nóng vào mùa hè, vì vậy có thể lên kế hoạch cho buổi sáng hoặc buổi chiều. Một khi bạn lên đến đỉnh hang thì lạnh. Điểm nổi bật là khung cảnh của thung lũng.', '29 tháng 5, 2019', CURRENT_TIMESTAMP);

