    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/15/ff/a3/m-t-d-a-di-m-r-t-dang.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'vietrapro', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/21/85/40/46/vietrapro-t.jpg?w=100&h=-1&s=1', 5, 'Thung Khe pass is one of the most interesting stops on the road to Mai Chau and Moc Chau. The pass''s beautiful white appearance, as well as friendly ethnic minority sellers, attracts tourists(Một trong những điểm dừng chân hấn dẫn trên hành trình đến Mai Châu và Mộc Châu đó chính là đèo Thung Khe. Vẻ đẹp trắng toát của con đèo cũng như sự thân thiện của những người bán hàng dân tộc thiểu số đã thu hút du khách)', '13 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Thị Thùy Linh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Điểm nghỉ giữa đường khi đi Hòa Bình rất tuyệt. Có mấy món như ngô nướng, thịt xiên, trứng nướng là mấy món quá ngon. Giá lại rẻ.', '20 tháng 5, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hà Ngô 🌽', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ed/00/default-avatar-2020-4.jpg?w=100&h=-1&s=1', 5, 'Điểm dừng chân không thể bỏ qua khi bạn lên Mai Châu hoặc Mộc châu. Ở đây bán rất nhiều đồ ăn từ các cây trồng của người dân tộc. View phía sau cũng rất đẹp. Đồ ăn củng rẻ nữa.Vừa ăn vừa view thung lũng phía dưới đúng thật tuyệt vời 👍', '19 tháng 5, 2021', CURRENT_TIMESTAMP);

