    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nhu Tran Van', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 3, 'Đường đến thác Gò Lào rất đẹp với các cây tre luồng bao phủ. Thác nước khá cao, nhưng nhỏ. Gần khu thác, nếu có 1 quán nhỏ bán nước hoặc đồ ăn nhẹ sẽ tiện cho du khách hơn', '18 tháng 1, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'sonha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/68/default-avatar-2020-9.jpg?w=100&h=-1&s=1', 5, 'chúng tôi đi xe khách lên có dừng chân ở đèo đã trắng , khung cảnh rất đẹp, Thác gò lào rất đẹp, bạn nên mang đồ bơi khi có ý định đi thăm Thác Gò Lào.', '19 tháng 8, 2019', CURRENT_TIMESTAMP);

