    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/47/ba/4e/inside.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'AugereauBui', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/79/42/b8/caption.jpg?w=100&h=-1&s=1', 5, 'Do ở đây là họ khai thác đá, cát để làm xi măng cho nên là vào buổi nhiều những chiếc xe tải, xe bồn họ rửa những phần còn lại trong xe nên là nước xi măng trắng nó chảy ra kết hợp với việc khai thác đá nên đã tạo ra một hình ảnh đặc trưng của còn đèo này nên người ta gọi nó là Đèo Đá trắng. Bên dưới đèo là thung lũng Mai Châu bà xa xa là cánh đồng lúa Mai Châu.', '17 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 5, 'Đèo đá trắng là điểm dừng chân của các phượt thủ. Nhìn từ xa đèo trông như thác nước. Đây là điểm chụp ảnh rất tuyệt. Khu vực nghỉ chân có những quán nhỏ của đồng bào dân tộc với những món ngon đậm hương vị Hoà Bình như cơm lam, thịt nướng. Mình rất thích đèo đá đặc biệt này.', '10 tháng 5, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Erik Hoang, Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/61/e3/6b/caption.jpg?w=100&h=-1&s=1', 5, 'Không phải lần đầu đến với mây trời Tây Bắc. Nhưng vẫn thấy choáng ngợp trước nơi đây. Núi mờ sương, đèo cua tay áo. Việt Nam đẹp quá !!!', '14 tháng 9, 2019', CURRENT_TIMESTAMP);

