    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/b1/6c/18/mai-chau-home-restaurant.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thanh Hoà N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/32/default-avatar-2020-12.jpg?w=100&h=-1&s=1', 5, 'Cửa hàng thổ cẩm Hoa Ban là một điểm đến tuyệt vời cho những ai yêu thích sản phẩm thủ công độc đáo. Tại đây, bạn sẽ tìm thấy nhiều mẫu mã phong phú, từ khăn, túi xách đến trang phục, tất cả đều được làm từ chất liệu thổ cẩm truyền thống và mang đậm bản sắc văn hóa. Nhân viên phục vụ rất nhiệt tình và am hiểu về sản phẩm, giúp khách hàng có những lựa chọn phù hợp nhất. Giá cả hợp lý so với chất lượng, khiến cho việc mua sắm trở nên thú vị hơn. Không gian cửa hàng được bài trí đẹp mắt, tạo cảm giác gần gũi và ấm cúng. rất ấn tượng với trải nghiệm mua sắm tại đây và chắc chắn sẽ quay lại để khám phá thêm nhiều sản phẩm mới.', '9 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Culture27529753641', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Cửa hàng thổ cẩm Hoa Ban mang đến nhiều sản phẩm độc đáo và đa dạng. Chất lượng sản phẩm ở đây rất tốt, với những món đồ được làm thủ công tinh xảo và đẹp mắt. Nhân viên phục vụ thân thiện và chu đáo, luôn sẵn sàng tư vấn để khách hàng tìm được sản phẩm phù hợp. Mức giá tại cửa hàng cũng khá hợp lý, phản ánh đúng giá trị của sản phẩm. Không gian cửa hàng ấm cúng và dễ chịu, tạo cảm giác thoải mái khi mua sắm. Tổng thể, tôi rất hài lòng với trải nghiệm tại cửa hàng thổ cẩm Hoa Ban và chắc chắn sẽ quay lại để khám phá thêm nhiều sản phẩm thú vị.', '9 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thành Mai Châu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 4, 'Một nơi nên đến, để khám phá và tìm hiểu về cuộc sống và con người nơi đây, rất thân thiện, yên bình!', '8 tháng 12, 2018', CURRENT_TIMESTAMP);

