    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/34/1f/8e/thai-s-travel-bus.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Gard S', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/4d/f7/c3/avatar.jpg?w=100&h=-1&s=1', 5, 'Tôi bắt xe buýt từ Mai Châu đến Tam Cốc và có một chuyến đi dễ chịu. Tôi đã được chọn ngay bên ngoài homestay của tôi và rơi ngay bên ngoài ký túc xá tiếp theo của tôi. Các ổ đĩa đã thoải mái và đúng giờ, không có gì để chỉ trích.Tôi nhận ra mình đã quên một số quần áo tại nhà trọ ở Mai Châu khi tôi đến. Vì vậy, homestay của tôi đã sắp xếp với công ty này để gửi nó với chiếc xe buýt tiếp theo. Người lái xe (Thái / Tai?) Đã đủ hào phóng để làm điều đó, miễn phí (thậm chí từ chối bất kỳ tiền boa nào). Anh ấy gọi cho tôi để đảm bảo tôi ở đúng vị trí và không có rào cản ngôn ngữ. Sau khi gặp nhau, chúng tôi đã có một cuộc trò chuyện thú vị về trà và anh ấy chở tôi về ký túc xá của tôi sau đó.Dịch vụ tuyệt vời và tiết kiệm trong ngày của tôi.', '24 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jurjan Scheper', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 5, 'Giao tiếp và vận chuyển hoàn hảo! Ông Hà nói tiếng Anh rất tốt và trả lời rất nhanh. Tôi chắc chắn đề nghị dịch vụ của mình! !', '22 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Andy_James142', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2e/70/67/avatar045.jpg?w=100&h=-1&s=1', 5, 'Hôm nay chúng tôi đi từ Ninh Bình đến Mai Châu ở miền Bắc Việt Nam.Chỉ có 3 chúng tôi trong chuyến đi. Chúng tôi rời đi lúc 2 giờ 30 chiều và đến lúc 6 giờ 30 chiều. Chúng tôi lờ mờ sau hai nhân viên: tài xế và hướng dẫn viên xe buýt tên là "người Thái". Người lái xe rất xuất sắc và ngay cả trên những con đường dốc, chúng tôi đã yên tâm. Thái cũng xuất sắc. Anh ấy mời chúng tôi trà xanh và pomello ở điểm 1/2.Điều này có thể không xảy ra trong mỗi chuyến đi nhưng người Thái đã thả chúng tôi tại chỗ ở của chúng tôi ở Mai Châu và thậm chí còn mang túi của chúng tôi đến quầy tiếp tân. Dịch vụ của anh ấy rất nổi bật. Tôi hy vọng tôi có cơ hội để đặt xe buýt của mình một lần nữa.', '26 tháng 9, 2019', CURRENT_TIMESTAMP);

