    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Explorer39395890682', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/9c/default-avatar-2020-14.jpg?w=100&h=-1&s=1', 5, 'Bó Luông - Vừa được ăn ngon! Vừa được chơi vui!. Món ăn ngon, đầy đặn, bày trí đẹp. Nhân viên niềm nở. View xanh mát từ hồ Mỏ Luông. Hãy đến Bó Luông để thử ngay cơm mẹt Thái, vừa thưởng thức ẩm thực, vừa giao lưu văn nghệ truyền thống, uống chén rượu cần ấm lòng', '4 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Curiosity67776657240', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Cơm ngon, dịch vụ tốt!. Cơm ngon, dịch vụ tốt, view lại thoáng mát, bày trí ấm cúng. Nhà hàng có mở lớp học nấu ăn hoặc các show giao lưu văn nghệ theo nhu cầu của thực khách', '18 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'An Le', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Cơm nhà "NGON" tại Nhà hàng Bó Luông. Chúng tôi đã có 1 trải nghiệm ẩm thực tuyệt vời tại nhà hàng Bó Luông. Chúng tôi chọn set mẹt truyền thống gồm có: Cá nướng sả ớt, lợt bản nướng, rau cải luộc chấm trứng, canh khoai sọ, cơm lam...các món đều tròn vị, bày trí đẹp mắt. Điểm cọng cho sự nhiệt tình, thân thiện của nhân viên và view hồ cực chill. Very good!', '29 tháng 4, 2026', CURRENT_TIMESTAMP);

