    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Escape47667032508', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 1, 'Thái độ của chủ quán không tốt. Thực phẩm thì không tươi và thái độ phục vụ kém', '21 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'the2thattravel', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/43/a1/4f/the2thattravel.jpg?w=100&h=-1&s=1', 5, 'Viên ngọc ẩn trong Mai Chay. Chúng tôi yêu thích các món ăn ở đây, nhưng kinh nghiệm của chúng tôi với hai chị em chúng tôi gặp nhau nhiều hơn. Mặc dù chúng tôi không thể hiểu nhau, nhưng thật tuyệt vời với những gì bạn có thể cảm nhận được từ nụ cười ấm áp và thái độ tốt bụng của ai đó. Chắc chắn giá trị một chuyến thăm nếu bạn đang ở Mai Châu! Tùy chọn ăn chay cũng rất ngon!', '20 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Alicia M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/a5/1c/45/alicia-h.jpg?w=100&h=-1&s=1', 5, 'Thực phẩm tươi và dịch vụ tuyệt vời!. Chúng tôi ở Mai Châu hai ngày và chúng tôi ăn ở Quan 3 Chi Em cả hai ngày. Chúng tôi sẽ quay lại lần thứ ba nếu có nhiều thời gian hơn! Các món ăn đã được DELICIOUS. Rất tươi và mọi thứ được nấu theo đơn đặt hàng. Hãy kiên nhẫn và nó rất đáng giá. Nhân viên rất ân cần và nhiệt tình. Họ luôn mỉm cười và khiến chúng tôi cảm thấy được chào đón. Thức ăn được phục vụ rất nóng và rất tươi. Tất cả mọi thứ chúng tôi đã cố gắng trên cả hai chuyến thăm đều tuyệt vời. Nếu chúng tôi quay lại Mai Châu, chúng tôi chắc chắn sẽ ăn ở đây một lần nữa! Cảm ơn những trải nghiệm tuyệt vời!', '15 tháng 1, 2020', CURRENT_TIMESTAMP);

