    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Guide16504623619', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Một địa điểm tuyệt vời để tìm hiểu về lịch sử và văn hóa của 54 dân tộc anh em tại Việt Nam. Bảo tàng được thiết kế khoa học, với các hiện vật trưng bày sống động và khu vực ngoài trời mô phỏng các công trình kiến trúc truyền thống. Nhân viên thân thiện, nhiệt tình, không gian sạch sẽ và thoáng đãng. Đây là điểm đến lý tưởng cho gia đình, học sinh, và du khách yêu văn hóa. Rất đáng để ghé thăm!', '6 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lynk Nee', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/77/bd/a0/linhlil.jpg?w=100&h=-1&s=1', 4, 'Bảo tàng trưng bày nhiều hiện vật phong phú, từ trang phục, nhạc cụ đến các công cụ lao động truyền thống, giúp du khách hiểu rõ hơn về đời sống và phong tục tập quán của từng dân tộc. Không gian rộng rãi và thoáng đãng, với nhiều khu trưng bày ngoài trời, tạo cảm giác gần gũi với thiên nhiên. Các hoạt động giao lưu văn hóa diễn ra thường xuyên, mang đến trải nghiệm sống động và thú vị. N', '20 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tracy Dieu Thu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, 'Một địa điểm đáng để đến, đa dạng văn hoá, khung cảnh đẹp, yên bình.Đến đây hiểu sâu về các dân tộc của nước ta và có nhiều mô hình thực tế để ngắm nhìn', '2 tháng 3, 2023', CURRENT_TIMESTAMP);

