    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Julie C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Đó là một nơi yên tĩnh, nơi bạn có thể ngồi thiền, học nấu ăn Việt Nam nếu bạn quan tâm, chỉ làm một việc với Thiên nhiên, đốt lửa trại. Tôi thực sự tận hưởng thời gian của mình với gia đình Nông Nông ở giữa những cánh đồng chè. Tôi giới thiệu thác Cửa Tử để có những người bạn vui vẻ và mới?', '6 tháng 12, 2019', CURRENT_TIMESTAMP);
