    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/d0/a0/b5/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Du Lịch Thái Nguyên', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/41/7e/35/dulichthainguye.jpg?w=100&h=-1&s=1', 5, 'Suối Đá Cổng là một điểm du lịch kỳ thú và hấp dẫn, thuộc sườn đông Tam Đảo. Đây là một trong những điểm đến không thể bỏ qua khi du khách muốn tìm hiểu và khám phá vẻ đẹp thiên nhiên hùng vĩ của Việt Nam.Điều đặc biệt ở suối Đá Cổng là những điều bất ngờ mà nó mang lại cho du khách. cho đến những bậc đá cheo leo trên suối , mỗi bước chân đều đem lại những trải nghiệm mới mẻ và thú vị. Suối đá cổng không chỉ là một điểm du lịch mà còn là nơi để du khách tìm lại sự bình yên, hòa mình vào thiên nhiên và tận hưởng không khí trong lành.Với sự kỳ vĩ và vẻ đẹp tự nhiên không thể chối từ, suối đá cổng chắc chắn sẽ là một điểm đến lý tưởng cho những ai yêu thích khám phá và trải nghiệm.', '11 tháng 7, 2024', CURRENT_TIMESTAMP);

