    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thuy An', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'Trải nghiệm đáng nhớ tại Làng nhà sàn Thái Hải. Một nơi tuyệt vời để khám phá văn hóa Tày giữa thiên nhiên xanh mát. Nhà sàn truyền thống, ấm cúng, món ăn ngon và đậm bản sắc địa phương. Tôi rất ấn tượng với sự thân thiện của người dân và chuyến thăm quan tìm hiểu về bản làng rất ý nghĩa . có cả ăn uống, ngủ nghỉ tiện nghi và các hoạt động trải nghiệm. có thể đi cá nhân hay nhóm lớn đều được. Rất đáng để quay lại!', '25 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'chasemarta', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 4, 'Nơi thú vị. Đây là một khu phức hợp rất lớn giúp mọi người hiểu về văn hóa dân tộc của người Thái Hải.
Rất nhiều học sinh Việt Nam đến đó và nghỉ đêm và tận hưởng khu phức hợp rộng lớn.
Chúng tôi chỉ dừng lại để ăn trưa. Thức ăn rất tuyệt và đó là một trải nghiệm thú vị.
Chúng tôi đã có một hướng dẫn đó là tuyệt vời', '13 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'George B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/14/f1/7f/thai-hai-tay-ethnic-village.jpg?w=200&h=200&s=1', 5, 'Phải ghé thăm!. Một trong những ngày thú vị nhất mà tôi đã có ở Châu Á.
Mọi người nên ghé thăm nơi này để tìm hiểu về văn hóa địa phương ở đây.
Hướng dẫn thật tuyệt!', '20 tháng 11, 2019', CURRENT_TIMESTAMP);

