    VALUES (gen_random_uuid(), v_place_id, 'Tue Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ba/5e/d9/caption.jpg?w=100&h=-1&s=1', 5, 'Chùa Tam Thanh Lạng Sơn – tuyệt đẹp! Nằm trong động Tam Thanh, chùa mang vẻ cổ kính, huyền bí, xứng danh “đệ nhất bát cảnh xứ Lạng”. Tượng A Di Đà tạc vào vách đá thế kỷ 15, hồ Âm Ti trong xanh, nhũ đá độc đáo, không gian thanh tịnh. Lễ hội rằm tháng Giêng náo nhiệt, rước kiệu Ngô Thì Sĩ, văn bia cổ giá trị. Điểm đến tâm linh và chụp ảnh tuyệt vời', '11 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'FromVietnam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/b2/b4/c7/fromvietnamasia.jpg?w=100&h=-1&s=1', 4, 'chùa và động tam thanh ở tỉnh lạng sơn khá đẹp. chùa nằm trong hang động. trong hang động có lối lên lầu vọng cảnh ngăm nàng tô thị khá hay.vé thăm quan 20k/ người', '5 tháng 8, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Akira Giang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Chùa Tam Thanh nằm bên trong  động Tam Thanh, ngoài ra chùa còn có một tên gọi khác là chùa chùa Thanh Thiền. Động Tam Thanh là quần thể di tích danh thắng gồm Nhị-Tam Thanh – Núi Tô Thị – Thành Nhà Mạc.Sở dĩ có cái tên chùa Tam Thanh là vì ngày xưa, nơi đây thờ tự Đạo Giáo, thờ Tam Thanh (Ngọc Thanh, Thượng Thanh, Thái Thanh)Vào ngày 15 tháng Giêng, hội chùa Tam thanh diễn ra với nhiều nghi lễ, tập tục truyền thống của người dân xứ Lạng.', '27 tháng 1, 2020', CURRENT_TIMESTAMP);

