    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 4, 'Một nơi mà người đến Lạng Sơn cần phải đến. Hang rộng rãi, mát mẻ, sạch sẽ và cũng rất đẹp. Mọi thứ đều nguyên sơ. Ít thay đổi do con người .Xứng đáng là một nơi dành cho những người yêu thích thiên nhiên.', '21 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Langbam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/39/ce/b4/avatar.jpg?w=100&h=-1&s=1', 4, 'Hang động gắn liền với danh nhân Ngô Thì Sỹ, ông là người phát hiện và cho tu sửa, tôn tạo thành nơi du ngoạn vào tháng 5/1779. Ðộng khá rộng, có nhiều ngóc ngách, nhiều nhũ đá rơi xuống muôn hình vạn dạng. Từ cửa động chính nhìn lên là ngôi chùa Tam Giác thờ cả Khổng Tử, Lão Tử, Thích Ca. Trong động có tượng truyền thần Ngô Thì Sĩ tạc vào vách đá và trên vách động còn ghi nhiều bài ký phú của ông và các danh nhân khác.Điểm tham quan hấp dẫn khi đến với Lạng Sơn.', '11 tháng 9, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'heinzhuynh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/07/fa/2a/fb/heinzhuynh.jpg?w=100&h=-1&s=1', 3, 'Chuyến đi khứ hồi của tôi từ Hà Nội đến Đông Bắc rồi Mad dừng lại một đêm ở làng lang.Vì vậy, tôi ghé thăm đây. kết hợp với Tam Thanh. Đây cũng là một nhỏ và chúng tôi đi vào bên trong cho một số hình ảnh. Đó là nó', '6 tháng 7, 2018', CURRENT_TIMESTAMP);

