    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'An Nhi', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'Little pie. Như bước vào một khu vườn, cực kì mê 🤤. Cây xanh ở khắp nơi, từng ngóc ngách của quán, đó là ấn tượng đầu. Rồi bên trong được bày trí theo phong cách vintage. Điểm cộng là có cả chó mèo :> Nói chung là chủ ở đây rất thích động vật, yêu thiên nhiên. Ai đến cũng có thể cảm nhận được hết. Nhẹ nhàng, tinh tế. Đồ ăn, đồ uống, phục vụ khiến mình rất hài lòng. Chắc chắn sẽ còn quay lại nữa 🥰 #baovemoitruong', '16 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
