    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'tony', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'địa điểm đẹp
không khí ấm áp
giòn ngon
đến đây một ngày nắng và chỉ muốn một nơi im lặng để uống cà phê nhưng những gì tôi. giòn ngon
đến đây một ngày nắng và chỉ muốn một nơi yên tĩnh để uống cà phê nhưng những gì tôi thấy thật là mê hoặc', '20 tháng 8, 2019', CURRENT_TIMESTAMP);

