    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/32/03/d5/00/staircase-space-at-the.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lê Hồng Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 4, 'Hang động đẹp với nhiều cấu tạo tự nhiên hàng trăm năm. Tuy nhiên thì bị can thiệp nhiều quá nên mất đi nhiều sự tự nhiên', '14 tháng 4, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DRW44', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/8d/f8/6f/drw44.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đã đi du thuyền 4 giờ quanh Vịnh Hạ Long, bao gồm cả bữa trưa, được tổ chức như một phần của hành trình trên sông Viking. Đến cuối hành trình, chúng tôi đã ghé thăm khu phức hợp Hang Vàng tuyệt vời không kém - những hang động đồ sộ với tất cả các măng đá, măng đá và những tảng đá tuyệt vời mà bạn mong muốn. Chắc chắn không tàn tật thân thiện nhưng tốt, bước vững chắc trong suốt. Nó có thể là điểm nổi bật của kỳ nghỉ, nhưng, chỉ là ngày thứ 2, chỉ có thời gian mới trả lời.', '20 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'yv', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/25/02/9a/vonnyyvng.jpg?w=100&h=-1&s=1', 5, 'Mẹ thiên nhiên đơn giản là tuyệt vời, nó rất hấp dẫn khi chứng kiến hang động và bên trong trông như thế nào. Hang động thực sự khá lớn nên bạn có thể dành thời gian từ từ chiêm ngưỡng các cấu trúc và vẻ đẹp của thiên nhiên.', '17 tháng 12, 2019', CURRENT_TIMESTAMP);

