    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/32/03/d5/00/staircase-space-at-the.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Việt', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Trung tâm mua sắm thật sự ấn tượng . Đầu tiên, vị trí của trung tâm rất thuận tiện, nằm ngay giữa trung tâm thành phố,  vị trí thuận lợi, mà còn là sự đa dạng của cửa hàng và thương hiệu. Từ các cửa hàng thời trang hàng đầu đến những thương hiệu. Chất lượng sản phẩm. Nhân viên phục vụ rất thân thiện và nhiệt tình. Họ luôn sẵn lòng hỗ trợ và giúp đỡ khách hàng trong mọi tình huống .', '20 tháng 4, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Yangyang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f6/0d/default-avatar-2020-34.jpg?w=100&h=-1&s=1', 5, 'Các hang động được bảo tồn tốt đáng kinh ngạc. Những người trong tour của tôi đã cư xử rất tốt và tuân thủ các quy tắc. Chúng tôi nhóm lại với nhau và trekked toàn bộ hang động. Quan điểm tại TOP là giá trị leo lên. Các bước đã không đặc biệt dốc.', '8 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kevin A', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Địa điểm đẹp với cảnh quan tuyệt đẹp.Một chuyến thăm xác định. Chúng tôi đã đi không quá đông.Trẻ em tuổi teen cũng thích nó', '22 tháng 12, 2019', CURRENT_TIMESTAMP);

