    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sotontraveller', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 4, 'Đây là những hang động tuyệt đẹp mà nhiều tàu thuyền đang dừng ở Vịnh Hạ Long dừng lại. Chúng đã được phát triển đáng kể để có đủ ánh sáng để thấy tất cả các hình dạng ấn tượng mà đá vôi đã tạo ra trong hơn 1000 năm. Không cần phải nói, nhiều người trong số họ đã được đặt tên. Lối đi bộ cũng được phát triển để phục vụ cho số lượng lớn khách truy cập, hiếm khi tập tin đơn lẻ và khá an toàn dưới chân. Có thể không tốt lắm nếu bạn không thoải mái đi bộ trong một giờ hoặc lâu hơn trong những trường hợp hơi khó khăn. Rất đáng để ghé thăm.', '26 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bridget M', NULL, 4, 'Chắc chắn rất thú vị mặc dù nó rất quan trọng để mang giày chân tốt hơn dép xỏ ngón, nhưng chỉ cần ra ngoài vịnh bằng thuyền kayak, vào thời điểm đó đã không nghĩ về điều này! Đã nói nó có thể rất bận rộn nhưng vào ngày thăm chỉ là bữa tiệc của chúng tôi với hàng tá.', '12 tháng 5, 2019', CURRENT_TIMESTAMP);

