    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Huong D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Tuyệt vời. Chúng tôi đã có hai lần trải nghiệm trong chuyến đi thăm Vịnh Hạ Long, đoàn chúng tôi có 45 người. Nhà hàng phục vụ rất nhiệt tình, chu đáo và ra món rất nhanh. Đặc biệt đồ ăn trang trí bắt mắt, nhân viên phục vụ rất nhiệt tình. Rất cảm ơn các bạn, đặc biệt là bạn Doan. Chúc nhà hàng Đại Dương Vàng 9999 luôn đông khách. Mãi yêu ❤️❤️❤️', '31 tháng 5, 2026', CURRENT_TIMESTAMP);

