    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/cc/89/48/img-20191020-wa0017-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Inspire57911835506', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 5, 'Very good restaurant. Đồ ăn rất ngon, nhiều đồ uống rất nìce, nhân viên vui vẻ nhiệt tình. Quán rất đông khách.  Rất hài lòng với quán và nhân nhiên', '5 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Camper56380811025', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, 'Tôi yêu quán nàyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy. Đồ ăn siêu ngonnnn
Giá cả hợp lý vô cùng
Anh nhân viên tên Nguyên quá cute
100/10 điểm 
Nên trải nghiệm thử ❤️❤️❤️❤️❤️❤️❤️❤️❤️', '21 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KINH Chef (Street Food K CORP VN)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/39/4d/ac/caption.jpg?w=100&h=-1&s=1', 4, 'Nhà Hàng Đức - kiểu Đông Âu tại Bãi Cháy - Hạ Long. Nhà hàng Papa BBQ là một địa điểm thực sự đặc biệt tại khu Phố Đi Bộ của Bãi Cháy - Hạ Long. Đã đến lúc bạn được thưởng thức đùi cừu phong cách chuẩn Đông Âu và tận hưởng một trải nghiệm ẩm thực đáng nhớ.

Đối với tôi, việc ghé thăm nhà hàng này là một hành trình ẩm thực thú vị. Không chỉ bởi vị trí tuyệt vời, mà còn bởi món Đùi cừu độc đáo và ngon miệng. Một điều đặc biệt về Papa BBQ là không gian của nhà hàng, mà không gian vườn ngoài trời xinh đẹp và trang trí theo phong cách chuẩn Đông Âu tạo ra một không gian lý tưởng cho bữa tối thư giãn và lãng mạn.

Đùi cừu tại Papa BBQ thật sự xuất sắc. Thịt mềm mịn và thơm ngon, nướng đúng điểm để giữ nguyên hương vị tự nhiên của thịt. Khi ăn kèm với bánh mì nướng và các loại gia vị đặc trưng, bạn sẽ thấy mình như đang ở tại một quán ăn tại Đông Âu. Đây là một trải nghiệm thú vị và độc đáo mà bạn không nên bỏ lỡ.

Nhà hàng không chỉ chú trọng vào chất lượng thực phẩm mà còn vào dịch vụ. Đội ngũ nhân viên tại đây thân thiện, nhiệt tình và luôn sẵn sàng đáp ứng mọi yêu cầu của khách hàng.

Nếu bạn là người yêu thực phẩm, đặc biệt là món Đùi cừu phong cách Đông Âu, thì Papa BBQ là điểm dừng chân lý tưởng. Đây là nơi để bạn thử một phần của chuẩn Đông Âu ngay tại Hạ Long và tạo ra những kỷ niệm ẩm thực đáng nhớ', '16 tháng 10, 2023', CURRENT_TIMESTAMP);

