    VALUES (gen_random_uuid(), v_place_id, 'Scenic08192539594', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng hải sản ngon. Sau khi mua hải sản ở tầng 1 thì bữa tối ở bàn tầng 2 rất ngon. Tôi đã ăn rồi, lần sau nếu quay lại thì dự định sẽ lại đến thăm', '20 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
