    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/89/f4/25/photo2jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trần Thanh Thảo', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 5, 'Đền Hùng là một nơi lý tưởng  để khám phá lịch sử và văn hóa ,  nơi    tâm linh và là  nơi tôn vinh các vị anh hùng và vua Hùng.  Được tham quan các đền thờ, đền thờ các vị anh hùng và vật phẩm linh thiêng, tham quan khu vực di tích. Ngoài ra cò được ăn các món ăn truyền thống', '4 tháng 12, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jake Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/e5/1d/30/viet-cuong-n.jpg?w=100&h=-1&s=1', 5, 'Tôi đã ở đây vào tháng 10 năm 2019, Đền thờ và tất cả các phần liên quan trong khu vực kỷ niệm Vua Hùng thật tuyệt vời, khám phá nơi này bạn có thể biết nhiều về văn hóa Việt Nam.', '9 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Tôi đến thăm di tích lịch sử này nhiều lần rồi. Mỗi lần đi đều để lại ấn tượng tốt đẹp trong tôi. Khung cảnh thiên nhiên hùng vỹ,thơ mộng, mát mẻ và sạch sẽ. Cây xanh tươi tốt và rất nhiều. Các Chùa chiền, đền thờ ,miếu mạo... Cổ kính và linh thiêng. Các dịch ra tương đối hợp lý về mặt hàng và giá cả. Nhân viên nhiệt tình và có trách nhiệm. Tôi sẽ đến viếng thăm khi nào có dịp. Mọi người hãy cố gắng đến Đền Hùng càng nhiều càng tốt. Rất tiếc cho những ai không thể nào đến nơi đây. Cảm ơn Đền Hùng Vương.', '7 tháng 5, 2019', CURRENT_TIMESTAMP);

