    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Thoáng đãng, mát mẻ về mùa hè, ấm áp về mùa đông. Thật sự thanh thản và thoải mái khi đến với Khu du lịch này. Mọi người hãy đến thưởng thức nơi đây. Sạch sẽ và con người thân thiện.', '7 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tour828552', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 5, 'Tôi đã cùng bạn bè đi du lịch ở nhiều nơi và 1 trong số đó là khu du lịch nước nóng thanh thủy và khá là hài lòng về địa điểm này, bởi vì vệ sinh khá là tốt, không khí tự nhiên trong lành, thoáng mát. Là một địa điểm nghỉ mát khá tốt.', '9 tháng 11, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
