    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/94/eb/b1/rock-cafe-tam-dao.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GrandTour07918002372', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 1, 'Tam Đảo là một địa danh đẹp, không khí mát mẻ gần thủ đô. Tuy nhiên mình khuyên khách du lịch KHÔNG nên đến đây vì cách làm dịch vụ ở Tam Đảo QUÁ TỆ, Tất cả các dịch vụ ăn ngủ nghỉ đều thổi bị giá lên quá đắt đỏ so với thực tế. Họ cào nát thảm thực vật núi rừng nguyên sinh để xây dựng các cơ sở lưu trú và bán ra với chi phí quá đắt đỏ. Chính quyền địa phương cũng không có phương án siết chặt quản lí mà để nó phát triển 1 cách vô tổ chức. Tôi cực kì khuyên tất cả mọi người nói KHÔNG với du lịch Tam Đảo, cho đến khi ở đây được quản lí chặt chẽ và đưa giá cả về đúng mức tiêu chuẩn. Chỉ có 1 từ để nói về cách làm du lịch ở đây "NGÁO GIÁ"', '22 tháng 4, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'vietrapro', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/21/85/40/46/vietrapro-t.jpg?w=100&h=-1&s=1', 5, 'Great trip to Tam Dao - chuyến đi Tam Đảo tuyệt vời', '22 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vu Trung Thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 4, 'Mặc dù nằm cách thủ đô Hà Nội 50 km nhưng Tam Đảo có khí hậu ôn hòa.Mát mẻ quanh năm. Từ Hà Nội đến Tam Đảo, theo quốc lộ Hà Nội - Lào Cai và rẽ vào tỉnh Vĩnh Phúc.Tam Đảo có phong cảnh đẹp và là một công viên quốc gia nên có hệ thực vật đa dạng. Đây cũng là một khu nghỉ mát ngắn hạn với các đặc sản như rau xanh và gà và cá', '18 tháng 3, 2020', CURRENT_TIMESTAMP);

