    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Trung Tuấn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ae/a4/7c/caption.jpg?w=100&h=-1&s=1', 5, 'Quảng Trường được đặt nằm giữa trung tâm thị trấn Tam Đảo, bao quanh là các tòa nhà quán ăn khách sạnCảm nhận đầu tiên là quảng trường khá rộng, sạch sẽ, thoáng mát, có nhiều cây xanh và nhiều bức tượng để nhằm mục đích chụp ảnh, có đài phun nước được đặt ở giữa và 2 chữ ''''Tam Đảo" được đặt ở một bục cao hơnCó nhiều máy bán nước tự động nhưng giá hơi chát ( đặc biệt một số chai nước lọc bị độn giá lên 20.000đ)Khi về đêm, quảng trường sẽ được thắp sáng nhờ những dãy đèn phát sáng xung quang nhìn trông rất lung linhQuảng trường nằm sát các quán ăn nên các khách du lịch ăn xong có thể đi dạo và ngồi xơi nước, ngắm đường phố', '18 tháng 6, 2022', CURRENT_TIMESTAMP);

