    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Liliane', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 1, 'Khu nghỉ dưỡng này thực sự khủng khiếp, quản trị viên cắt điện chỉ vì họ nghĩ rằng chúng tôi có thể làm phiền không ai trong bán kính 150 m. Vì vậy, chúng tôi không thể có vòi hoa sen vì không có nước bơm. Và cuối cùng, các nhân viên an ninh đã cư xử khủng khiếp, anh ta cứ nhìn chúng tôi khi chúng tôi đang bơi.Khu nghỉ dưỡng nh? c i ?? u bu? i! !', '20 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Braddell_Hill', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 4, 'Sân gôn đang trong tình trạng tốt. Điểm cộng lớn là thời tiết trong tháng 12. Nhiệt độ mát ở 20 độ C với rất nhiều ánh nắng mặt trời.Chủ yếu là một khóa học đi bộ như xe đẩy không được phép trên các luồng.Một số lỗ hổng khá xa nhau. Đối với những người đi bộ, câu lạc bộ sẽ tổ chức một lỗi để giúp chuyển người chơi từ lỗ này sang lỗ khác.Nhà hàng là cơ bản. Nhưng họ phục vụ bia Hà Nội lạnh.Một khóa học của nó không quá xa Hà Nội và lên trên khu nghỉ mát núi. Chuyến đi chơi tốt.', '22 tháng 12, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lankylee', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/2d/fe/a0/avatar.jpg?w=100&h=-1&s=1', 3, 'Đây là sân golf sullen nhất mà tôi đã làm trong nhiều năm. Cách caddies tương tác với khách biên giới thô lỗ. Họ tham gia vào cuộc trò chuyện vô tận bên trong. Khóa học là ok nhưng không đủ tốt để vượt qua dịch vụ kém.', '26 tháng 11, 2017', CURRENT_TIMESTAMP);

