    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/ca/fc/b2/caption.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/cd/2b/17/caption.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/e4/59/43/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/cc/d8/0b/garlic-naan-kadhai-indian.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cường L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 5, 'Đánh giá về Kadhai Indian Restaurant – Tam Đảo ⭐⭐⭐⭐⭐. Đây thực sự là quán ăn Ấn Độ ngon nhất mà tôi từng trải nghiệm, không chỉ ở Tam Đảo mà còn so với nhiều quán Ấn tại Hà Nội. Gia vị rất chuẩn, đậm hương vị Ấn nhưng lại được nêm nếm vừa miệng, dễ ăn hơn nhiều so với định kiến “đồ Ấn khó hợp khẩu vị người Việt”. Các món như cà ri, cơm cừu, gà nướng đều thơm, nóng hổi và chế biến tinh tế.

Điều khiến tôi hơi bất ngờ là quán khá vắng khách. Có lẽ do phần lớn khách du lịch Việt Nam lên Tam Đảo thường tìm các món “đặc sản” quen thuộc như gà đồi, su su, lẩu… nên ít nghĩ đến việc thử ẩm thực Ấn Độ. Thêm vào đó, truyền thông trong nước chưa quảng bá nhiều về ẩm thực Ấn, khiến nhiều người lầm tưởng là khó ăn hoặc nặng mùi gia vị. Nhưng thực tế, khi thưởng thức ở Kadhai, tôi nhận ra đồ Ấn hoàn toàn có thể rất hợp khẩu vị, thậm chí gây nghiện.

Nếu bạn là người thích trải nghiệm, hoặc đã từng thử món Ấn ở nước ngoài, bạn sẽ thấy đây là một lựa chọn tuyệt vời. Và nếu bạn chưa từng ăn đồ Ấn, thì Kadhai chính là nơi lý tưởng để bắt đầu. Tôi tin nếu nhiều người Việt mở lòng hơn với ẩm thực Ấn, quán này sẽ không bao giờ vắng khách', '2 tháng 9, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kadhai Indian Restaurant & Bar', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/ab/6f/85/caption.jpg?w=100&h=-1&s=1', 5, 'Kadhai indian restaurant Tam Dao best food in  this town highly recommend visit with family and friends and enjoy food .. Lần đầu tôi bước chân tới Tam Đảo, đã trải nghiệm đồ ăn Việt Nam tuy nhiên không có gì đặc biệt ở đây. 
Vô tình thấy nhà hàng Kadhai Indian ở đây, tôi order với 1 số món tôi thường ăn. Ngoài sự tưởng tượng của tôi về đồ ăn ở đây. Thật hoàn hảo không có bất cứ lời phàn nàn nào về đồ ăn.
Đặt biệt khuyến khích khách hàng ăn ở đây, họ có nhiều lựa chọn như Đồ ăn Ấn, đồ ăn Trung Quốc và pizza', '12 tháng 5, 2025', CURRENT_TIMESTAMP);

