    VALUES (gen_random_uuid(), v_place_id, 'Scenic', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/32/default-avatar-2020-12.jpg?w=100&h=-1&s=1', 4, 'Gia đình mình cứ tết là dành chút thời gian lên đền bà chúa kho.Không tin ngưỡng chỉ thành tâm thôiNhưng thấy nhiều người quá mê tín', '8 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tâm Tít', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 1, 'Tín ngưỡng là tốt nhưng thấy dân tình đốt cả núi tiền giấy thế này, rồi vay trả thánh thần như thế thì nó thành ra dị đoan rồi zzz', '31 tháng 5, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'vietrapro', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/21/85/40/46/vietrapro-t.jpg?w=100&h=-1&s=1', 4, 'Không chỉ cung cấp dịch vụ cho thuê xe đi đền bà Chúa Kho cho khách hàng, mà hàng năm Vietrapro đều tổ chức các chuyến đi đến bà chúa Kho Bắc Ninh để cầu may, xin bình an và lộc làm ăn cho toàn thể công ty.Khuôn viên ngôi đền cũng không quá rộng, nhưng đây lại là điểm đến của rất nhiều du khách không chỉ ở Bắc Ninh mà còn rất nhiều tỉnh khác.Ngôi đền từ lâu đã được biết đến là linh thiêng. Tuy nhiên, chúng tôi quan niệm, mọi sự may mắn, những kết quả tốt đẹp đều phải do bản thân mỗi người.Vào các dịp đầu năm, thì lượng người đổ về đây rất đông, nên dẫn đến tình trạng chen lấn, và phải đợi chờ rất lâu mới làm lễ được.', '26 tháng 6, 2021', CURRENT_TIMESTAMP);

