    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/46/d4/5a/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Đền bà chúa kho', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1d/f1/ec/8c/denbachuakho.jpg?w=100&h=-1&s=1', 5, 'đền bà chúa kho bắc ninh. Giới thiệu về di tích lịch sử Đền Bà Chúa Kho Bắc Ninh - Cách sắm lễ xin lộc bà chúa kho - Sắm lễ vay tiền bà chúa kho - Sắm lễ trả nợ bà chúa kho', '16 tháng 9, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TheLeongOhana', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/83/1c/4d/caption.jpg?w=100&h=-1&s=1', 4, 'Gặp bàn công việc vào bữa trưa. Chúng tôi đưa nhóm ra ngoài ăn trưa và được tổ chức trong một phòng riêng lớn. Nó hóa ra là một trong những nhà hàng địa phương tốt hơn mà chúng tôi đã ăn tối ở khu vực Bắc Ninh.

Nhìn chung là một món hời so với ăn ở Hà Nội với các món ăn tổng thể tốt. Chúng tôi có vô số người phục vụ và phục vụ bàn, vì vậy Susan lười biếng làm đầy thức ăn của chúng tôi và những chiếc đĩa trống cũng nhanh chóng được dọn đi.

Thịt bò với bánh mì chiên và tôm dừa là những món ăn ngon nhất vào buổi chiều hôm đó. Thịt bò mềm có màu nâu đậm rất phù hợp để nhúng bánh mì chiên vào. Tôm dừa giòn và ngọt hơn một chút so với dự kiến. Món ưa thích nhất cho mọi người trong bàn là cá hồi chiên vì nước sốt sệt sệt không đi cùng với món ăn', '13 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng tốt trong thành phố.. Sau 1 ngày thăm những danh thắng quanh thành phố, bạn có thể dừng chân ở nhà hàng Hà Phong. Đây là một nhà hàng rộng, sạch sẽ, phục vụ đồ ăn nhanh, có bãi đỗ xe rộng và chỗ chơi cho trẻ nhỏ. Đồ ăn mang phong vị đồng quê, khá rẻ với chỉ khoảng 100.000 vnđ+++/ người (không bao gồm đồ uống) là bạn đã có thể có được bữa ăn no với bạn bè. Phòng ăn rộng với nhiều loại phòng. Nói chung là một nhà hàng tốt trong thành phố', '16 tháng 2, 2019', CURRENT_TIMESTAMP);

