    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Tuấn Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn chất lượng. Phong cảnh đẹp, thoáng, gần gũi thiên nhiên. Đồ ăn tươi ngon. Rượu êm. 9đ. Mình ăn combo ngỗng 9 món theo gợi ý của nhân viên. Do không đặt trước nên đợi mất 30p nhưng thật sự bõ công chờ. Tiết canh thơm mát, cổ ngỗng nhồi chiên vừa giòn vừa béo. Ngỗng nướng thơm. Đặc biệt món pate gan ngỗng tươi thì perfect luôn. Điểm cộng nữa là nhân viên rất nhiệt tình lễ phép, mặc dù khách đông phải chờ hơi lâu và gọi nhân viên hơi khó', '6 tháng 4, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Quynh Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/d3/1c/9d/l-u-duoi-bo-v-i-nu-c.jpg?w=200&h=200&s=1', 5, 'Nhà hàng rất bình dân nhưng chất lượng tốt, đồ ăn ngon.. Nhà hàng có không gian mở, kiểu cây cối sông nước. 
menu rất đa dạng từ nướng đến lẩu, rất nhiều món từ chim câu, cá lăng, ếch, lươn đến các món cơ bản như gà, sườn lợn, đều có rất đầy đủ. 
đồ ăn rất vừa vặn, nhân viên thân thiện. Nhất định lần sau sẽ ghé lại để thưởng thức món Pate gan ngỗng rất ngon', '6 tháng 4, 2021', CURRENT_TIMESTAMP);

