    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/99/40/38/argentinian-and-uruguayan.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, '188petere', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/e6/fc/7d/188petere.jpg?w=100&h=-1&s=1', 4, 'Một số tác phẩm nghệ thuật tráng lệ nhưng được thương mại hóa cao', '2 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'John D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 4, 'Những người ghét nơi này không phải là người mua sắm nghệ thuật rất giỏi. Chắc chắn, có rất nhiều schlock. Nhưng nếu bạn dành thời gian để xem xét cẩn thận, có một số tác phẩm nghệ thuật tuyệt vời, bởi các nghệ sĩ khuyết tật xứng đáng được hỗ trợ. Chúng tôi đã mua một bức tranh thêu lụa đáng kinh ngạc, có thể đắt đỏ theo tiêu chuẩn địa phương, nhưng là một món hời lớn so với những gì bạn có thể tìm thấy ở Mỹ - - nếu bạn có thể. Chúng tôi bỏ qua các món ăn nhẹ, và tập trung vào nghệ thuật. Phong cảnh đó được chúng tôi đánh giá cao từ chuyến đi kéo dài 3 tuần trên khắp Đông Nam Á.', '23 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tom V', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1e/b9/0e/35/tomvining.jpg?w=100&h=-1&s=1', 4, 'Không dừng lại ở đây để ăn. Tuy nhiên, chúng tôi đã dừng lại để thưởng thức nghệ thuật đã được tạo ra, một số tác phẩm tuyệt vời. Họ cung cấp cho một mức giá hợp lý. Các cơ sở không phải là tuyệt vời, tuy nhiên, bạn đang có nhiều hơn cho nghệ thuật.', '27 tháng 7, 2018', CURRENT_TIMESTAMP);

