    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngô Thảo', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f6/0d/default-avatar-2020-34.jpg?w=100&h=-1&s=1', 5, 'Tuyệt vời. Đồ ăn rất ngon 🥰 lâu rồi mới tìm được quán vừa miệng vậy. Nhân viên phục vụ nhiệt tình niềm nở lại còn xinh gái. Có dịp mình sẽ rủ thêm bạn đến ăn tại quán. Cảm ơn các bạn rất nhiều vì bữa ăn này 😋', '29 tháng 11, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'cá chép', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Gogi hải dương quán nướng ngon. Mình cùng gia đình tới ăn tại Gogi Hải Dương. Thực sự mình đã ăn rất nhiều quán nướng nhưng hệ thống gogi vẫn là ngon nhất. Đặc biết ở gogi Hải Dương các bạn nhân viên rất dễ thương và ưa nhìn. Mời chào từ quản lí đến nhân viên. Cảm thấy mình là khách hàng và bỏ ra số tiền không phải nhỏ nhưng xứng đáng mang lại trải nghiệm đáng đồng tiền bát gạo', '12 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'cá chép', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Nhân viên nhiệt tình. Good. Đồ ăn hợp khẩu vị, món ăn ngon thịt tươi. Tuy ít nhân viên nhưng các em phục vụ rất nhiệt tình và ghi nhận 1 điều khác ở quán khác là lúc nào cũng cười', '29 tháng 7, 2019', CURRENT_TIMESTAMP);

