    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/96/29/2a/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/96/29/3e/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Voyager21387696480', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 1, 'Đồ ăn quá tệ , đi cố thêm tí nữa ăn ở trạm HP đồ vừa rẻ vừa mới . Đồ ăn ở đây bị đắt hơn lại còn cũ, nhân viên rất tháđộ. Đồ ăn quá tệ , đi cố thêm tí nữa ăn ở trạm HP đồ vừa rẻ vừa mới . Đồ ăn ở đây bị đắt hơn lại còn cũ, nhân viên rất thái độ. Bánh bao thì hấp đi hấp lại đến mức nhão nhoét vẫn bán , bánh mì thì bán đắt xong lại cho vào lò vi sóng nướng mềm oặt ra nhưng cả nhân bên trong thì chua lè', '17 tháng 6, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Daydream68417909265', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 2, 'Nhân viên và quản lý quá tồi. Nhân viên thu ngân ăn quỵt tiền của khách. Trên kệ bánh có đề giá. Đến lúc tính tiền tính thêm tiền cố tình không quét mã in hoá đơn để ăn quỵt.
Vừa tính tiền xong thì liên tục nhắc đuổi khách gây khó chịu', '29 tháng 6, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phuong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/e6/5c/e5/v52-tr-m-d-ch-v-h-i-duong.jpg?w=200&h=200&s=1', 2, 'Thái độ quá kém. Thái độ của nhân viên phục vụ quầy bán bánh đặc sản thiếu văn hoá. Là người bán hàng mà thái độ coi thường khách hàng. Khách đường dài vào chạm nghỉ chân ăn tối. Xong ra quầy muốn mua bánh làm quà. Lại gần vừa hỏi chưa dứt câu: gói bánh đậu xanh hộp vàng là như nào ak.? Nv bán hàng liếc mắt cắt ngang: 55k... Chj ta quay đi không cần nhìn khách. Khách hỏi tiếp nó là vị gì.? Chj nv khó chịu trả lời: vị nó giành giành trên hộp đấy.! Khách bảo mặt hộp để tiếng Anh ko hiểu. Chj nv lại gần bổ tay xuống quầy kính vừa nói gắt gỏng vừa chỉ tay: có hình sen với bánh đây còn hỏi vị gì.?" Khách hàng bó tay đành quay ra về mà không mua được bánh.! Thái độ phục vụ mất lịch sự với khách hàng như vậy thì khách du lịch muốn mua hàng nữa ko ak.? (19h ngày 02/11/2019)', '2 tháng 11, 2019', CURRENT_TIMESTAMP);

