    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mã Minh T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 5, 'Chuyến đi vô cùng tuyệt vời với đầy những trãi nghiệm thú vị. Tôi và chồng đã có những kỉ niệm đáng nhớ trong tuần trăng mật của mình.', '24 tháng 6, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mỹ Duyên T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/bb/default-avatar-2020-65.jpg?w=100&h=-1&s=1', 5, 'Vịnh Lan Hạ sở hữu khá nhiều bờ cát trắng mịn, trải dài giữa các dãy núi cùng với nước biển trong xanh tạo nên vẻ đẹp hấp dẫn rất đáng để các bạn tới tham quan trải nghiệm. Dịch vụ tốt, người dân thân thiện', '4 tháng 12, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hong Van Cruise', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/ad/0b/3b/cruise-h.jpg?w=100&h=-1&s=1', 5, 'Vịnh Lan Hạ là một trong những điểm thăm quan di lịch tuyệt sắc mà thiên nhiên ban tặng cho Cát Bà , ở đây có gần 400 hộ dân làng chài sinh sống trên biển và rừng Quốc Gia , Loài Vooc đầu trắng chính là loại động vật được bảo tồn lâu đời . Chuyến đi thăm quan không thể thiếu Cát Bà', '10 tháng 11, 2023', CURRENT_TIMESTAMP);

