    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bee lucky homestay', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/bb/default-avatar-2020-65.jpg?w=100&h=-1&s=1', 5, 'Một khu vườn thật đẹp và nên thơ ở đây có rất nhiều loại bươm bướm đủ màu sắc khi bạn đi bộ lên đỉnh của vườn quốc gia bạn sẽ được ngắm trọn vẹn vịnh Lan Hạ', '2 tháng 11, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hong Van Cruise', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/ad/0b/3b/cruise-h.jpg?w=100&h=-1&s=1', 5, 'Đây là 1 trong những địa điểm không thể bỏ lỡ khi đến với Cát Bà , Chiêm ngưỡng vẻ đẹp thiên nhiên từ trên cao , Đứng từ đỉnh Ngự Lâm bạn có thể thấy Vịnh Lan Hạ và ngắm những tán cây lâu năm được bảo tồn . Xứng đáng để thử .', '10 tháng 11, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KingCong Travel', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/bd/bc/6f/caption.jpg?w=100&h=-1&s=1', 5, 'Tôi là lái xe Taxi và là một hướng dẫn viên địa phương làm việc tại đảo Cát Bà. Tôi thường xuyên đưa khách du lịch nước ngoài tới địa điểm này vì nơi đây phong cảnh tự nhiên rất đẹp.', '4 tháng 11, 2023', CURRENT_TIMESTAMP);

