    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Alina Spa (Health Care Center)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/c6/89/d4/caption.jpg?w=100&h=-1&s=1', 5, 'Cát Bà là hòn đảo tuyệt đẹp với vẻ đẹp hoang sơ, biển trong xanh và núi đá vôi hùng vĩ. Nơi đây có nhiều bãi tắm sạch, ẩm thực hải sản tươi ngon, giá cả hợp lý. Du khách còn có thể khám phá vườn quốc gia, chèo kayak vịnh Lan Hạ hoặc tham quan làng chài cổ. Người dân thân thiện, dịch vụ phát triển nhưng vẫn giữ nét mộc mạc.', '20 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trần Dung', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Đảo Cát Bà mang vẻ đẹp hoang sơ, biển xanh, cát trắng, cảnh quan ấn tượng. Thích hợp cho nghỉ dưỡng, du lịch khám phá. Người dân thân thiện, đồ ăn hải sản tươi ngon. Rất đáng trải nghiệm', '2 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Passport44898245984', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'cát bà là một hòn đảo tự nhiên rất đẹp .ở đây có nhiều nơi để khám phá.người dân địa phương rất thân thiện và hiếu khách.là một nơi đáng để đến', '21 tháng 2, 2024', CURRENT_TIMESTAMP);

