    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/ad/a9/04/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Companion07822271018', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 2, 'Buồn!. Đoàn Mình tầm 20 người đến uống nước lúc 9 9 rưỡi tối. Không biết là chủ hay nhân viên tỏ thái độ không thích và báo với bên mình rằng quán sắp đóng cửa( 10 h tối). Chưa thấy quán nào chê khách như vậy', '7 tháng 5, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Linh yell', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 5, 'Perfect. Cơ sở vật chất tốt.Đồ ăn và đồ uống ngon đặc biệt là các loại Pasta, lần tới sẽ thử các món ăn khác. Hợp khẩu vị cả người việt và tây. 
Sẽ ủng hộ nhiều nhiều', '5 tháng 5, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'trynh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'Wonderful!. Food here is amazing. Nhân viên thân thiện lắm. Họ hoà đồng và nhiệt tình. 
Nghiện nhất là trà đào cam sả của quán nhé!!!!!
Hôm đầu tiên ở Cát Bà, mình gọi 1 salad quả bơ, xoài, gà ; 1 cari gà ; khoai tây chiên ; cơm rang bò nấm ; nước xoài ; nước cam. Mình đi 2 người, sức cũng khá trâu nên ăn ngon quá ngon, no quá no.
Trưa hôm sau gọi pad thái hải sản , trà đào cam sả và bún thái hải sản. 
Mọi thứ đều đầy đặn, thơm, vị vừa phải k quá mặn k quá nhạt. Nhưng chắc do khẩu vị ăn mặn quen nên đối với mình pad thái hơi ngọt. ( ý kiến cá nhân) 
Everything is still great and perfect!', '11 tháng 4, 2023', CURRENT_TIMESTAMP);

