    VALUES (gen_random_uuid(), v_place_id, 'Ngọc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Địa điểm nhất định phải đến ăn uống khi đến Cát Bà. đồ ăn siêu ngon , burger tuyệt vời , nhân viên thân thiện , hiếu khách. trang trí quán siêu đẹp, có rất nhiều hoạt động cho khách trong ngày', '22 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoang Tony', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/93/a8/03/caption.jpg?w=100&h=-1&s=1', 5, 'Một nơi với không gian và không khí tuyệt vời - đồ ăn và đồ uống rất ngon. một nơi đầy lý thú, lôi cuốn, hấp dẫn với phong cách cởi mở, thân thiện, nhân viên nhiệt tình, môi trường giao lưu cộng đồng, thực phẩm và đồ uống ngon cùng với chỗ ngồi thoải mái, đến đây bạn sẽ được thưởng thức không khí lễ hội từ từ những bài hát do chính thực khách biểu diễn, hoặc bạn cũng có thể tự mình trình diễn', '28 tháng 6, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Đinh Quốc Hưng', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, 'Quay lại và sẽ còn quay lại nữa khi đến với đảo Cát Bà. Không khí thật tuyệt vời, khu vườn xanh và sạch hơn trong lầb chở lại này, nhiều hoạt động hấp dẫn, đồ ăn ngon, nhân viên thân thiện và hữu ích', '11 tháng 4, 2024', CURRENT_TIMESTAMP);

