    VALUES (gen_random_uuid(), v_place_id, 'Venture36896099901', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 5, 'Kiên. Đồ ăn ngon, bày trí bắt mắt, nhân viên phục vụ nhiệt tình, đồ ăn vừa khẩu vị chung của gia đình mình( Bích)', '3 tháng 5, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nene', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 2, 'Một trải nghiệm chưa thật sự hài lòng:). Mình đi cùng bạn bè tới nhà hàng này, sau khi đi phà và xe khách tới Cát Bà, chúng mình thực sự khá mệt và đói. Tuy đồ ăn được phục vụ khá nhanh nhưng mình không hài lòng với bữa trưa ngày hôm đó. Và một điều nữa, nhà vệ sinh nữ có 2 buồng và 1 trong số đó rất rất mất vệ sinh không thể sử dụng được', '30 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
