    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thu trang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 5, 'ĐI CÔNG VIỆC MÀ THÀNH ĐI NGHỈ. Team mình đi công tác, được giới thiệu qua nhà hàng. Xét về mặt bằng chung thì gọi set sẽ lợi hơn nhiều vì có đủ cả các món rau, hải sản, thịt cá… Ai ăn xong cũng tấm tắc khen vì đồ ăn hợp miệng. Điểm cộng lớn là món ăn ra nhanh, quán đông nhưng không phải đợi lâu. Một trải nghiệm đáng thử', '17 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ceridwen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/2a/61/ba/caption.jpg?w=100&h=-1&s=1', 5, 'Không ngờ ở trên đây yên bình. Nhà mình hay tránh mấy chỗ đông khách nên chọn Ladybird. Đúng đợt học sinh nghỉ hè nên khu du lịch xung quanh khá nhộn nhịp, riêng trong này lại nhẹ nhàng. Món sườn nướng mật ong được các bé ăn hết trước tiên. Nhân viên lễ phép, hỏi gì cũng hỗ trợ. Bữa cơm gia đình khá trọn vẹn', '12 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Pham Thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/0a/default-avatar-2020-35.jpg?w=100&h=-1&s=1', 5, 'view biển, gió và không mưa. Một nơi khá hay cho các cặp đôi nhé, mình ghé vào đây trưa nay, bên ngoài khá gió nên bọn mình ngồi ở bàn cạnh cửa sổ, trong ấm cúng hơn và view đẹp, đồ uống ngon. Điểm cộng nữa là nhân viên phục vụ khá nhanh, đồ uống nóng có nhiều loại để lựa', '5 tháng 11, 2025', CURRENT_TIMESTAMP);

