    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/22/72/18/d9/special-chana-chaat-d.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'NP Ly', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ed/00/default-avatar-2020-4.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn cực ngon. Thấy review của hội chị em bạn dì trên group ăn uống. Mình mạnh dạn rủ bạn đi. Ban đầu mình còn sợ không ăn được đồ ăn ở đây nhưng vẫn muốn thử. Quả thật không làm mình thất vọng! Đồ ăn đã được biến tấu một chút cho phù hợp khẩu vị của người Việt nhưng vẫn rất lạ lạ ngon miệng theo phong cách Ấn. Hai người gọi 2 bánh, 1 cà rì, 1 thịt cừu nướng, 1 gà nướng. Ăn no căng bụng do nó quá đầy đặn so với sức ăn của người Việt mình ý. Anh chủ đẹp trai cực, lại còn nói tiếng Việt như gió, cực kì vui vẻ. Nhất định mình sẽ quay lại nhiều lần sau', '12 tháng 3, 2022', CURRENT_TIMESTAMP);

