    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e8/2f/36/thong-market.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e8/2e/ac/thong-market.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0c/e1/d5/66/glennchua9531.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e8/2f/75/thong-market.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'christylong173', NULL, 5, 'Bạn bè của tôi đề nghị tôi đến thăm chợ Thong nếu tôi có cơ hội đến Thái Bình. Đó là một sự lựa chọn hoàn hảo. Nhiều thứ được bán ở đây và chúng rất cơ bản. Giá có thích hợp cũng có.', '27 tháng 3, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GlennChua9531', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0c/e1/d5/66/glennchua9531.jpg?w=100&h=-1&s=1', 4, 'Quần áo, giày dép, chất tẩy rửa, rau quả địa phương, trái cây, thịt, cá vv, mọi thứ bạn cần về cơ bản. Có rất nhiều lựa chọn, vì vậy nếu bạn không hài lòng với giá cả, chỉ cần đi bộ và tìm một cửa hàng khác. Quy tắc của ngón tay cái - đặc biệt là cho quần áo và giày dép, là để mặc cả ít nhất một nửa giá mà họ yêu cầu đầu tiên. Nếu bạn không giống như một người châu Á, họ có thể sẽ yêu cầu giá rất cao - họ hầu như không thấy những người khác ngoài chính họ ở Thái Bình, vì vậy nó khá rõ ràng với họ.Có cả thịt chó nữa. FYI.', '11 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thanh N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 5, 'Trở lại thăm quê, nơi đầu tiên tôi muốn đi đó là chợ Thông.Con người quê, phong tục tập quán lối sống của người dân quê được thể hiện rõ mồn một trong phiên chợ.Rất nhiều hàng quán, món ăn, vật dụng được bày bán.Người bán người mua gần gũi thân thương.Một góc chợ là cả một trời yêu thương quê hương trong tôi!', '13 tháng 1, 2016', CURRENT_TIMESTAMP);

