    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Travel32774363969', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 1, 'Trải nghiệm lần này cùng gia đình thật tồi tệ. Chưa bao giờ tôi đi ngôi chùa nào lễ mà có tâm trạng bức xúc như thế. Bức xúc vì cách tổ chức chỉ được đi tàu khi vào, khách đi thì quá đông., đưa mẹ và con nhỏ đi lễ chùa đầu năm mà phải đợi cả sáng đến chiều vì xếp lượt 2930😡😡😡😡😡 . Người ngồi đợi la liệt, ghế thì ko có ngồi. Ai cũng bực mình, nếu biết thì không ai muốn đến đó là câu nói của biết bao người phải chờ đợi 😡😡😡😡😡', '21 tháng 2, 2026', CURRENT_TIMESTAMP);
