    VALUES (gen_random_uuid(), v_place_id, 'phuongptm', NULL, 5, 'Nhà hàng Châu Giang rất ấn tượng. Chúng tôi dùng bữa sáng và bữa tối tại đây trong kỳ nghỉ của gia đình tại Vinpearl Condotel Phủ Lý. Bữa tối được chế biến rất ngon miệng, bữa sáng đáp ứng được nhu cầu ăn chay của mẹ tôi. Chúng tôi rất hài lòng và xin gửi lời cảm ơn đến các bạn nhân viên nhà hàng đã giúp chúng tôi có một kỳ nghỉ hoàn hảo', '6 tháng 5, 2020', CURRENT_TIMESTAMP);

