    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kim Chi', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, '“Tháng 8 giỗ cha tháng 3 giỗ mẹ”nhắc tới giỗ cha là nhắc tới  Hưng đạo Vương Trần Quốc Tuấn. Địa điểm phù hợp với những người muốn tìm về chốn linh thiêng mong muốn sự thanh thản và cầu cúng.', '4 tháng 12, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
