    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Hương Giang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 5, 'Đây là điểm đến nhất định phải qua khi tới Nam Định. Đền mang vẻ cổ kính và khá yên tĩnh, yên bình. Mình với gia đình năm nào cũng đến. Đi vào dịp Tết thì có xin ấn đền Trần nhưng mà hơi đông và vào buổi sáng sớm nên mỗi bố mình đi xin, còn cả nhà sẽ cùng đi vào ban ngày thắp hương, xin chữ,... khá thong thả và thoải mái', '24 tháng 12, 2022', CURRENT_TIMESTAMP);

