    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hai Hau homestay', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/65/de/b1/phi-m.jpg?w=100&h=-1&s=1', 5, '60 năm trước, nhà thờ này nằm gữa một ngôi làng trù phú, cách bờ biển khoảng 4km. Vậy mà do biển xâm thực, giờ đây nó nằm sát bên sóng nước. Khoảng năm năm trở lại đây, nhiều nhiếp ảnh gia về đây, nhà thờ trở nên nổi tiếng về câu truyện của biển, về con người hồn hậu và về hải sản thì quá rẻ, đặc biệt con người nơi đây quá giỏi nấu ăn.', '20 tháng 6, 2020', CURRENT_TIMESTAMP);
