    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/0e/11/a8/cay-l-n.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'kiên', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 4, 'Nhà thờ đẹp. Còn rất tốt. Sao lại muốn phá đi?!?! Đã trèo lên gác chuông. Vẫn tốt, cầu thang gỗ lên gác chuông làm sơ sài, kiểu như lên gác xép, mà nhìn gỗ hình như cũng mới làm. Cho nên cầu thang có chỗ bị hỏng, mấy tấm ván rơi ra không còn nữa là bình thường. Trung tự nhà thờ lại vẫn rất ổn', '15 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Một số mà người đến thấy vô cùng trịnh trọng và thiêng liêng. Cảnh vật rất cổ kính và tinh sảo. Mọi thứ đều sắp xếp hợp lý và chất lượng. Để lại ấn tượng rất tốt cho người đến dự và du lịch. Tôi sẽ đến khi nào có dịp.', '19 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'LWilson1125', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/23/default-avatar-2020-28.jpg?w=100&h=-1&s=1', 3, 'Sau gần 30 phút nhìn cả bên trong và bên ngoài nhà thờ, tôi và các thành viên trong gia đình tôi không biết gì về lịch sử của nhà thờ này. Đây là một điều đáng tiếc lớn và tôi khuyên bạn nên ghé thăm Nhà thờ Phát Diệm hơn Giáo hội này. Nếu bạn không phải là người yêu lịch sử, bạn có thể truy cập vào đây và chụp một số ảnh.', '21 tháng 8, 2018', CURRENT_TIMESTAMP);

