    VALUES (gen_random_uuid(), v_place_id, 'Tuấn Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'một chuyến đi thăm quan check in , thưởng thức ẩm thực viêt nam ý nghĩa. Nằm ngay trung tâm thành phố, khu sinh thái Lưu Gia Trang là điểm đến lý tưởng cho những ai muốn thưởng thức những món ăn truyền thống của Việt Nam. Với không gian ấm cúng, gần gũi, nhà hàng mang đến cho bạn cảm giác như đang được quay trở về quê hương', '28 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
