    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bon', NULL, 5, 'Nhà hàng có nhiều món ngon. Nhắc tới GoGi là nghĩ ngay tới món ba chỉ bò được tẩm ướp nướng và nước lẩu Bul có vị ngọt thanh ngon tuyệt vời. Nhân viên rất nhiệt tình mình nhờ gì cũng dạ vâng rất đáng yêu', '4 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bondangyeu', NULL, 5, 'Nhà hàng ngon số 1. Phải nói là bị nghiện nước lẩu ở đây mất rồi. Lẩu có vị ngọt thanh còn có miến rất dai cùng thịt bò mềm ngọt đúng là hết sẩy luôn', '30 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hồng Trà', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn ngon. Đồ ăn tươi ngon, nhân viên nhiệt tình, view cực đẹp. Nói chung rất hài lòng. Chắc chắn sẽ quay lại và giới thiệu bạn bè', '20 tháng 9, 2019', CURRENT_TIMESTAMP);

