    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/14/4b/c8/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thùy Dương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/c1/51/1c/caption.jpg?w=100&h=-1&s=1', 5, 'Vừa trở về sau chuyến đi Tràng An (Ninh Bình), mình vẫn còn nguyên cảm giác bồi hồi và ngỡ ngàng trước vẻ đẹp của vùng đất này. Không ngoa khi nơi đây được mệnh danh là "Vịnh Hạ Long trên cạn" – một bức tranh thủy mặc đời thực vừa hùng vĩ, vừa thơ mộng đến nghẹt thở.Điều mình mê nhất ở Tràng An là cảm giác được ngồi trên chiếc thuyền nan nhỏ, lững lờ trôi trên dòng nước xanh ngắt như ngọc bích. Nước ở đây trong tới mức bạn có thể nhìn rõ những thảm rong rêu uốn lượn phía dưới. Thuyền đưa mình len lỏi qua những hang động kỳ bí, có những đoạn trần hang thấp đến mức phải cúi đầu, chạm tay vào những khối nhũ đá mát rượi. Cứ mỗi lần ra khỏi cửa hang, một khoảng trời mới lại mở ra với những dãy núi đá vôi sừng sững, rợp bóng cây xanh và tiếng chim hót vang vọng.', '15 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TIẾN NAM Đ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/6f/4f/a7/caption.jpg?w=100&h=-1&s=1', 5, 'Mình đi 1 mình vào ngày có chút mưa, nhưng nhìn chung TRANG AN cung rất đẹp khi đi thuyền  . có dịp minh sẽ quay lại', '3 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TRẦN SƠN', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/11/00/29/sonnamdinh.jpg?w=100&h=-1&s=1', 5, 'Phong cảnh thật tuyệt vời và cùng với đó các đền, chùa, điểm tâm linh ở nơi này đã tạo nên một địa điểm Thiên nhiên với Văn hóa hài hòa. Chuẩn Di sản văn hóa và thiên nhiên thế giới', '7 tháng 4, 2026', CURRENT_TIMESTAMP);

