    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hồng Ngọc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 5, 'Một địa điểm tuyệt vời để thả mình vào thiên nhiên. Xuôi dòng theo các lối đi thuyền của đầm bạn sẽ nhìn thấy rất nhiều hoa, động thực vật dưới nước. Cũng may đi vào hôm thời tiết đẹp.', '28 tháng 5, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Trung', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'Đầm Vân Long là một trong những điểm thăm quan tuyệt đẹp và hoang sơ ở Ninh Bình. Vào mùa nước lên, nhiều loại rong rêu, hoa, nước lại trong veo nên bạn như được đắm mình vào thiên nhiên vậy', '25 tháng 5, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nhàn Thu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/7b/default-avatar-2020-56.jpg?w=100&h=-1&s=1', 5, 'Đầm Vân Long không phải quá nổi tiếng như các địa điểm du lịch như Tràng An, Tam Cốc nhưng nó lại đem đến nhiều cảm xúc nhất. Có lẽ vì ít khách và sự hoang sơ của nó làm tôi cảm thấy mình cảm nhận được thiên nhiên nhiều hơn.', '20 tháng 5, 2021', CURRENT_TIMESTAMP);

