    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/8f/62/dd/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/8c/a5/b1/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'nguyễn thii', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 5, 'Con mình ăn rất ngon nên cả nhà đều hài lòng. Nhà mình có hai bé nhỏ nên lúc chọn quán cũng hơi đắn đo.  May là món bánh tráng cuốn khá dễ ăn, thịt mềm nên các bé cũng ăn được nhiều hơn mình nghĩ.  Rau tươi sạch, nước chấm vừa vị chứ không quá mặn.  Đợt cuối tháng 6 khách du lịch khá đông nên chờ món khoảng hơn 10 phút, cũng không quá lâu.  Giá hợp lý, lần sau đưa gia đình đi Ninh Bình chắc vẫn cân nhắc quay lại', '6 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'phương nhi', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Bữa tối khá dễ chịu sau khi dạo phố cổ Hoa Lư. Hai đứa mình ghé quán sau khi đi dạo quanh phố cổ Hoa Lư buổi tối.  Gọi bánh tráng cuốn thịt heo với sườn chiên mắm tỏi, món nào cũng vừa miệng. Thịt heo mềm, da giòn nhẹ, rau nhiều và còn rất tươi.  Đúng dịp đầu tháng 7 nên khu hồ khá đông, có biểu diễn trên mặt nước nên ngồi ăn cũng vui mắt.  Nhân viên hơi bận vì đông khách nhưng vẫn hỗ trợ nhanh.  Nếu quay lại Ninh Bình mình vẫn sẽ ghé ăn thêm lần nữa', '4 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thảo Vy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 4, 'Cuối tháng nhưng vẫn không quá đau ví. Tụi em đi chơi đúng lúc ví gần cạn nên chọn quán cũng cân nhắc dữ lắm. Xem menu xong thấy vẫn ổn nên ngồi lại. Đồ ăn lên khá nhiều hơn em tưởng. Món em thích nhất là cơm cháy vì ăn vui miệng. Chụp hình trên tầng trên cũng đẹp nữa. Nếu đi nhóm đông thì chia tiền ra khá nhẹ', '30 tháng 6, 2026', CURRENT_TIMESTAMP);

