    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'lolllll', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Bữa ăn tuyệt vời bên bờ biển.. Nhà hàng Tuyết đã khiến tôi cảm thấy rất hài lòng với bữa tối gần biển. Món tôm nướng và cá chiên đều rất tươi ngon và được chế biến hoàn hảo. Không gian ngoài trời nhẹ nhàng, phù hợp cho những ai muốn thư giãn. Nhân viên phục vụ rất chuyên nghiệp, luôn theo dõi để đảm bảo khách hàng được chăm sóc chu đáo. Tôi sẽ quay lại lần sau', '3 tháng 10, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
