    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'vuthu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 5, 'Xuất sắc. Tuyệt vời.Đồ ăn ngon, tôi gọi phần nhỏ. đấy là phần ăn cho hai người chứ không phải cho một người. Chủ quán và người phục vụ rất nhiệt tình', '20 tháng 2, 2020', CURRENT_TIMESTAMP);

