    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/fb/bc/d2/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DayTrip17287493110', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, 'Các món ăn được trưng bày 1 cách bài bản, nhân viên thân thiện và chu đáo. 1 địa điểm phù hợp để đi cùng với gia đình hoặc bạn bè, 1 địa điểm phù hợp để giải khuây vô cùng là hợp lý, giá cả phải chăng, những món ăn ngon miệng và đẹp mắt được trưng bày đi cùng với những nhân viên thân thiện và chu đáo', '22 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'karolinka2016', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 5, 'Pizza ngon nhất tôi từng có (và tôi thường không thích pizza!). Trước hết tôi cần đề cập đến các thành viên của đội ngũ nhân viên - mọi người thực sự siêu đẹp và thân thiện. Đối tác của tôi đã đặt hàng pizza của họ và tôi đã gọi món salad cà chua / phô mai của họ. Salad của tôi là một kích thước khá đầy với rau tươi ngon ngon và một món ăn ngon. Tôi đã thử pizza người yêu thịt của đối tác của tôi và cuối cùng đã ăn cắp một nửa của nó vì nó hoàn toàn ngon. Tôi không bao giờ thích ăn pizza nhưng cái này đơn giản là quá ngon (độ dày vừa phải, lượng toppings, phô mai ngon ....). Tôi chắc chắn có thể giới thiệu nơi này', '4 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'sarahxc0', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/1a/a2/84/sarah-c.jpg?w=100&h=-1&s=1', 5, 'Một trong những tốt nhất!. Chắc chắn nhà hàng yêu thích của chúng tôi và rung cảm chung ở tam Cốc! Phải thử pizza, tươi nấu với các cơ sở làm tại nhà (xem anh ta cần và quay bột)! Tất cả đồ uống có giá rất hợp lý và giá rẻ! !', '26 tháng 11, 2019', CURRENT_TIMESTAMP);

