    VALUES (gen_random_uuid(), v_place_id, 'Giáo Mr.', NULL, 3, 'Khu nghỉ khá là to rộng, nhưng quá đông và ý thức người dân lại không tốt. Chúng tôi thuê một biệt thự mà các phòng thì xuống cấp, không khác gì cái phòng của nhà nghỉ.', '6 tháng 3, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
