    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'andhewittscores', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/77/98/41/caption.jpg?w=100&h=-1&s=1', 4, 'Lên thuyền trên sông, dừng chân một vài bước, xuống và ngắm nhìn vị trí của bạn! Tôi đã sử dụng dịch vụ này để đến các ngôi đền.Hãy chú ý đến những kẻ lừa đảo bên ngoài bến tàu, họ sẽ cho bạn biết họ làm việc ở đó, rằng ngôi đền đóng cửa, v.v.Chỉ cần đến quầy bán vé và mua vé, họ sẽ cho bạn biết phải xếp hàng nào! Đơn giản.', '15 tháng 3, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Inlovewiththeworld', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Sông Chao Phraya mang ý nghĩa văn hóa và kinh tế sâu sắc; kết hợp tinh xảo với cấu trúc của thành phố. Rất yên bình. Cách tốt nhất để trải nghiệm sự yên tĩnh và khung cảnh là tham gia chuyến du ngoạn trên sông, đi thuyền du lịch hoặc đến quầy bar trên sân thượng. Tôi thường đi thuyền du lịch giống như taxi dưới nước. Đây là lựa chọn giá rẻ, thơ mộng để chiêm ngưỡng các điểm du lịch ven sông của Bangkok. Quán bar trên sân thượng cũng là cách tuyệt vời để tận hưởng khung cảnh từ một điểm ngắm cảnh khác.', '5 tháng 1, 2026', CURRENT_TIMESTAMP);

