    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Dee', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 4, 'Sau chuyến bay dài từ Thái Bình Dương, chúng tôi đi ngang qua Little Saigon vào ban đêm và thật tuyệt khi thấy trung tâm của Little Saigon với rất nhiều nhà hàng, siêu thị, cửa hàng, v.v. .', '1 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'belindakbelisle', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đang lên kế hoạch cho một chuyến đi đến Việt Nam. Đến thăm khu vực ở Westminster trong một ngày với tất cả mọi thứ. Thức ăn tuyệt vời, bầu không khí tuyệt vời, và những người thân thiện đáng yêu.', '6 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Emily Muniz', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/3d/default-avatar-2020-55.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi thực sự yêu nơi này! Trong những ngày cuối tuần mùa hè, gia đình có thể thưởng thức Chợ đêm với đầy đủ thực phẩm, âm nhạc và giải trí cho tất cả các gia đình. Mọi thứ thật đáng yêu và vui nhộn ở Little Saigon.', '27 tháng 8, 2019', CURRENT_TIMESTAMP);

