    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Meander03551048140', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/a3/default-avatar-2020-38.jpg?w=100&h=-1&s=1', 4, 'Thăm quê Bác ở Nam Đàn là một trải nghiệm giản dị nhưng đầy ý nghĩa. Ngôi nhà nhỏ, mộc mạc với giường tre, bàn gỗ và khoảng sân yên bình giúp tôi hình dung tuổi thơ của Bác Hồ. Không gian này không chỉ gợi lên sự gần gũi mà còn khiến tôi trân trọng hơn những giá trị đã hun đúc nên một con người vĩ đại.', '23 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Du lịch và sự kiện Miền Đất Việt', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/b1/ba/5f/travellandviet.jpg?w=100&h=-1&s=1', 5, 'Rất ý nghĩa khi đến thăm ngôi nhà đơn sơ của gia đình bác. Rưng rưng nước mắt khi được nghe chuyện thời ấu thơ của người', '8 tháng 3, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hải Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Bạn nên đi theo đoàn, và thuê hướng dẫn viên để hiểu rõ về các dấu tích lịch sử tại đây, sẽ tuyệt với không gian xanh mát, đơn sơ, giản dị và cổ kính ở đây. Bạn sẽ hiểu thêm về văn hóa của 1 thời kỳ tại địa phương này.', '12 tháng 12, 2019', CURRENT_TIMESTAMP);

