    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Meander03551048140', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/a3/default-avatar-2020-38.jpg?w=100&h=-1&s=1', 5, 'Đền thờ Vua Quang Trung là một điểm đến trang nghiêm và giàu ý nghĩa lịch sử. Khi bước vào, tôi cảm nhận ngay sự uy nghiêm của không gian, nơi tôn vinh vị anh hùng áo vải đã làm nên chiến thắng Ngọc Hồi - Đống Đa lừng lẫy.Kiến trúc đền giản dị nhưng vững chãi, hài hòa với thiên nhiên. Những bức tượng, hoành phi, câu đối đều toát lên tinh thần chiến đấu kiên cường của vị vua tài ba. Đến đây, tôi không chỉ chiêm ngưỡng mà còn cảm nhận được niềm tự hào dân tộc và sự kính trọng dành cho Quang Trung - Nguyễn Huệ.', '23 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'trang hiên ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/10/7b/4d/1a/trang-hien-h.jpg?w=100&h=-1&s=1', 5, 'Địa điểm tâm linh yêu thích. Tại đây các bạn phải vượt qua một con dốc ngoằn ngoèo bằng xe máy, tiếp theo bạn sẽ vượt một dãy bậc thang nhưng ở cuối thì bạn sẽ thấy một ngôi đền cực đẹp với kiến trúc cổ. Ở đây bạn cũng có thể nhìn ngắm được cả thành phố Vinh từ xa nữa', '6 tháng 10, 2021', CURRENT_TIMESTAMP);

