    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/63/ab/10/at-miaow-pizza.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Louis B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/13/4a/bd/11/nam-viet-spa.jpg?w=200&h=-1&s=1', 4, 'Chúng tôi đã có một spa đáng yêu ở đây với bạn bè của chúng tôi. Dịch vụ này là đồng minh tốt. Chúng tôi đã có dầu massage và xông hơi trong 1 giờ 30 rất thoải mái và tuyệt vời. Rat khuyen khich', '15 tháng 6, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sean L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/d3/71/5a/onwithsean.jpg?w=100&h=-1&s=1', 5, 'Tôi đã đến spa này một vài lần. Tôi rất vui khi tôi đến Nam Việt Spa. Mọi người làm việc ở đó rất thân thiện và hữu ích. Các chuyên viên đấm bóp làm việc ở đó rất giỏi về những gì họ làm. Họ có thể thư giãn các cơ khó khăn nhất. Vào cuối buổi mát xa của bạn, bạn sẽ có một lựa chọn. Bạn có thể lấy "que nóng". Chúng giống như một chiếc ghim lăn nhưng nhỏ hơn và mỏng hơn. Người đấm bóp đàn bà sử dụng chúng để cuộn cơ bắp của bạn như bột. Họ khá thú vị. Đừng bỏ lỡ Nam Việt Spa vào lần tới khi bạn ở thành phố Vinh!', '16 tháng 4, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anna', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/9e/c5/a7/avatar.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đã có một dịch vụ tuyệt vời trong khi có điều trị spa ở đây, các nhân viên đã rất hữu ích và chuyên nghiệp. Đây là một địa chỉ tốt để thư giãn sau một ngày làm việc vất vả', '7 tháng 4, 2018', CURRENT_TIMESTAMP);

