    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/5f/76/78/conquer-all-the-challenges.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Giang C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Chuyến đi là một trải nghiệm độc đáo và khác lạ. Chúng tôi được thăm những địa điểm đẹp không ngờ mà ngay cả người Nghệ An như tôi cũng không biết tới; ngoài ra còn có các trò chơi vui nhộn và được giao lưu với những người dân địa phương; các hoạt động tình nguyện cho các bạn nước ngoài.  Cảm ơn Vinh guru đã taoj ra một trải nghiệm thú vị và nhiều ý nghĩa.', '14 tháng 4, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hueltm', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Trong suốt chuyến đi không có giây phút nào em thấy đoàn mình không vui vẻ cả, tay nghề chụp ảnh của các anh chị cũng rất hịn nha <3Mọi người đều rất chân thành và khoảnh khắc tạm biệt khiến em xúc động lắm, lưu luyến những ngày trải nghiệm trên Sapa.Chắc chắn chuyến đi tiếp theo của em sẽ lại đi cùng với VinhGuru nhé ạ *wink*', '13 tháng 4, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tungvin1988', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Cảm ơn Vinhguru đã mang đến cho tôi và công ty một kỳ nghỉ nhiều cung bậc cảm xúc;từ lúc di chuyển; đến hành trình các điểm tham quan và chương trình teambuilding+galadinner tất cả đều được tổ chức một cách rất chuyên nghiệp và hấp dẫn. Đặc biệt là bạn MC , kết nối được tất cả mọi người trong các trò chơi, chương trình. Các bạn Hdv cũng rất dễ thương và nhiệt tình hỗ trợ mọi người trong suốt chuyến đi.Hi vọng sẽ được gặp lại các bạn sớm.Thanks Vinhguru!', '8 tháng 4, 2020', CURRENT_TIMESTAMP);

