    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/c7/7b/f9/the-american-steak-restaurant.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hienrosa90', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/02/cb/20/grandtour28240712092.jpg?w=100&h=-1&s=1', 5, 'Đồ tây. Nhà hàng The American Steak tại Vinh được đánh giá cao với không gian sang trọng, ấm cúng và món bít tết chuẩn vị, thịt mềm, mọng nước, nướng đúng độ chín yêu cầu. Nên thưởng thức đồ tây', '7 tháng 3, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Guide16504623619', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'The American Steak - Thiên đường cho tín đồ bít tết. Nhà hàng mang đậm phong cách Mỹ với không gian sang trọng, ấm cúng. Bít tết được chế biến chuẩn vị, thịt mềm, mọng nước, nướng đúng độ chín yêu cầu. Ngoài ra, các món ăn kèm như khoai tây nghiền, salad cũng rất ngon. Nhân viên phục vụ chu đáo, thân thiện. Giá cả hơi cao nhưng xứng đáng với chất lượng. Nếu bạn là fan của steak, đây chắc chắn là địa điểm không thể bỏ qua!', '26 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Julia F', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/73/default-avatar-2020-13.jpg?w=100&h=-1&s=1', 5, 'Thức ăn tuyệt vời. Nhà hàng này làm bánh mì kẹp thịt ngon nhất ở Vinh. Tôi đến đó hàng tuần cho một burger. Họ cũng sẽ thêm các thành phần bổ sung vào bánh burger của bạn theo yêu cầu của bạn. Tôi chưa bao giờ thất vọng với một bữa ăn từ bít tết Mỹ', '22 tháng 10, 2019', CURRENT_TIMESTAMP);

