    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vui99', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/02/c3/a3/wander25788109113.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng NEMO Sóng Xanh – Điểm đến hải sản tươi ngon tại Vinh. Nhà hàng NEMO Sóng Xanh tọa lạc tại cuối đường Lê Mao kéo dài, rẽ phải 200m, thành phố Vinh, Nghệ An. Với không gian sang trọng, rộng rãi, nhà hàng có thể phục vụ gần 1.000 khách cùng lúc, phù hợp cho các buổi tiệc và gặp gỡ', '28 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'HarryPham2011', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/b2/74/0f/caption.jpg?w=200&h=200&s=1', 5, 'Nhà hàng đẹp, Hải sản tươi sống, ngon và phục vụ cực tôt. Tình cờ có buổi họp lớp và chúng tôi lựa chọn nhà hàng này. Cảm ơn nhà hàng đã cho tôi và bè bạn một buổi hội ngộ tuyệt với. Món ăn ngon, phục vụ chuyên nghiệp. chắc chắn sẽ quay lại và giới thiệu cho bạn của tôi', '9 tháng 7, 2023', CURRENT_TIMESTAMP);

