    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f2/8c/3f/bai-d-u-xe-r-ng-rai-ly.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'keeleyjade_x', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/10/06/c9/6e/keeleyjade-x.jpg?w=100&h=-1&s=1', 3, 'Bữa tối thất vọng. Chúng tôi vừa ăn tối tại Việt Đức. Các nhân viên đã tốt trong ý nghĩa họ đã cố gắng để nói chuyện với chúng tôi bằng tiếng Anh được đánh giá cao. Chúng tôi đặt hàng Mi Xao B (thịt bò và mì ăn liền) và gà hấp với gừng và gạo. Các món mì được nhạt nhẽo không có rau (so với khác Mi Xao Bo chúng tôi đã có). Nó cũng rất nhờn. Gà gừng có xương, nhưng hơn một nửa không phải là thịt gà mà là chất béo và da nên tôi không thể ăn được. Không có mùi gừng nào cả. Gạo của tôi không bao giờ đến. Nó có giá 257000 D với một nước và bia để chúng tôi (du khách dài hạn) nó là tốn kém và đáng thất vọng. Đặc biệt là chúng tôi đã đi du lịch Việt Nam trong 2 tháng nay để có ý tưởng tốt về chất lượng và chi phí', '29 tháng 5, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hanneke W', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 4, 'Thức ăn tuyệt vời, dịch vụ siêu thân thiện. Điều này về cơ bản là một trong số ít các nhà hàng thực sự ở Vinh, bên cạnh tất cả các quán ăn nhỏ trên đường phố. Hầu hết các nhân viên đều trẻ và họ rất mệt mỏi để thực hành tiếng Anh của họ, mà họ hầu như không nói được. . . Chúng tôi cho phép họ chọn một con gà và một món thịt bò cho chúng tôi và tất cả hóa ra là rất tốt! Nhà vệ sinh sạch sẽ và một khu vườn xinh đẹp. Hai con ria xích gần lối vào khá buồn', '3 tháng 4, 2017', CURRENT_TIMESTAMP);

