    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Paul G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/c4/e7/71/g9850evpaulg.jpg?w=100&h=-1&s=1', 4, 'Thực phẩm phong phú, nơi để đi nếu bạn đang tìm kiếm giá vé SA.. Hãy mong đợi một bầu không khí tiệc tùng và dịch vụ tiêu biểu của Việt Nam - luôn thân thiện, hữu ích và tử tế nhưng không phải là nhanh nhất trên hành tinh. Các lựa chọn thực phẩm và đồ uống là ấn tượng, như là chi phí. Bạn sẽ không rời đi với sự hối tiếc', '19 tháng 6, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hall T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/79/6e/90/hall-t.jpg?w=100&h=-1&s=1', 1, 'Không chịu nổi. Một cơn ác mộng. Để bắt đầu, cô phục vụ đứng và nhìn chằm chằm vào chúng tôi trong khi chúng tôi đang chọn thức ăn (cách mặt tôi 50 cm) và sẽ không nhúc nhích ngay cả khi tôi yêu cầu cô ấy (bằng tiếng Việt) cho chúng tôi 5 phút. 3 món đầu tiên chúng tôi chọn từ thực đơn họ đã làm. Khi nó đến đã mất 3 món ăn. Chúng tôi để lại thức ăn và đồ uống của chúng tôi một nửa.
Âm nhạc là 20 decibel vượt quá giới hạn an toàn và các nhân viên đã thô lỗ đặt nó một cách lịch sự', '12 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'anhanh78', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Cửa hàng sang trọng, phục vụ chu đáo. Quán ngon, vị trí đẹp. Bên ngoài trang trí rất nhiều đèn. Nhân viên phục vụ tốt. Hài lòng về món ăn ở đây', '4 tháng 8, 2018', CURRENT_TIMESTAMP);

