    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phuchq', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/dd/7a/da/phuchq.jpg?w=100&h=-1&s=1', 5, 'Tôi đã đến chùa hương cùng bạn bè, ngôi chùa thật thiên liêng và cổ kính. Điều tuyệt vời nhất là ở đây có sông có núi, không gian bình yên và mát mẻ.', '1 tháng 8, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'haan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 5, 'từ chổ để xe để đến chùa phải đi tầm 4-5km bằng cáp treo và leo bậc nhưng rất ấn tượng với rừng cây thông ở đây.các bạn nhớ đem thêm áo vì chênh nhiệt độ nên sau quảng đương leo bậc lên đến nơi nhiệt độ thấp hơn khi về dễ bị cảm :)', '5 tháng 4, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 5, 'Nằm trên đỉnh núi Hồng Lĩnh, chùa được chia làm 2 phần, phần chùa mới nằm trên nền chùa cổ phía trên với tháp và phần chùa cũ nằm phía dưới. Từ cổng vào khu vực cáp treo khá xa (khoảng 5km) nhưng đường đẹp, hai bên rừng thông, có thể đi xe điện hoặc thuê xem ôm. Nếu đi đò thì mất khoảng1,5km đi bộ từ bến đò vào nhà cáp treo. Đi cáp treo lên chùa tuy nhỏ nhưng uy nghiêm. Phần mới được xây dựng nằm phía trên và phải leo đường khá dốc, bậc thang cao hơn bình thường. Nhưng khi đứng từ trên cao nhìn phong cảnh phía dưới rất tuyệt. Một địa điểm du lịch tâm linh rất tuyệt ở Hà Tĩnh.', '26 tháng 7, 2020', CURRENT_TIMESTAMP);

