    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trang Chu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/23/24/66/35/trangctt0710.jpg?w=100&h=-1&s=1', 5, 'Đây là hồ nước nhân tạo rất lớn với vẻ đẹp trong lành, thuần khiết. Xa xa là màu xanh của núi rừng "chìm chìm" điệp điệp (cách nói của con bé 2 tuổi nhà mình ;)). Con đường đi quanh hồ cũng tuyệt đẹp với 1 bên là hồ nước mênh mông, 1 bên là thảm cỏ xanh trải dài bất tận, phía trên là mênh mông màu xanh của bầu trời và mây trắng bồng bềnh trôi. Chắc chắc nếu ở Hà Tĩnh lâu, hoặc đi theo nhóm đông, mình cũng sẽ muốn cắm trại 1 đêm để trải nghiệm hết tất cả các khoảnh khoắc tuyệt vời ở Hồ Kẻ Gỗ. Mình không có chủ đích đến đây, chỉ là quyết định tức thì của 2 vợ chồng khi đang đi xuyên Việt, coi google map, thì muốn rẽ qua cho biết. Mà thấy bị mê hoặc luôn trước cảnh đẹp nơi đây.', '22 tháng 4, 2022', CURRENT_TIMESTAMP);

