    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/b5/da/8e/nha-hang-corona.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Suri', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/b5/da/8d/nha-hang-corona.jpg?w=200&h=200&s=1', 5, 'Tuyệt vời. Không gian thoáng,đẹp.nv nhiệt tình chu đáo món ăn ngon tuyệt.Rất phù hợp cho mọi nuhu cầu ăn uống', '7 tháng 8, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tai truong ba', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/a2/default-avatar-2020-3.jpg?w=100&h=-1&s=1', 5, 'Đánh giá. Nhà hàng corona thực sự còn hơn cả tuyệt mọi người ạ
Tầng 1 nơi phục vụ những món lẩu , nướng trên cả tuyệt vời
Nơi đây có những combo đồ nướng và lẩu rất ngon và phù hợp với túi tiền của mọi người
Tầng 2 nơi có phòng vip với phòng máy lạnh không gian khép kín rất phù hợp với những người cần không gian yên tĩnh để thưởng thức những món ăn mang đậm nét việt của nhà hàng 
Tầng 3 sẽ rất phù hợp cho những cuộc tụ tập bạn bè,với không gian thoáng đãng mát mẻ trên tầng thượng. Đặc biệt nơi đây còn có thể nhìn bao quát quanh khu vực vincom và vinper , thực sự nơi đây có một view rất tuyệt vời và còn hơn cả tuyệt vời mọi người ạ. Và còn điều thú vị nữa chính là ở đây phục vụ bia tươi nữa . Nhấm nháp một ly bia tươi trò chuyện vui vẻ với những người bạn hay gia đình thì còn gì nữa mọi người
Hãy tới đây cùng với gia đình và bạn bè, tôi nghĩ ở đây thực sự là một nơi cực kì lý tưởng mà bạn nên tới một lần trong đời!!!', '6 tháng 8, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thành Nè', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Thăm quan hà tĩnh. Thái độ phục vụ nhiệt tình , không giang khu buffet hiện đại ,sang trọng . Phòng vip mát mẽ sạch sẽ , tầng ba hải sản thì thoáng mát wir đẹp. Đồ ăn ngon ,đẹp mà giá cả thì phải chăng
Nếu các bạn có dịp đi công tác hay du lịch cùng bạn bè , người thân hãy ghé nhà hàng CORONA để trải nghiệm và tận hưởng', '6 tháng 8, 2020', CURRENT_TIMESTAMP);

