    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/c8/16/1c/photo2jpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/c8/16/1a/photo0jpg.jpg?w=200&h=200&s=1', 5, 'View đẹp, nước uống ngon. Nước uống ở đây pha ngon, không khí mát mẻ, view toàn cảnh rất đẹp. Bánh thì hơi ngọt. Hà Tĩnh ít chỗ chơi khuya, nên đây là lựa chọn không tệ vào ban đêm. Không gian quán sang trọng và lịch sự, nhạc nhẹ nhàng, phù hợp với gia đình', '16 tháng 8, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Miguel R', NULL, 3, 'Vị trí ấn tượng không quá ấn tượng về chất lượng thực phẩm và đồ uống!. Có lẽ điều này có thể là tuyệt vời cho du khách ba lô với rất ít sự lựa chọn hoặc chỉ vì không có vị trí cao cấp thực sự trong khu vực này. Tuy nhiên, điều này không đáp ứng các tiêu chuẩn hoặc kỳ vọng của một quán bar và thực phẩm chất lượng cao. Bánh mì kẹp thịt được đánh giá quá cao về chất lượng thịt và chắc chắn là nấu chín và đốt cháy. Các lựa chọn trong đồ uống trung bình và danh sách rượu vang ít để lại mong muốn cho giá cả. Nếu bạn sẽ tính phí cho một chai rượu vang tốt không phải là một vấn đề! Chai rượu giá rẻ và bỏ qua như một loại rượu chất lượng cao? Không! Có lẽ nó có thể phù hợp với những người chưa bao giờ trải nghiệm chất lượng thực sự hoặc sự đánh giá cao của du khách ba lô vào lúc này. Nó không ấn tượng như kiến trúc, vị trí và tầm nhìn. Nếu bạn chọn đến đây? Hãy để nhận thức, trí tưởng tượng và kỳ vọng của bạn ra khỏi cửa. Chỉ cần thưởng thức đồ uống thông thường và tận hưởng khung cảnh hạn chế, khu vực này vẫn đang phát triển và không có nhiều ở đây để xem. Khá là một sự thất vọng lớn!', '9 tháng 9, 2019', CURRENT_TIMESTAMP);

