    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TUAN ANH', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Quán đẹp, ngon , phu hop Vỉa hè rộng thoáng mát . Tầng 2 thì ngắm phố chil - phòng vip cho ai thích yên tĩnh. Quán này đẹp có nhiều view ăn tiền thật. Vỉa hè rộng thoáng mát . Tầng 2 thì ngắm phố chil - phòng vip cho ai thích yên tĩnh  kha ok', '3 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
