    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hà Mỹ Dung', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/dd/65/64/caption.jpg?w=100&h=-1&s=1', 5, 'Chuyến đi Tú Làn Oxalis- Quảng Bình 4 ngày 3 đêm dành cho vợ chồng tôi rất thú vị và an toàn. Tour guide rất dí dỏm, nói tiếng Anh rất hay. Thiên nhiên Quảng Bình - Việt Nam tuyệt đẹp! Chúng tôi sẽ quay lại!', '14 tháng 4, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
