    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Luyen P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 5, 'Tôi chỉ có một tour du lịch 2 ngày và 1 đêm với Oxalis trong hệ thống hang Tú Lân. Rất hài lòng với thời gian dành cho cả đội. Trang trại tuyệt vời, nhóm hỗ trợ rất tốt và 2 hướng dẫn viên tốt. Đặc biệt, tuyến đường này thật tuyệt vời, bao gồm đi bộ xuyên rừng, bơi lội dọc theo dòng chảy và ngược dòng, bơi trong hang, khám phá hang động và vân vân.', '3 tháng 9, 2018', CURRENT_TIMESTAMP);

