    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/25/b7/4f/photo4jpg.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/64/85/66/delicious-specialty-coffee.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/0f/cc/e3/evening-view-from-outside.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/b0/fb/f1/caption.jpg?w=100&h=-1&s=1', 5, 'Đây là một chuyến trải nghiệm thật thú vị, mang lại cho tôi nhiều sự mới lạ khi được đến nơi này , cảnh quan nơi đây thật tuyệt vời nó tạo cho tôi một cảm giác mới lạ nhưng đầy sự cuốn hút, tôi cảm thấy như mình đang ở một nơi nào đó trong truyện cổ tích thần tiên với những cảnh vật huyền ảo lung linh', '3 tháng 10, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TranMaiHoogQan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/8d/9f/b1/thuylamquan.jpg?w=100&h=-1&s=1', 5, 'Các thạch nhũ trong động là kiệt tác của thiên nhiên, được bảo tồn tốt nên rất đẹp, điểm hot nhất khi đến Quảng Bình ngoài Son Doong, vì giá hợp lý 250k/1 vé, nhưng có cái là fai leo lên 540m đường dốc, nên đi với quần đùi áo ngắn tay và hành trang gọn nhẹ, giày thể thao cho dễ leo, các bạn nữ k nên mang giày thời trang các kiểu dù là dép kẹp đi sẽ rất đau chân do đi bộ nhiều và leo, trên cửa động có quầy bán nước nên cũng không cần mang vác cho nặng, không khí trong động rất là mát mẻ và trong lành sảng khoái, leo núi mệt nhưng vào động là thấy khỏe hẳn ra, rất dễ thở!', '10 tháng 7, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Matthew P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/02/03/1d/matthew-p.jpg?w=100&h=-1&s=1', 5, 'Đã thực hiện một chuyến đi thuyền đến khu phức hợp hang động ngược dòng từ Son Tracy. Chiếc thuyền đã cắt động cơ khi chúng tôi đến hang động và thủy thủ đoàn sau đó chèo thuyền trong khoảng 30 phút vào thế giới ngầm rộng lớn này. Trên đường trở về, chúng tôi rời thuyền và leo lên 300 bậc thang được cho là trên vách đá, nơi trên đỉnh có thể đi xuống một đường ray rất an toàn và được xác định rõ ràng đưa bạn vào hệ thống hang động ấn tượng ồ ạt này. Việc leo lên là một chút mệt mỏi nhưng những nỗ lực của bạn sẽ được đền đáp nhiều hơn khi bạn vào hang động mát mẻ và hấp dẫn. Không có gì không thích ở đây chỉ cần đi sớm để bỏ lỡ sức nóng và đám đông. Áo phao được cung cấp và về cơ bản là bắt buộc.', '27 tháng 7, 2019', CURRENT_TIMESTAMP);

