    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Liễu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 4, 'Đi qua khu vực này và dừng chân ăn trưa, view đẹp, đồ ăn ngon. Một số nhà hàng nằm bên đường, sau lưng là bãi biển, không phải điểm du lịch nhưng nghỉ chân ở đây rất tốt.', '6 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
