    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Oanh Ly', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 4, 'Bãi biển Nhật Lệ đẹp nhưng nhiều hàng quán bám sát quá nên mình cũng không thích bằng bãi biển Bảo Ninh 2, tuy nhiên thì ở bãi biển bảo ninh nhiều gia đình trải đồ ăn nên nhiều rác, ý thức dọn dẹp kém.', '22 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Urue Tam', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Biển xanh ngắt như tranh vẽ, cát mịn dưới chân, nắng vàng rực rỡ ôm trọn bờ vai—thiên đường là đây chứ đâu! 🌊✨ Hải sản tươi ngon đến mức ăn một lần là nhớ mãi, lại còn được ngồi chill giữa làn gió biển mát rượi mà ngắm từng chiếc máy bay lượn qua, uyển chuyển cất cánh hay hạ cánh như biểu diễn riêng cho mình vậy! Trải nghiệm đỉnh cao, không gì sánh bằng—xứng đáng điểm 10 tuyệt đối! ✈️', '9 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thủy Mai', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Bãi biển đẹp, cat vàng mịn, bãi biển không quá đông như ở Thanh Hoá hay Cửa Lò. Nhiều quán ăn đặc sản, đặc biệt Hải Sản ở đây ngon và giá hợp lý.', '15 tháng 4, 2025', CURRENT_TIMESTAMP);

