    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'HanoiJW', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/eb/14/43/ngdangquang.jpg?w=100&h=-1&s=1', 5, 'Quảng Bình có nhiều khu đồi cát đẹp, hy vọng họ không san hết để làm khu đô thị và tổ hợp resort. Bạn nên bỏ chút thời giian để tạt qua đồi cát vào buổi chiều.', '2 tháng 9, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Guong', NULL, 5, 'Mình rất thích cát ở đây, vàng óng và tự nhiên. Đứng giữa đồi cát ngắm mặt trời lặn hay trượt cát cùng bè bạn thực sự là một trải nghiệm thú vị', '15 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'PVH_NA', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/7f/86/e5/pvh-na.jpg?w=100&h=-1&s=1', 4, 'Nếu trước đây, đến Quảng Bình ta nghĩ đến Phong Nha - Kẻ Bàng. Nay, bạn sẽ có thêm trải nghiệm mới ở đồi cát Quang Phú. Nằm ở phía bắc thành phố Đồng Hới, sát biển, gần sân bay.Tuy không mênh mông như bạn tưởng nhưng cũng đủ để bạn và gia đình có thêm những phút giây thư giãn thoải mái và chụp được nhiều ảnh đẹp.', '13 tháng 5, 2019', CURRENT_TIMESTAMP);

