    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/8f/ba/18/7th-heaven-2020-come.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'happyangle751311', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, '21/04/2016 toi co chuyen kham pha dong Phong Nha va Thien Duong. Nhan vien Le Khang Travel rat nhiet tinh, bac lai xe de thuong lam. Toi chi co loi khuyen la neu co y dinh tham quan, kham pha Phong Nha Thien Duong thi nen mua tour nay. Rat tien ich. Cam on Le Khang da cho chung toi chuyen di vui ve va day trai nghiem.', '21 tháng 4, 2016', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bao N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/c2/21/e9/bao-n.jpg?w=100&h=-1&s=1', 5, 'gia đình tôi vừa có một chuyến đi thăm quan các hang động cùng tour Quang Binh Caves Adventure Travel. Chuyến đi này đã khiến gia đình tôi rất vui vẻ.Chúng tôi đã được hướng dẩn cách đặt tour và chọn tour hợp lý, tiết kiệm thời gian đi lại. Đô ăn rất ngon ,hợp khẩu vị của cả nhà. Hướng dẩn viên hướng dẩn nhiệt tình.Các yếu tố trên làm cho chuyến đi của gia đình trở nên tuyệt vời.CẢm ơn công ty của bạn, và hẹn gặp lại ở những chuyến đi gần nhất.', '31 tháng 3, 2016', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'việt p', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/c2/21/5f/vi-t-p.jpg?w=100&h=-1&s=1', 5, 'thật bất ngờ với công ty của bạn .tôi đã có một tour tham quảng bình với nhiều địa danh với nhiều khám phá mới khi được nhận sự nhiệt tình hướng dẫn và tư vấn từ người dẫn làm cho chuyến đi vô cùng thú vị .chúng tôi rất cám ơn công ty với đội ngũ làm việc rất khoa học .chúng tôi rất cám ơn và sẽ gặp lại vào thời gian gần nhất', '31 tháng 3, 2016', CURRENT_TIMESTAMP);

