    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Paul J', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/07/fd/b5/20/paul-j.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi rất thích nhìn vào tàn tích này - đặc biệt là phần còn lại của trụ cột trung tâm của cầu thang xoắn ốc trước đây đến gác xép hợp xướng. Chúng tôi hy vọng có thêm một chút thông tin và bối cảnh (ảnh khi nó hoạt động).', '29 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lephuchau', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/19/4e/0a/lephuchau.jpg?w=100&h=-1&s=1', 4, '- Nhà thờ Tam Tòa là một di tích nhà thờ Công giáo tọa lạc đường Nguyễn Du, phường Đồng Mỹ, thành phố Đồng Hới, tỉnh Quảng Bình.- Ngày 11 tháng 2 năm 1965, nhà thờ bị một trận bom đánh sập, chỉ còn lại phần tháp chuông với nhiều vết đạn.- Địa điểm này là điểm tham quan du lịch nhưng thường xuyên đóng cổng rào xung quanh để bảo vệ không cho tiếp cận. Chỉ có thể đứng từ bên ngoài quan sát.', '23 tháng 2, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Louis B', NULL, 5, 'Nhà thờ này thực sự tuyệt vời nằm trên con sông Nhật Lệ. Phần phía trước duy nhất của nhà thờ vẫn còn là phần còn lại đã bị phá hủy bởi các cuộc đua ngựa Mỹ. Chỉ cần một chuyến thăm nhanh nhưng thú vị. đừng bỏ lỡ nó', '17 tháng 6, 2018', CURRENT_TIMESTAMP);

