    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Passenger66871261690', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 5, 'Sealand spa  sát bờ sông Nhật lệ rất thơ mộng.nv làm việc chăm chỉ 22h mình đến các c ấy vẫn rất niềm nở, vừa làm vừa trò chuyện giúp mình hiểu hơn về vùng đất mới.Nếu có cơ hội nhất định sẽ quay lại', '26 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Meander04575705343', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 5, 'Tiệm spa nằm trong một còn ngỏ nhỏ cách mặt tiền đường lớn khoảng 15m , tiệm nằm trên tầng 5 của ks. Hình như tiệm mới chuyển về đây, cơ sở vật chất rất mới. Có đầy đủ công năng phòng xông hơi, phòng tắm, tủ để đồ cá nhân, phòng thay đồ… view  biển.nói chung với mức giá bình dân với cơ sở vật như trên rất tuyệt vời.Các bạn nv làm việc ở đây đón tiếp rất nồng nhiệt,mặc dù đã hết giới nhưng vẫn bóp đầu thêm cho mình vì mình đau đầu.Áo quần khăn gối rất thơm thô sạch sẽ.Một trải nghiệm rất ưng ý', '12 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Zempaza', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/eb/default-avatar-2020-27.jpg?w=100&h=-1&s=1', 5, 'Quán mới xây dựng cơ sở mới khang trang,mùi thơm hoa cỏ tự nhiên thoải mái dễ chịu.nhân viên làm rất tốt, chăm chút .Phòng massage view biển Nhật Lệ rất đẹp, không giang yên tỉnh.Lưu ý: quán không nằm ở mặt đường lớn mà cách mặt đường khoảng 15m đường ô tô vào tốt tuy nhiên nếu không để ý cũng sẽ dễ đi quá.Quán nên làm bảng chỉ dẫn lớn ở đường lớn sẽ tốt hơn.', '16 tháng 9, 2026', CURRENT_TIMESTAMP);

