    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/6d/c5/42/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hola', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/2e/default-avatar-2020-67.jpg?w=100&h=-1&s=1', 5, 'Lựa chọn đồ Thái tại đồng hới. Ăn thì cũng được mỗi tội hôm nhà mình đến họ có tổ chức tiệc gì đấy nên hơi đông. Nhà mình chờ phải 15_phút mới có bàn. Được cái đồ ở đây ăn hợp khẩu vị mặc dù có mấy quán cũng bán đồ thái mà thấy ăn chỗ này vẫn hợp vị nhất. Ko biết vì sao nhưng chắc 1_phần vị trí trước sông thoáng mát nên ngồi ăn cũng thấy dễ chịu hơn chăng', '20 tháng 3, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Fuji Jonne', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 5, 'Đi ăn tối. Đồ ăn chuẩn vị Thái, nhân viên phục vụ nhiệt tình, các món ăn trang trí đẹp mắt, nhanh chóng, đặc biệt có món tháp sườn ngon đậm vị. Recomend cho mọi người nhà hàng này nhé ạ', '19 tháng 3, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Maps01862131182', NULL, 1, 'Quá tệ. Nhân viên phục vụ quá tệ xem chấn chỉnh lại đi cả quản lý nữa chứ như vậy sao mà ai giám vào đó để ăn nữa nếu không làm được thì thay nhân viên mới hoạc là đóng quán đi???', '5 tháng 9, 2024', CURRENT_TIMESTAMP);

