    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Công đạt n', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 4, 'đồ ăn ngon mà khẩu phần hơi ít. Phục vụ chăm sóc nhóm công ty mình rất chu đáo, biết nói tiếng Anh và recommend món spec. quán đẹp rất là vui khi tới đây', '15 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Explorer51444325336', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/6a/default-avatar-2020-47.jpg?w=100&h=-1&s=1', 5, 'Khác lạ. Cuối tuần rồi đưa vợ con đến trải nghiệm thử. Thấy menu nhiều món lạ, cả nhà rất phấn khích. Đặc biệt vợ với tụi nhỏ. Có món sườn cừu xử lý khá tốt, ko bị nghe mùi cừu quá nặng nên dễ ăn. Mấy món pizza cũng lạ khi kết hợp nguyên liệu địa phương. Sẽ quay trở lại!
Lưu ý: nhà bên cạnh đang xây nên hơi ồn', '12 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'xiucon', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 5, 'Healing chữa lành dịp lễ. Một trong những nhà hàng âu đẹp nhất Đồng Hới. Không gian thoáng đãng, sang trọng và đậm chất đương đại.các món thiên về steak và fussion. Mỗi tội nhân viên dù có cố gắng nhưng vẫn còn hơi chậm', '1 tháng 9, 2026', CURRENT_TIMESTAMP);

