    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Duy Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/2e/default-avatar-2020-67.jpg?w=100&h=-1&s=1', 5, 'Review đồ ăn quá. Đồ ăn tươi, nêm nếm hợp khẩu vị. Giá cả hợp lý so với chất lượng. Không gian thoáng, phù hợp đi cùng gia đình hoặc bạn bè', '5 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mai', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 5, 'View đẹp, đồ ăn ngon ! Sẽ quay lại.. Gia đình đi 4 người, ăn tối ở đây thật tuyệt. View biển, mát mẻ, đồ ăn tươi ngon. Mức giá ở Đồng Hới nói chung vẫn còn hợp lý (hoặc có thể gọi là thấp hơn) so với các điểm du lịch bãi biển khác', '20 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kha N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 5, 'Ốc sả gừng thơm lừng, nước ngọt cực đã!. Món ốc hấp sả gừng ở đây thật sự là một trải nghiệm ẩm thực tuyệt vời. Thịt ốc tươi ngon, giòn sần sật kết hợp cùng hương thơm nồng nàn của sả và vị cay nhè nhẹ của gừng tạo nên một hương vị vô cùng đậm đà. Đặc biệt, phần nước hấp thật sự là điểm nhấn, vừa thanh ngọt tự nhiên, vừa thấm đẫm hương vị thảo mộc. Nhâm nhi chút nước ấm nóng thơm lừng cùng vài con ốc mọng nước thì cực kỳ đã miệng, ăn một lần là nhớ mãi!', '19 tháng 7, 2026', CURRENT_TIMESTAMP);

