    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Huong P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 5, 'Điểm đến của mọi khách du lịch khi tới QB. Quán ăn phục vụ rất nhanh, đồ ăn ngon, nhân viên vui tính, rất đáng để thử, ông chủ mlem mlemmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm ♥️♥️♥️', '11 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Linh Tran', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Đồ uống ngon, không gian ấm cúng và dịch vụ thuê xe máy rất ok. Mình và bạn tới ga Đồng Hới và đã tìm đến Sophie Homy để uống nước. Chị chủ quán rất nhiệt tình và dễ thương, hướng dẫn tận tình cho mình các địa điểm du lịch ở đây. Đồ uống khá ngon và quán decor rất ấm áp. Tụi mình đã thuê xe máy đi Phong Nha 2 ngày với mức giá rất hợp lý, xe lại còn mới nữa. Nói chung là rất hài lòng vì sự trải nghiệm này!', '16 tháng 4, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'jonathan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/b2/b3/fa/caption.jpg?w=100&h=-1&s=1', 5, 'sự lựa chọn tuyệt vời. Lựa chọn tuyệt vời nếu bạn cần thứ gì đó nhanh và ngon để ăn trước khi đi tàu! Sophie nói và hiểu tiếng Anh khá tốt', '17 tháng 1, 2020', CURRENT_TIMESTAMP);

