    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/d1/a8/fb/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Chu Thị N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 5, 'Điểm ăn uống lý tưởng cho gia đình. Nhà hàng này là lựa chọn lý tưởng cho các gia đình đang  tìm kiếm một bữa ăn tuyệt vời ngay tại trung tâm thành phố. Đồ ăn ở đây thực sự ngon, với nhiều lựa chọn để làm hài lòng mọi người và giá cả rất phải chăng. Không khí ấm áp và hấp dẫn, khiến đây trở thành nơi dễ chịu để cùng nhau thưởng thức bữa ăn. chắc chắn phải thử', '6 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Đinh Thế L', NULL, 5, 'Không gian rộng rãi. Điểm đầu tiên khiến tôi ấn tượng là không gian thoáng đãng và sang trọng. Không gian hoàn hảo, khiến toàn bộ trải nghiệm ăn uống trở nên thú vị hơn. Đồ ăn tươi, ngon và giá cả phải chăng. Thêm vào đó, nhân viên vô cùng chu đáo và nhiệt tình, khiến chúng tôi cảm thấy được chăm sóc chu đáo. Rất đáng để giới thiệu', '9 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Không khí vui vẻ và dịch vụ tuyệt vời. Đầu tiên và quan trọng nhất, không khí ở đây thật tuyệt vời, rộng rãi, thoáng mát và sang trọng tuyệt đẹp. Đồ ăn tươi ngon, giá cả phải chăng, khiến trải nghiệm trở nên tuyệt vời hơn. Đội ngũ nhân viên vô cùng chu đáo và nhiệt tình, đảm bảo chúng tôi cảm thấy được chăm sóc chu đáo trong suốt chuyến đi', '5 tháng 11, 2024', CURRENT_TIMESTAMP);

