    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/bd/3d/bc/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cris 88', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/0e/8a/89/cris-sugar.jpg?w=100&h=-1&s=1', 5, 'Đoàn tôi đã có dịp ghé thăm đây vào năm 2018 tại địa Đạo Vĩnh Mốc . Một khám phá thú vị từ lịch sử của quảng trị . Phong cảnh thiên nhiên gần biển đẹp và với đường hầm trong lòng đất với các di tích kháng chiến ở đây', '20 tháng 9, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anahita A', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/4a/default-avatar-2020-42.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi sẽ không đi tour DMZ và tiếp tục tranh luận về việc liệu chúng tôi có nên hạn chế đến đường hầm Vĩnh Mộc hay không. Cuối cùng chúng tôi đã thực hiện chuyến tham quan cả ngày và thực sự, nó đáng giá. Thật đáng kinh ngạc khi nghe những câu chuyện của những người sống và sống sót sau những đường hầm này. Huế là một chút trong một cách "du lịch" bình thường, nhưng thực hiện chuyến đi nếu bạn muốn tìm hiểu về lịch sử và trải nghiệm một lát của nó', '6 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'SteveByfleet', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/c4/d2/98/stevebyfleet.jpg?w=100&h=-1&s=1', 5, 'Được xây dựng để bảo vệ dân làng địa phương, những người phải sống bằng má với những chiếc xe ngựa Nga được VC giữ ở đó, USAF đã phát hiện và ném bom **** ra khỏi nơi này.Các nhà lãnh đạo VC bảo họ ở lại, đứng vững, để họ đào những đường hầm này để bảo vệ và giấu vũ khí.Vì vậy, đây chủ yếu là các đường hầm dân sự không giống như các đường hầm quân đội Củ Chi gần Sài Gòn.Cuộc sống thực sự khó khăn những người này đã có', '15 tháng 2, 2020', CURRENT_TIMESTAMP);

