    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/8c/c2/d4/photo4jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Toralin', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/d0/bc/49/toralin.jpg?w=100&h=-1&s=1', 3, 'Đây chắc chắn là một trang web quan trọng, nhưng thành thật mà nói, bảo tàng và máy móc được trưng bày là khá nghèo nàn. Nếu bạn xem xét mức độ nghiêm trọng của trận chiến, động lực chính trị và để tôn vinh những người đã chiến đấu trên trang web này. . . Rõ ràng là bảo tàng không phản ánh đúng điều này.Các thông tin bảo tàng có thể được kích thích nhiều hơn.Điều đó nói rằng, nếu bạn đang ở trong khu vực, nó sẽ có giá trị một chuyến thăm.', '12 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'pphp', NULL, 3, 'Tôi rất muốn đi nhưng hơi thất vọng. Không có nhiều ở đó. Có thêm rất nhiều từ Bảo tàng Chứng tích chiến tranh ở TP HCM. Rất vui vì đã ở đó vì tôi đã đọc rất nhiều về nó và cũng thích bài hát này!', '12 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ChicoRanMan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/e9/41/95/chicoranman.jpg?w=100&h=-1&s=1', 5, 'Yêu thích đến thăm mảnh nhỏ này từng là sân bay và căn cứ Khe Sanh trong chiến tranh Việt Nam. Một bảo tàng mô tả Trận Khe Sanh dưới góc nhìn của Bắc Việt.Bên ngoài một số cỗ máy chiến tranh của Mỹ được hiển thị. Máy bay trực thăng Bell Huey và Chinook, vận tải C 130 và xe tăng M 61 ấn tượng. Bạn có thể bò bên dưới bể và nhìn lên qua cửa thoát hiểm và xem nội thất ấn tượng của xe tăng.', '13 tháng 1, 2020', CURRENT_TIMESTAMP);

