    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'hà anh trụ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/de/d9/0e/caption.jpg?w=100&h=-1&s=1', 5, 'Nước biển khá sạch. Tôi đã nhặt được tảo biển. Cát mịn. Sóng hơi yếu. Ở đây chắc nắng vỡ đầu. AbcqeryioooBxbxjxjxbxbxnxbxbxbx', '27 tháng 8, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Legiang89', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/0d/24/25/avatar.jpg?w=100&h=-1&s=1', 5, 'Cùng với Cửa Tùng, Cồn Cỏ, bãi biển Cửa Việt xinh đẹp được xác định là điểm nhấn phát triển du lịch của tỉnh Quảng Trị. Đến với Cửa Việt, các bạn sẽ được thoải mái chiêm ngưỡng vẻ đẹp duyên dáng, bãi cát trắng mịn, sạch sẽ trải dài bên những rừng dương liễu xanh rì rào. Cảm giác yên bình đến lạ sẽ giúp các bạn quên hết mệt mỏi sau những ngày làm việc căng thẳng.', '17 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'jengadie', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 4, 'Bãi biển không đông đúc, cát trắng và những người thân thiện. Có những cửa hàng gần đó nơi bạn có thể mua thức ăn và đồ ăn nhẹ. Chúng tôi yêu cầu nấu hải sản tươi từ người dân địa phương. Chắc chắn, một nơi tốt để ghé thăm.', '6 tháng 11, 2019', CURRENT_TIMESTAMP);

