    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'MOK', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, '"Món quà không ngừng cho đi" được viết trên một mảnh đạn được trưng bày', '21 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Louga925', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 4, 'Trung tâm cung cấp thông tin về mìn và bom chủ yếu được sử dụng trong Chiến tranh Việt Nam. Trong nhiều bảo tàng ở Việt Nam, cuộc chiến giữa Việt Nam và Hoa Kỳ mô tả những người lính Việt Nam dũng cảm và chiến thắng. Ở trung tâm này, bạn sẽ thấy chính xác thiệt hại thực sự của các cuộc chiến.Những quả bom rỉ sét được trưng bày ở khu vực xung quanh đẹp có thể cho chúng ta biết sự bình yên.', '19 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'R M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/09/1d/fd/r-m.jpg?w=100&h=-1&s=1', 5, 'Tôi đến đây vì mục đích nghiên cứu, nhưng bất kỳ ai quan tâm đến lịch sử Chiến tranh hay chiến tranh của Mỹ nói chung nên đến đây để xem những gì đang được thực hiện liên quan đến những ảnh hưởng lâu dài của chiến tranh. Phu là một hướng dẫn tuyệt vời và rất say mê công việc mà RENEW đang làm. Suy nghĩ kích động - nếu bạn đã truy cập UXO Lào ở Luông Pha Băng hoặc trang web Campuchia ở Siêm Riệp, đây sẽ là một bổ sung tuyệt vời. Đáng giá thời gian và tiền bạc của bạn, không xa Huế.', '23 tháng 6, 2019', CURRENT_TIMESTAMP);

