    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'tinbaoloc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Đến quảng trị nơi đây là nơi mình ghé đầu tiên. Đến để biết, để nhìn thấy và cảm nhận nơi đây từng là chiến trường khốc liệt. Cảm thấy biết ơn ông cha ta đã ngã xuống để đổi lấy được sự bình yên cho thế hệ sau này.Trân trọng.', '16 tháng 10, 2019', CURRENT_TIMESTAMP);
