    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anthony', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 4, 'Trong hành trình thăm dải đất miền Trung, chúng tôi thành kính ghé thăm Thành cổ Quảng Trị. Đọc những dòng giới thiệu, tận mắt xem những di tích thời chiến, trong lòng chúng tôi đều dâng lên lòng biết ơn với các anh hùng liệt sỹ đã ngã xuống vì Tổ Quốc. Đây là một nơi chúng ta đều nên đến để biết cái giá của hoà bình và sự tàn khốc của chiến tranh!', '12 tháng 7, 2017', CURRENT_TIMESTAMP);

