    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Louga925', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 3, 'OK nhưng ít hơn mong đợi. Rất phổ biến trong người dân địa phương. Hương vị và nhân viên là tuyệt vời. Nhưng tôi mong đợi nhiều loại nguyên liệu hải sản tươi sống địa phương hơn vì Đông Hà nằm gần cảng cá. Thật không may, các thành phần có vẻ tương tự như ở Hà Nội hoặc HCM', '19 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lotus Le', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/15/f8/cf/flyer57419409298.jpg?w=100&h=-1&s=1', 4, 'Good Japanese restaurant in Dong Ha. Phong cách, không gian hiện đại cho bạn một buổi tối dễ chịu cùng gia đình. Đồ ăn ngon, thực đơn và cách trình bày món ăn phong phú. Tuy nhiên order 1 số món đợi hơi lâu', '13 tháng 2, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
