    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Truong Van Hoang', NULL, 5, 'Rất tuyệt vời, đồ ăn ngon.. Đã đưa khách đến đây nhiều lần. Khách nào cũng khen, hoài cổ yên tĩnh. Mâm cơm ấm cúng cho gia đình và bạn bè. Rất tuyệt vời, đồ ăn ngon, vị trí đẹp, nhân viên nhiệt tình.!!', '14 tháng 8, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Gerda L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 5, 'Món ăn ngon, sạch sẽ, nhân viên phục vụ rất tốt. Tôi đã có cơ hội đến nhà hàng Phúc An vào tuần trước và thực sự ấn tượng với không khí và cách phục vụ nhiệt tình của nhà hàng. Món ăn ngon, sạch sẽ, nhân viên phục vụ rất tốt, giá tốt, sẽ quay lại khi ghé quảng trị', '8 tháng 8, 2024', CURRENT_TIMESTAMP);

