    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hue Private Car', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/da/ad/90/caption.jpg?w=100&h=-1&s=1', 5, 'Lăng Minh Mạng là một trong những quần thể lăng tẩm đẹp và hài hòa nhất ở Huế. Không gian rộng lớn, yên bình, kết hợp tinh tế giữa núi – hồ – rừng, tạo cảm giác rất thư thái khi dạo bước. Kiến trúc cân đối, các mái ngói đỏ và hồ sen khiến nơi đây vừa trang nghiêm, vừa thơ mộng.Nếu bạn thích không gian tĩnh lặng, cảnh quan hài hòa và muốn tìm hiểu sâu hơn về văn hóa Nguyễn, đây chắc chắn là một điểm nên đến. Đặc biệt, chụp ảnh ở đây rất đẹp và thoáng, ít ồn ào.Một trải nghiệm đáng nhớ khi đến Huế!', '1 tháng 12, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sigourney', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/a2/f4/b1/thaoxiuu.jpg?w=100&h=-1&s=1', 5, 'Lăng Minh Mạng, tọa lạc tại Huế, là một trong những di tích lịch sử ấn tượng của triều đại Nguyễn. Được xây dựng vào giữa thế kỷ 19, lăng tẩm này nổi bật với kiến trúc hoàng gia trang nghiêm và hài hòa, phản ánh sự uy nghi của vua Minh Mạng. Không gian lăng được bao quanh bởi cảnh quan thiên nhiên tươi đẹp, với hồ nước, cổng tam quan và các điện đài tinh xảo. Sự kết hợp hoàn hảo giữa thiết kế kiến trúc và cảnh quan thiên nhiên làm cho lăng Minh Mạng không chỉ là nơi tôn vinh vị vua mà còn là một điểm đến du lịch hấp dẫn, mang đậm dấu ấn văn hóa và lịch sử.', '3 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vũ Thị Thảo', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/7b/default-avatar-2020-56.jpg?w=100&h=-1&s=1', 5, 'Không gian thực sự rất yên tĩnh, trong lành và có phần tĩnh mịch. Nhiều cây xanh được chăm sóc cẩn thận. Vào đây lượn một tý cho biết rồi ra.', '10 tháng 5, 2021', CURRENT_TIMESTAMP);

