    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'san san', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 5, 'lăng Tự Đức là một điểm tham quan rất đáng để ghé thăm khi đến Huế. Nơi đây không chỉ là di tích lịch sử quan trọng mà còn là không gian nghệ thuật độc đáo, hòa quyện giữa thiên nhiên và kiến trúc.Tham quan lăng Tự Đức sẽ giúp bạn hiểu thêm về triều đại nhà Nguyễn và có những trải nghiệm khó quên trong hành trình khám phá cố đô Huế.', '27 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'timbisto', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/3d/default-avatar-2020-55.jpg?w=100&h=-1&s=1', 5, 'Vì vậy, một nơi tuyệt đẹp để được với lịch sử như vậy. Một hương vị đích thực của Việt Nam lịch sử.Hồ và những khu vườn rất ấn tượng và bạn có thể thấy ba ngôi mộ đơn giản nhưng thanh lịch. Một cho anh ta, và một cho cả vợ và anh trai anh ta.Nó cho thấy sự hào phóng của ông như một Hoàng đế', '9 tháng 3, 2020', CURRENT_TIMESTAMP);

