    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/fb/e8/6d/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kim G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 5, 'Được xây dựng vào năm 1805, Cung điện Thái Hòa có ngai vàng của Hoàng đế Nguyễn. Cung điện được trang trí với mạ vàng, sơn mài và tráng men. Một khoảng sân rộng phía trước cung điện được gọi là Tòa án tính toán, được hai lần một tháng, các quan lại tham gia vào buổi lễ Khán giả lớn. Lễ đăng quang đã diễn ra tại đây, cũng như các lễ kỷ niệm và chiêu đãi chính thức. Cung điện Thái Hòa được coi là cấu trúc quan trọng nhất trong Hoàng thành.', '29 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roland B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/2b/b6/fa/r0landbrunner.jpg?w=100&h=-1&s=1', 4, 'một trong những tòa nhà chính ở Hoàng thành (Thành cổ), Cung điện Thái Hòa có những chi tiết đẹp và nội thất phong phú.', '8 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'RobandChez', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/20/ee/32/avatar.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi rất vui vì chúng tôi đã đến đây khi chúng tôi ở lại Huế. Mặc dù đó là một ngày khốn khổ và mưa mà chúng tôi đến thăm Hoàng thành thật đẹp. Kiến trúc và tác phẩm nghệ thuật rất thú vị và đẹp. Chúng tôi đã may mắn khi chúng tôi đến thăm vì nơi này gần như trống rỗng! Chắc chắn có một chuyến đi ở đây nếu bạn đang ở trong khu vực. Họ cũng có một cửa hàng quà tặng nhỏ đáng yêu.', '6 tháng 10, 2019', CURRENT_TIMESTAMP);

