    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Curiosity05994132752', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ed/00/default-avatar-2020-4.jpg?w=100&h=-1&s=1', 5, 'Không gian tuyệt vời với các góc "làng nghề" được trang trí rất nghệ thuật và gần gũi. Nhân viên trong trang phục áo dài rất "Huế". Giá đồ uống thì có thể nói là rẻ, cách phục vụ chu đáo, nhiệt tình. Chắc chắn nếu có cơ hội thì mình sẽ quay lại để tiếp tục trải nghiệm', '20 tháng 9, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Yixuan', NULL, 5, 'Ngọc rất thân thiện và nói chuyện với tôi trong khi tôi vẽ chiếc mũ, làm cho trải nghiệm thú vị hơn rất nhiều so với nó! Trải nghiệm tuyệt vời : )', '6 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ry John', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f6/0d/default-avatar-2020-34.jpg?w=100&h=-1&s=1', 5, 'Khi tôi đến Huế. Tôi đã bị ấn tượng bởi không gian đẹp tại Luc Bo. Đặc biệt là không gian thủ công mỹ nghệ truyền thống. Tôi đã có một khoảnh khắc đẹp với Ngọc. Cô ấy có vẻ như là một giáo viên nghệ thuật tận tâm. Chúng tôi đã có một cuộc trò chuyện thú vị tại thời điểm đó. Rất tốt !', '5 tháng 12, 2019', CURRENT_TIMESTAMP);

