    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngọc Nhi', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/5f/57/5c/caption.jpg?w=200&h=200&s=1', 5, 'Món ngon Đà Thành. Thật bất ngờ với sự cổ kính và món ăn bắt mắt tại Xóm Mới Garden Đà Nẵng. Không gian ấm cúng, mang đậm nét cổ điển, rất thích hợp để thư giãn. Đồ ăn ngon, trình bày đẹp mắt và hương vị tuyệt vời. Đồ uống phong phú và ngon miệng. Nhân viên thân thiện và phục vụ chu đáo, làm cho trải nghiệm thêm phần tuyệt vời. Rất đáng để ghé thăm!', '19 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngọc Chắn Xảo', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/de/0b/5d/caption.jpg?w=100&h=-1&s=1', 5, 'Xứng đáng 5 sao. Mình dẫn đối tác đến đây ăn trưa, không gian đẹp, nhạc nhẹ nhàng. Đồ ăn thì ngon nữa. Đối tác nước ngoài của mình rất thích luôn. Nem nướng, bánh xèo, bún chả 10 điểm. Nhân viên thân thiện, phục vụ nhanh nhẹn, chuyên nghiệp. Xứng đáng được biết đến nhiều hơn nữa', '15 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
