    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngoc N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/7b/default-avatar-2020-56.jpg?w=100&h=-1&s=1', 5, '⭐ Trải nghiệm rất đáng nhớ, đồ ăn ngon và dịch vụ tuyệt vời. Mình và gia đình có dịp ăn ở đây và ai cũng rất hài lòng. Hải sản tươi, món ăn được nêm nếm vừa miệng, lên món cũng khá nhanh. Không gian nhà hàng sang trọng, sạch sẽ nhưng không tạo cảm giác quá gò bó, rất thích hợp để đi cùng gia đình hoặc bạn bè.

Điều làm mình ấn tượng nhất là bạn nhân viên Sam. Bạn rất nhiệt tình, luôn niềm nở, chủ động hỏi thăm và hỗ trợ tụi mình trong suốt bữa ăn. Cảm nhận được sự chu đáo và tận tâm chứ không phải kiểu phục vụ cho có. Nhờ vậy mà cả bữa ăn trở nên thoải mái và dễ chịu hơn rất nhiều.

Chắc chắn mình sẽ quay lại vào lần sau. Cảm ơn Sam và cả nhà hàng đã mang đến một trải nghiệm rất tuyệt!', '7 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'NorthStar24083877080', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 5, 'Một trãi nghiệm tuyệt vời. Trãi nghiệm vô cùng tuyệt vời. Bạn nhân viên tên Thạch rất quan tâm khách hàng. Và vô cùng vui vẻ khiến gia đình mình thoải mái khi ở đây. Rất đánh khen thưởng', '28 tháng 8, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Camper31290042580', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Nhân viên Roy là nhất!. Tôi đã đến thăm mùa giải năm nay vào khoảng 7 giờ và ăn rất ngon miệng. Trong số đó, nhân viên Lợi đối xử rất tốt với tôi nên tôi rất thoải mái trong lúc ăn. Hành động mà anh ấy đối xử với chúng tôi đã làm cho chuyến du lịch của chúng tôi vui lên. Roy là nhất!!', '13 tháng 8, 2025', CURRENT_TIMESTAMP);

