    VALUES (gen_random_uuid(), v_place_id, 'Trongtran79', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/5e/a2/42/caption.jpg?w=100&h=-1&s=1', 5, 'Mình rất thích không khí ở chợ đêm Hội An, rất náo nhiệt với nhiều khách du lịch đến từ nhiều nước khác nhau. Và chỉ với vài phút di chuyển mình có thể đi đến phố cổ bên kia chiếc cầu với nhiều đèn lồng nhiều màu sắc. Hãy nhớ ghé chợ đêm cũng như phố cổ khi đến Hội An nhé^^', '5 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr NHD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/89/19/3d/caption.jpg?w=100&h=-1&s=1', 4, 'Chợ đêm Hội An rất sầm uất, vì chợ gắn liền với hoạt động tham quan ở phố cổ.Chợ bán các loại cây trái nhiệt đới Việt Nam là chính.Món ăn thì mang nét đặc trưng ở Hội An như: Tào phớ, Xiên nướng, Cao lầu, Mì Quảng, Bánh đập, Chè các loại,...Các cửa hàng quần áoCác gian hàng lưu niệmCác quán bar, nhà hàngNói chung, có rất nhiều lựa chọn cho du khách khi đến đây ăn uống.Tuy nhiên, giá cả ở chợ đêm khá cao, giá này ở các khu vực khác ở Hội An có khi là gấp đôi. Không biết có chặt chém hay không, nhưng giá gấp đôi ở các khu lận cận & không ngon bằng.', '22 tháng 2, 2025', CURRENT_TIMESTAMP);

