    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GRLUK', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 4, 'Chợ này đã có một tiếng vang thực sự về nó vào ngày chúng tôi đi dạo dài qua nhiều quầy hàng và cửa hàng của nó. Các điểm tham quan và âm thanh đã cho chúng tôi cảm giác tuyệt vời khi ở một nơi nào đó thực sự khác biệt và không có sự ồn ào của tiếng ồn giao thông ở hai thủ đô lớn.Chúng tôi đã may mắn, nó gần khách sạn của chúng tôi, nhưng nó đáng để nỗ lực ghé thăm.', '15 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ron B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 5, 'Nếu một người ăn của bạn đây là nơi để được. Quá nhiều mùi và cảnh khiến bạn muốn nếm trải mọi thứ', '9 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'G2Kpauly', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/24/91/74/avatar.jpg?w=100&h=-1&s=1', 4, 'Tôi đã đi xung quanh thị trường này và nó ổn. Có tất cả những thứ thông thường để mua. Một số cô gái tôi biết đã mua một số trang phục được làm cho phù hợp và vv Phần thực phẩm là tuyệt vời cho một số thực phẩm ngon quá!', '25 tháng 2, 2020', CURRENT_TIMESTAMP);

