    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/77/df/88/hoi-an-heart-restaurant.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hung Do Van', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/07/9f/54/c0/worldtrip-vip.jpg?w=100&h=-1&s=1', 5, 'Khu phố chợ tấp nập người đến mua sắm ăn uống nằm ngay trung tâm phố cổ Hội an.Nhiều sản phẩm mới lạ nằm ngay trên đường Trần Quí Cáp. Vào ban đêm những xe hàng lưu niệm bày bán nhiều thứ. Ấn tượng nhất với chúng tôi là gỗ Lũa ở của hàng anh Hưng từ làng mộc Kim Bồng. Rất đẹp mắt giá tốt chừng 500 ngàn cho 1 sản phẩm và đượng tặng kèm phiểu đồng, 3 nụ trầm và 1 tượng phật ngồi thiền.Trải nghiệm đáng nhớ!', '15 tháng 7, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'MOON SHOE MARKET', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/db/b9/53/caption.jpg?w=100&h=-1&s=1', 5, 'Tôi đi cùng bạn và chúng tôi đã ghé vào chợ ăn.       ở đây thức ăn vừa miệng , giá lại rẻ chỉ từ 25k đến 35k 1 phần ăn. thức ăn rất đa dạng', '20 tháng 7, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tracy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 5, 'Nó tràn ngập lựa chọn một nơi để thử món ăn Hội An đích thực vì gần như mọi quán ăn và nhà hàng đều phục vụ cùng một thực đơn. Khu ẩm thực trong chợ có lẽ là lựa chọn tốt nhất để thử đồ ăn địa phương. Nhiều người trong số họ đã phục vụ thức ăn ở đây trong nhiều thập kỷ là những gì hướng dẫn của tôi nói với tôi. Và thật tuyệt vời vì tôi có thể ngồi ở một nơi và thử tất cả các món ăn địa phương mà không phải tìm kiếm chúng. Phải thử là mì cao lau, mì mi quang, hoành thánh hoa hồng trắng.', '20 tháng 3, 2020', CURRENT_TIMESTAMP);

