    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Companion56005330477', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Bữa ăn cuối tuần. Không gian đầm ấm, trải nghiệm tuyệt vời, thức ăn ngôn lành', '23 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Culture19893187071', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 5, 'Grandma Kitchen Hội An. Tôi cùng gia đình đã ăn tối taij đây vào dịp nghỉ hè.Ở đây có view đẹp nhìn ra sông, các món ăn truyền thống Hội An như Cao Lầu, Mỳ Quảng bò rất hợp khẩu vị dù lần đầu tôi ăn. Món hải sản kiểu dân chày tươi, ăn kèm sốt xanh rất đặc biệt . Nhân viên phải nói là siêu thân thiện và nhiệt tình .Giá cả hợp lý và sẽ quay lại nếu ghé Hội An', '4 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roving30576700244', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/91/default-avatar-2020-62.jpg?w=100&h=-1&s=1', 5, 'Grandma Kitchen và những thực khách đói bụng. Đây là lần tôi đến Hội An cùng gia đình, tình cờ ghé thăm quan dùng bữa tối. Đồ ăn thực sự rất ngon, hợp khẩu vị, thể hiện được rõ nét đặc trưng của đặc sản Hội An, cộng thêm giá cả phải chăng, chỗ ngồi rộng, thoáng, thoải mái (cả trong và ngoài quán). Nếu có lần sau, tôi vẫn sẽ ghé qua Grandma Kitchen!', '24 tháng 5, 2025', CURRENT_TIMESTAMP);

