    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Minh Hoà', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Tôi là người Phố cổ Hội An nhiều đi tích lịch sử. Nhưng lần đầu tiên đến Mỹ lại di tích, tôi được nghe và xem lại những video cũng như được kể lại. Rất sót thương và cảm động.', '18 tháng 4, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoi An B n P Travel', NULL, 4, 'Thuyết minh tương đối đầy đủ, các hình ảnh của vụ thảm sát cho thấy sự ác liệt của chiến tranh. càng thấy giá trị của hòa bình', '20 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'SandyBargara', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/02/dc/e3/0a/sandybargara.jpg?w=100&h=-1&s=1', 4, 'Trang web di tích Mỹ Sơn trưng bày những tàn dư của ngôi làng là trung tâm của vụ thảm sát Mỹ Lai. Đó là hòa bình và tôn trọng. Tên và tuổi trên bia mộ của những người bị giết ở tàn dư của mỗi ngôi nhà khá cảm động. Toàn bộ trang web là một lời nhắc nhở đơn giản về sự tàn bạo đó.Bảo tàng có một số hình ảnh. Câu chuyện được kể được hiểu theo quan điểm của người Việt Nam. Nhiều người tôi đã thấy ở Bảo tàng Chứng tích chiến tranh.Nếu bạn đang ở trong khu vực đó là giá trị ghé thăm.', '3 tháng 10, 2019', CURRENT_TIMESTAMP);

