    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lưu văn Minh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Những ai đã từng đến thăm khu tưởng niệm Sơn Mỹ ,đều có chung suy nghĩ tội ác tày trời của đế quốc Mỹ không bao giờ quên trong lòng mỗi chúng ta.Đau thương dù đã qua 52 năm,chúng ta không quên những người con Quảng Ngãi đã hy sinh cho ngày hôm nay.Chiến tranh không thể nào còn trên đất Vệt Nam này một lần nào nữa.. Đoàn ccb phường Thanh xuân Trung Quân Thanh Xuân Hà Nội .', '13 tháng 7, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Felix Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/40/66/d8/sightsee59008146764.jpg?w=100&h=-1&s=1', 5, 'Nơi diễn ra cuộc thảm sát 504 thường dân vô tội tại Xã Tịnh Khê. Nên đến cho biết về lịch sử đau thương và mất mác.', '29 tháng 4, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'grandpop60', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/23/default-avatar-2020-28.jpg?w=100&h=-1&s=1', 5, 'Nơi này rất đáng để ghé thăm, rất buồn, và rất chống Mỹ, gọi họ là những kẻ giết người. Nó chỉ có giá 20, 000 lối vào.', '10 tháng 3, 2020', CURRENT_TIMESTAMP);

