    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Compass07789289237', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 1, 'Thất vọng. Tối ngày 27/7 tôi và anh đồng nghiệp ra ăn gọi món cá bống sông trà kho tộ mãi 30 phút sau nhân viên lên báo là không có món. Tôi phải gọi món khác thay thế là cá kèo kho tộ. Gọi 3 niêu cơm cháy giòn thì 40 phút sau mang 3 niêu bình thường. Phản ánh với quản lý thì mới được mang đi đổi làm niêu khác. Chưa hết. Đến lúc thanh toán hoá đơn tính luôn cả món cá bống sông trà kho tộ. Tôi nghĩ nhà hàng làm ăn gian dối thế này thì quá lời. Làm ăn kiểu treo đầu dê bán thịt chó, tính tiền cà dê lẫn chó. Chúc mừng chủ nhà hàng làm ăn kiểu này được lâu lâu nhé', '27 tháng 7, 2024', CURRENT_TIMESTAMP);

