    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Quoc Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 4, 'CƠM GÀ CŨNG ĐƯỢC - DỄ ĂN. Quán ăn khá sạch sẽ, nhanh gọn, cơm ăn tương đối ngon, gà ngon, chỉ có cái là giá hơi cao một chút. Suất 40k ăn không no, 50k cũng k no luôn. 40k suất bình thường và 50k là suất lớn. Thêm cơm cho suất 40k - 50k  mình nghĩ sẽ hợp lý hơn', '6 tháng 3, 2024', CURRENT_TIMESTAMP);
