    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/32/15/45/7c/restaurant-review-g608528.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/a0/b8/5b/signature-grilled-surf.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Liù DM', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 1, 'Đừng ăn trong nhà hàng của ngư dân trên bãi biển IN FRONT OF Life là một quán bar trên bãi biển!Chúng tôi đã đồng ý về giá cho một con tôm hùm mỗi kg và họ tăng gấp đôi giá.Dịch vụ này rất tệ và họ không nói một từ tiếng Anh nào.Chúng tôi đã gọi 2 loại bia nhiều lần, một đĩa nghêu và một con tôm hùm với một ít cơm và rau.Các loại bia không bao giờ đến, cũng không phải là gạo hay rau, chỉ là một đĩa nghêu và tôm hùm không có món ăn phụ, ngay cả khi chúng tôi trưng bày hình ảnh của gạo nhiều lần. Khi chúng tôi muốn đi xa và trả giá tôm hùm đã tăng gấp đôi và chúng tôi đã trả 26 € cho bữa tối ngay cả với đồ uống hoặc cơm!', '1 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sea R', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/9f/77/37/ugly-hotel-bai-xep-village.jpg?w=200&h=-1&s=1', 3, 'Vị trí đẹp nhưng hai khu phát triển khu nghỉ dưỡng xấu xí gần đó đang cố khẳng định bãi biển là riêng tư (tôi được cho biết rằng thực tế bãi biển thuộc sở hữu của làng) nhưng mong đợi có dấu hiệu của một nhân viên bảo vệ. Trong ngôi làng, khách sạn đáng ghét trong khuôn mặt của bạn có tên The Hidden Jewel là một tòa tháp xấu xí gồm 8 tầng, thống trị sykline của ngôi làng thấp tầng tại điểm gặp vbeach. Tôi được cho biết là nó được quy hoạch là một tòa nhà 2 tầng nhưng được phép xây dựng quá cao do bị mua chuộc.', '17 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'pippi1968maj', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/e0/6e/16/pippi1968maj.jpg?w=100&h=-1&s=1', 5, 'Một làng chài nhỏ xinh. Nhà hàng TỐT NHẤT tại Việt Nam, Mùa hè, nó nằm ở Bai Xep. Bãi biển sạch đẹp và môi trường an toàn.', '22 tháng 12, 2019', CURRENT_TIMESTAMP);

