    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Journey Johnie', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/3d/default-avatar-2020-55.jpg?w=100&h=-1&s=1', 4, 'Cảnh biển rất đẹp, đúng như tên gọi là eo gió, gió ở đây rất to, sóng to. Chỉ phù hợp để ngắm cảnh, không tắm biển được', '2 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'sharika', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Eo gió đẹp nhưng mà nắng lắm nha mấy bợn. Thích hợp với mấy chế muốn tắm nắng xạm da để lấy tồng Tây nè. Cảnh rất đẹp nhé . ......', '17 tháng 10, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr NHD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/89/19/3d/caption.jpg?w=100&h=-1&s=1', 3, '- Cách TP Quy Nhơn tầm 30 phút đi xe máy, chúng ta đến được Eo Gió, chỗ này là địa điểm các bạn phải đến khi tham quan Bình Định.- Dải đất miền Trung hiền hoà, biển vỗ rầm rì, các dải bờ biển xa tít trông rất đẹp & vô tận.- Cơ sở vật chất chưa tốt, có vài đoạn đi rất nguy hiểm, dễ trượt té.- Tôi quan sát thấy chỗ này không có nhà vệ sinh. 1 điểm trừ về điểm tham quan này.- Có 1 dãy hàng rào đặc trưng ven các tảng đá, thả mình vào thiên nhiên là có ngay các tấm ảnh xinh lung linh.', '8 tháng 1, 2024', CURRENT_TIMESTAMP);

