    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/5a/86/8b/ng-i-m-m.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hai Phan (Francis)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/3a/b3/e4/caption.jpg?w=100&h=-1&s=1', 5, 'Nằm cách trung tâm thành phố Qui Qui vài km. Nơi này có một số điểm đẹp như bãi đá Đá trứng, bãi cát yên tĩnh đẹp, lăng mộ của Han Mac Tu. . .', '16 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Justine D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/99/47/bf/photo0jpg.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi đi với ý định đến thăm bệnh viện không phải bãi biển Quý Hòa. Đó là một khung cảnh yên bình và thanh bình đáng kinh ngạc, chỉ cần đi bộ xung quanh trong hòa bình và yên tĩnh theo tốc độ của riêng bạn. Có nhiều ngôi mộ, tượng và bia mộ khác nhau để ngắm nhìn và đi lang thang xung quanh. Chúng tôi đã thực sự vào bệnh viện cũ (đã đọc rằng điều này là có thể) nhưng ngồi và có dừa bên bãi biển. Nếu một buổi sáng yên bình và yên tĩnh lôi cuốn bạn, hãy đến thăm. Xe buýt T 11 sẽ thả bạn trên con đường chính và bạn có thể đi bộ xuống ngọn đồi quanh co và đôi khi hẹp.', '1 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kute_Loan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/94/69/da/kute-loan.jpg?w=100&h=-1&s=1', 5, 'Bãi biển tuy chưa có nhiều dịch vụ vui chơi nhưng rất đẹp và sạch sẽ. Quy Nhơn đang dần trở thành địa điểm du lịch thú vị.', '11 tháng 9, 2018', CURRENT_TIMESTAMP);

