    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/c5/6e/de/an-duong.jpg', 0, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phạm Thuý Vân', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/9f/default-avatar-2020-16.jpg?w=100&h=-1&s=1', 5, 'Gia đình mình ra biển vào sáng sớm nên không khí rất dễ chịu và mát mẻ. Bãi biển khá yên tĩnh, thích hợp để đi bộ, ngắm biển và dành thời gian cùng gia đình. Buổi sáng ánh sáng đẹp, chụp ảnh cũng rất ổn. Một trải nghiệm đơn giản nhưng đáng nhớ trong chuyến đi Quy Nhơn.', '18 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Huyen88712', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 4, 'Bãi biển sạch, nước trong và không quá đông nên rất thích hợp để đi dạo hoặc ngắm bình minh. Chỉ cần đi bộ từ khách sạn là có thể tận hưởng khung cảnh biển rất đẹp và không khí trong lành.', '10 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bonet Agency', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 5, 'Bãi biển xanh đẹp lắm nhé. Mình đến Quy Nhơn rất thích biển ở đây rất xanh mướt, mát, sạch mà rất nhộn nhịp nhé', '6 tháng 7, 2026', CURRENT_TIMESTAMP);

