    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/1b/f9/ad/v-restaurant-view-from.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Cường', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 5, 'Lần đầu tiên đến với bình định, nơi chùa ông núi nơi trải nghiệm tâm linh tuyệt vời. Có nhiều sự trải nghiệm tuyệt vời ! Tượng phật Thích ca, khuôn viên đẹp rộng rãi, yên tĩnh.', '17 tháng 11, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr NHD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/89/19/3d/caption.jpg?w=100&h=-1&s=1', 5, 'Có dịp đến Quy Nhơn, các bạn nên dành thời gian đi tham quan và chiêm bái chùa Ông Núi. Ngôi chùa này cách Thành phố Quy Nhơn tầm 30-45phút đi xe máy. Cung đường đến đây khá hoang sơ và nhiều cảnh đẹp. Đi qua các trụ điện gió, các đồi cát bao la ngút ngàn...Đến nơi, là không gian yên bình và rộng rãi. Có 2 cách để đến được tượng Phật là đi xe máy ở ngay bãi xe có dịch vụ đưa đón với giá hợp lý, đi lên 40k, đi xuống 20k. Còn cách 2 là gởi xe máy 10k và leo bộ theo các bậc tam cấp để lên chánh điện.Khi lên đến nơi, chúng ta sẽ bao quát được cả 1 vùng Quy Nhơn vào tầm mắt, đồi núi & biển cả.Một nơi đáng để chiêm bái, trong chánh điện có tượng Phật bao phủ xung quanh, có cảnh Phật đản sinh, thành đạo, nhập Niết bàn...', '16 tháng 1, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hai Phan (Francis)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/3a/b3/e4/caption.jpg?w=100&h=-1&s=1', 5, 'Ngôi chùa được thiết kế ở một vị trí thực sự tốt đẹp. Tốt cho chuyến thăm tôn giáo ở Qui Qui. Bạn có thể đến đây sau khi ghé thăm Kỳ Co - Eo Gio', '16 tháng 2, 2020', CURRENT_TIMESTAMP);

