    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phan Thành', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng mới món ăn địa phương. Một địa điểm tuyệt vời! Nếu bạn đang ở làng chài Bãi Xếp, nhất định phải ghé qua nhà hàng này. Tôi đã thử cả món thịt và cá, cả hai đều tuyệt vời! Giá cả rất hợp lý, món ăn ngon tuyệt, và nhân viên thì vô cùng thân thiện. Tôi khuyên bạn nên thử món thịt nướng và cá nướng.  Thực đơn đa dạng và phù hợp với mọi khẩu vị. !', '7 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
