    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Coastal31711285442', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/3d/default-avatar-2020-1.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng ngon với view biển đẹp tại Quy Nhơn, rất đáng để trải nghiệm khi đến với Quy Nhơn nha. Có tiệc nướng BBQ ở biển. Các món ăn có trong menu để quán chế biến ngon, đậm đà hương vị. Nhân viên phục vụ (bạn tên Sương) nhiệt tình, hỗ trợ gia đình mình khi đến nhà hàng ăn uống', '21 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyen NK', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/9c/default-avatar-2020-14.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn ngon, nhân viên nhiệt tình. Mình đến đây để chúc mừng sinh nhật cùng gia đình. Nhà hàng phong cách Âu và có món đá muối rất đặc biệt làm mình rất ấn tượng. Phong cách phục vụ chuyên nghiệp, đặc biệt là bạn Hân đã tận tình tư vấn từ lúc mình đặt bàn đến hết buổi ăn', '30 tháng 4, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hưng Thịnh P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 5, 'Yên tĩnh, ấm cúng, lãng mạn và đẹp tuyệt vời. Đồ ăn ngon, không gian đẳng cấp và
các bạn nhân viên còn rất nhiệt tình nữa.
Món bò Angus đến từ quê hương Idol Messi thật tuyệt vời…', '27 tháng 5, 2024', CURRENT_TIMESTAMP);

