    VALUES (gen_random_uuid(), v_place_id, 'Guide61651990673', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Wonderful hotel. Nhà hàng ăn ngon, cô Sunny rất nhiệt tình, vui vẻ, rất đáng yêu, vv, rất recommend cho mọi người đến đây, đồ ăn ngon tuyệt vời, thư giản, hợp với gia đình và trẻ em. Trong tương lai sẽ quay trở lại', '2 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'chinhiz', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/14/e7/26/chinhiz.jpg?w=100&h=-1&s=1', 3, 'Không có gì đặc sắc. Ăn thử ở đây một bữa trưa nhưng không cảm thấy đẳng cấp của nhà hàng 5 sao của Avani . Bếp nấu bình thường , không gian không đặc sắc và giá thì chưa xứng với chất lượng . Các bạn cần cố gắng nhiều', '26 tháng 7, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'wes d', NULL, 5, 'Quy phúc, thành phố một trong những nhà hàng tốt nhất. Trong khi đi du lịch khắp miền trung Việt Nam, để tham quan lịch sử
Chúng tôi dừng chân tại thành phố Quy bào, để tham quan và tìm thấy chính mình trong một trong những nhà hàng trang trí nội thất đẹp nhất của các mặt hàng lịch sử không khí thư thái và tự nhiên. Thực đơn của nhà hàng này đi kèm với nhiều lựa chọn các món ăn được chế biến bởi các đầu bếp với ẩm thực Việt Nam rất ngon và ngon, dịch vụ thân thiện và chào đón và hầu hết giá cả cũng rất hợp lý cho cả người dân địa phương và du khách. Chúng tôi đề nghị nhà hàng này cho tất cả mọi người', '18 tháng 12, 2019', CURRENT_TIMESTAMP);

