    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Climber61331801763', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/a2/default-avatar-2020-3.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn ngon. Nhà hàng nhỏ nhưng ấm cúng, trang trí sinh nhật xinh xắn, món ăn nhìn bắt mắt, mình thích nhất món cá hồi salad và sườn nướng. Ăn nhanh quá chưa kịp chụp ảnh món, Mình đến cũng thấy rất nhiều khách nước ngoài họ cũng khen', '28 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
