    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/e5/cd/7f/photo4jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'John11', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 2, 'Bữa Tối. Quán hơi nhỏ , kiểu thức ăn nhanh , chất lượng pizza trung bình . so với tầm giá , giá bia hơi cao  :(', '3 tháng 4, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mathieu D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 4, 'Bia thủ công tuyệt vời!. Và thức ăn tuyệt vời, nhưng tia sét giết chết sự rung cảm của "quán rượu". Nó trông giống như một nhà hàng và điều đó hơi buồn bởi vì nó có thể là một quán bar / quán rượu to lớn!', '10 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nadine', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/81/2c/db/avatar.jpg?w=100&h=-1&s=1', 4, 'Pizza ngon, mì ống và bia, nhưng một chút giá cả.. Nghe nói những điều tuyệt vời về nơi này vì vậy đã thử nó. Địa điểm rất bận rộn nên chúng tôi phải chờ 30 phút để đặt bàn. Mặc dù vậy, chúng tôi không bận tâm và các nhân viên đã để mắt và cập nhật cho chúng tôi mặc dù nơi này rất bận rộn.

Chúng tôi đã chia sẻ một pasta napolina - rất tươi và ngon. Sau đó, chúng tôi đã gọi pizza - tôi yêu cầu không có phô mai trên pizza nhưng họ quên đề cập đến phô mai trong pesto và tôi cũng không nghĩ về điều này. Tôi biết ngay khi nhìn thấy chiếc bánh pizza có chứa phô mai. Chủ sở hữu đã thay đổi điều này cho tôi không có vấn đề và làm cho tôi một cái mới.

Một số loại bia ngon quá!

Nhược điểm duy nhất là nó khá đắt. Có một khoản phí 15% tet mà chúng tôi biết nhưng trước đó, hóa đơn được áp dụng là 550 k, đây là khoản tiền lớn nhất chúng tôi đã trả cho một bữa ăn trong 6 tháng ở châu Á - bao gồm cả ở các thành phố lớn.

Tuy nhiên, tôi sẽ quay trở lại', '28 tháng 1, 2020', CURRENT_TIMESTAMP);

