    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sharyn C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Xuất sắc. Tầm nhìn tuyệt vời từ quán bar trên tầng thượng và dịch vụ tuyệt vời, không thể tin rằng chúng tôi có toàn bộ mái nhà cho chính mình. Các món ăn rất đáng yêu, rất khuyến khích', '15 tháng 8, 2019', CURRENT_TIMESTAMP);

