    VALUES (gen_random_uuid(), v_place_id, 'Quest47454816841', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/3d/default-avatar-2020-55.jpg?w=100&h=-1&s=1', 5, 'Vui vẻ và hài lòng. Không gian đẹp, rộng rãi, thoáng đãng. Đi vào thời tiết nắng to nhưng không nóng. Dịch vụ ổn áp chu đáo. Đi chơi rất vui. Nước biển trong, san hô rất đã', '13 tháng 5, 2024', CURRENT_TIMESTAMP);
