    VALUES (gen_random_uuid(), v_place_id, 'Venture09725183311', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Ăn uống. Nhà hàng Cococamp tuyệt vời với không gian lãng mạn và hải sản tươi ngon. Khám phá một trải nghiệm ẩm thực độc đáo tại làng chài Nhơn Hải!', '28 tháng 3, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trail14401303038', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 5, 'Rất oki. Cảm nhận của chúng toi tất hài lòng về dịch vụ và có nhũng trai nghiện thật thú vụ Bền này lúc tối mấy tôi chơi camp thật thú vị và mát mẻ', '16 tháng 3, 2024', CURRENT_TIMESTAMP);

