    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phan Tuấn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/bb/54/9c/compass22540523982.jpg?w=100&h=-1&s=1', 5, 'Điểm đến không thể bỏ qua khi đến Phú Yên. Các cột đá xếp chồng lên nhau như những chiếc đĩa khổng lồ. Cảnh biển đẹp, đây là nơi lý tưởng để thư giãn và chiêm ngưỡng vẻ đẹp của thiên nhiên.', '9 tháng 8, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trần Lưu Đình Vũ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/9a/db/65/caption.jpg?w=100&h=-1&s=1', 5, 'Vẫn hoang sơ như trước khi Phú Yên phát triển du lịch. Là một địa điểm nhất định phải đến khi đến Phú Yên với những tảng đá xếp hình một cách độc đáo. Sự tạo hóa của tự nhiên đã biến nơi đây trở nên độc đáo', '23 tháng 6, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
