    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'flyingman1993', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/0d/66/92/flyingman1993.jpg?w=100&h=-1&s=1', 4, 'Đây là điểm đến lý tưởng cho những ai yêu thích tìm về với thiên nhiên, sự tĩnh lặng, hoài niệm để tìm đến cảm giác thanh thản từ trong tâm hồn. Giá vé 1 người là 50k, tuy nhiên đã bao gồm đồ uống và có bánh ít tráng miệng đi kèm thì cũng không hề đắt.', '13 tháng 2, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
