    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/da/c9/0e/manfrotto.jpg', 0, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/91/75/15/le-t.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tuan Anh Vu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/da/c9/0e/manfrotto.jpg?w=100&h=-1&s=1', 5, 'Một nơi mà chúng ta có thể hòa mình với biển, gió và mặt trời. Bạn bè tôi và tôi đến đó vào khoảng 2 giờ chiều, trời rất nóng và khô, độ ẩm thấp. Chúng tôi leo lên ngọn đồi và ngắm cảnh toàn cảnh đến hòn đảo nhỏ tên Hòn Yên nơi xưa kia con chim làm tổ trên đó. Thật là một tham quan tuyệt vời!', '29 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tam L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/91/75/15/le-t.jpg?w=100&h=-1&s=1', 5, 'Bãi biển tuyệt vời của nó để lặn san hô. Nó vẫn trông như ngôi làng tự nhiên và dễ dàng tiếp cận đảo chim yến khi thủy triều rút. Chúng tôi có thể thuê một chiếc ca nô với tài xế ard 500 k vnd cho một chuyến du lịch ngắn với lặn san hô và ngắm cảnh. Một điều tôi quan tâm là chúng ta cần giữ môi trường sạch sẽ trong khu vực này và bảo vệ hệ thống sống san hô. Rất khuyến khích cho cảnh này!', '1 tháng 8, 2019', CURRENT_TIMESTAMP);

