    VALUES (gen_random_uuid(), v_place_id, 'Connector26830593675', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/9e/6d/24/caption.jpg?w=200&h=200&s=1', 5, 'Tuyệt vời Món ăn ngon, giá rẽ bất ngờ, nơi đáng đến cho một kỳ nghĩ, nhân viên nhiệt tình, dễ thương, tôi đã đến nhiều l. Món ăn ngon, giá rẽ bất ngờ, nơi đáng đến cho một kỳ nghĩ, nhân viên nhiệt tình, dễ thương, tôi đã đến nhiều lần cùng với bạn bè của tôi', '16 tháng 4, 2025', CURRENT_TIMESTAMP);
