    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/c6/c5/53/khong-gian-quan-d-m-ch.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Olivia H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Quán ăn mang đậm chất thôn quê, không gian rộng rãi, đồ ăn ngon ở Tuy hòa, Phú yên. Mình đã ghé quán ăn cuối tháng 6 vừa rồi khi có dịp ra Phú Yên du lịch chơi. Quán tuy nhìn thôn quê nhưng lại ở trung tâm thành phố Tuy Hòa. Đồ ăn hải sản tươi ngon rất vừa miệng, chị chủ quán nhiệt tình dễ thương. Đặc biệt là không gian rất rộng rãi nhiều cây xanh, ăn uống no say ở quán xong bạn có thể đi xuống khu vực biển của thành phố Tuy Hòa để tham quan phố đi bộ dọc biển, chụp hình checkin tháp Nghinh Phong vừa mới xây rất ấn tượng. Gần đó cũng có khu hồ điều hòa nhiều cây xanh nữa. Đợt này ra Tuy Hòa thấy ráng đáng đồng tiền, có nhiều nơi để đi tham quan và ăn được đồ ăn ngon. Có dịp sẽ quay lại, hihi', '19 tháng 7, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Haonguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Ăn uống, tiếp bạn. Nhà hàng thoáng mát, thức ăn vừa miệng, đa dạng, phong phú, phong cảnh đẹp cho những ai thích chụp hình. Cô chủ thì vui vẻ', '4 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Han Do', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/a3/default-avatar-2020-38.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn ngon, đặc sản Phú yên hợp khẩu vị. Nhà hàng sân vườn nên rất rộng và thoáng, nằm gần núi nhạn nhiều cây xanh thân thiện môi trường, quán trang trí theo phong cách đồng quê Phú yên với mái lợp lá dừa, tạo cảm giác đặc trưng khác hẳn các nhà hàng khác ở thành phố Tuy hoà. Đồ ăn tươi được nấu liền khi order món, đặc trưng quán là các món lẩu và Hải sản tươi vừa đánh bắt. Ăn xong có thể đi bộ lên núi Nhạn tham quan, rất thuận tiện', '3 tháng 2, 2020', CURRENT_TIMESTAMP);

