    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/fd/ba/1d/front-entrance.jpg', 0, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/fd/b8/7a/img-20180122-114505040.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/fd/b8/7b/img-20180122-120227922.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vân Nam Phát', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/db/b7/0d/nhomkinhphuyen.jpg?w=100&h=-1&s=1', 4, 'ok. Cơm niêu Tuy Hòa – Đậm đà chất quê! – Cái tên và sologan rất bình dị thân quen nhưng không kém phần lịch lãm, sang trọng bởi những món ngon hoài cổ, đậm đà chất quê, cùng không gian bài trí, cây cảnh hài hòa. Đặt biệt dàn phong lan hàng trăm loài khoe sắc, thoảng hương một cách nhẹ nhàng, lãng mạng làm cho thực khách đến đây thêm phần khoái khẩu cùng bữa cơm quê dượm tình xứ sở “hoa vàng trên cỏ xanh”.

    Không chỉ chăm chút cho từng món ăn, Cơm niêu Tuy Hòa đã và đang hướng đến chất lượng dịch vụ trọn gói, chăm sóc hậu mãi cho khách khi sử dụng dịch vụ tại nhà hàng. Mới đây, nhà hàng Cơm niêu Tuy Hòa được Sở VH-TT-DL Phú Yên gắn biển cơ sở đạt chuẩn phục vụ khách du lịch', '6 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Peterneto20', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/59/default-avatar-2020-24.jpg?w=100&h=-1&s=1', 5, 'Nơi tuyệt vời. Rất khuyến khích nơi này để ăn cho mọi người đi du lịch đến Tuy Hòa, Phú Yên. Đồ ăn ở đây rất ngon', '12 tháng 6, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jacob G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Người gầy!. Thực phẩm tốt và quản lý thân thiện!

Nơi này rộng và sạch sẽ. . . bao gồm cả phòng tắm. Đó là một số hải sản tươi ngon nhất tôi tìm thấy - bạn có thể tự mình lấy ra. Họ có rất nhiều bãi đậu xe máy, đó là một lợi thế. Họ cũng có phòng tiệc riêng có sẵn cầu thang, và có thể tổ chức các sự kiện lớn. Tôi rất khuyên họ và dịch vụ tuyệt vời của họ!', '7 tháng 2, 2018', CURRENT_TIMESTAMP);

