    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'phip888', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/49/e3/08/phip888.jpg?w=100&h=-1&s=1', 5, 'Đảo Hòn Miêu là nơi ở của ngư dân địa phương, với kiến trúc xây dựng nhà ở đáng chú ý, rất yên tĩnh và phong cách sống thoải mái, nhưng một ngôi nhà câu lạc bộ kiểu khu nghỉ mát mini với hồ bơi là một bất ngờ.', '25 tháng 4, 2019', CURRENT_TIMESTAMP);

