    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'chanh chanh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 5, 'Tour Bình Ba Tết 2025 2 Ngày 2 Đêm tại SaiGon Star Travel để cảm nhận được vẻ đẹp hoang sơ của cùng những giây phút thư giãn tuyệt vời, thưởng thức tôm hùm và hải sản tươi sống.Bạn sẽ được trải nghiệm những khoảnh khắc thư giãn tuyệt vời giữa biển xanh cát trắng, tắm biển tại Bãi Nồm, ngắm san hô qua thuyền thúng, thưởng thức tiệc BBQ hải sản với tôm hùm tươi sống, và khám phá những địa điểm nổi bật như Chùa Ốc và Vườn Nho.', '28 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Gia Vũ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ed/00/default-avatar-2020-4.jpg?w=100&h=-1&s=1', 4, 'Bãi biển rất đẹp, nước trong xanh nhưng việc người dân khai thác mà không ta thức việc dọn rác cũng như bảo vệ môi trường thực sự quá phí tài nguyên. Vỏ đồ uống rất lung tung, tầu bè làm rỉ dầu trên mặt biển :((', '11 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mily', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/eb/default-avatar-2020-27.jpg?w=100&h=-1&s=1', 4, 'Lần thứ 2 đến đảo Bình Ba đã thấy bớt đi một chút vẻ hoang sơ. Khách du lịch đã nhiều hơn và có cảm giác đảo cũng không sạch như lần đầu đến. Hơi tiếc tuy thế vẫn có thể giới thiệu cho những ai chưa tới Bình Ba, nên đến một lần cho biết', '30 tháng 7, 2020', CURRENT_TIMESTAMP);

