    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Pedro maia', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/b6/b5/40/pedro-m.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đi tàu cao tốc đến đảo Son và có cơ hội thực hiện một số hoạt động chèo thuyền kayak và tắm nắng nhưng phần hay nhất là hướng dẫn viên du lịch của chúng tôi "Windy Fun" (tôi không biết viết hay nói như thế) thật buồn cười và hữu ích.Tour du lịch tuyệt vời Tôi khuyên bạn nên chắc chắn.', '25 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Fábio', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/9c/default-avatar-2020-14.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi lên thuyền đi Điệp Sơn. Đảo nhỏ nhưng tuyệt vời.Hướng dẫn của chúng tôi, Gió Windy (vẫn chưa biết cách đánh vần) rất hay và vui nhộn :)Muốn giới thiệu nó.', '25 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Geraldo pelliccioni', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 5, 'Chuyến tham quan tuyệt vời! Chúng tôi đến thăm đảo Diệp, nơi chúng tôi chèo thuyền trong một giờ, sau đó chúng tôi ăn trưa. Sau đó chúng tôi trở về đất liền và lái xe đến một bãi biển tuyệt vời nơi chúng tôi dành 2 giờ để bơi lội và thư giãn. Hướng dẫn, Uyên Phan rất vui vẻ và thân thiện! Tốt nhất!', '15 tháng 8, 2019', CURRENT_TIMESTAMP);

