    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/10/a9/73/f4/violet-n.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/ac/09/e3/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/17/c2/ad/photo4jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Violet Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/10/a9/73/f4/violet-n.jpg?w=100&h=-1&s=1', 4, 'Đó là một ngày nắng, hòn đảo thật đẹp với một con đường đi bộ nhỏ bằng cát, luôn có gió mát thổi qua, cảm giác thật tuyệt vời.Các hoạt động rất đơn giản, bao gồm bơi lội, chim yến tự nhiên, leo núi, lặn với ống thở.Nước trong vắt và trong lành, tuyệt vời cho môn bơi lội, tuy nhiên, có rất nhiều tảng đá làm tôi đau và bên kia có rất nhiều san hô mà tôi cần mang dép để bơi, nếu không, san hô sẽ cắt chân tôi.Trên thuyền để thăm tổ chim tự nhiên, tôi có thể nhìn thấy san hô qua kính đáy thuyền.Bữa trưa rất ngon** trên đường đến hòn đảo, đó là rất nhiều sóng, người mắc bệnh biển nên tự chuẩn bị vì phải mất 2 giờ.', '2 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KHlau', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/ac/09/e3/caption.jpg?w=100&h=-1&s=1', 5, 'Đây là hòn đảo ấm cúng, ẩn giấu và thư giãn cho nhiều người Việt Nam. Hình dạng và đặc điểm của hòn đảo là Tombolo, thực tập địa lý nên đây là danh lam thắng cảnh hiếm có. Bạn sẽ tìm thấy rất nhiều gia đình Việt Nam và có kỳ nghỉ của họ ở đây. Ăn trưa địa phương và các cơ sở bãi biển sang trọng có thể được tìm thấy. Tôi yêu nó rất nhiều! Xin đừng bỏ lỡ.Làm sao để tới đó:1) bạn phải tìm cửa hàng du lịch địa phương để mua vé (cho thuyền và ăn trưa)2) hoặc bạn có thể đến bến tàu và hỏi người địa phương (thông thường họ tính phí cao hơn)Lịch trình vận chuyển của họ là khoảng 715 sáng để khởi hành và 3 giờ chiều để trở về.Địa điểm là cảng Nha Trang.??????????????????????????????????????????? ??', '7 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trung N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Thực sự là 1 điểm đến không thể bỏ qua khi đến thành phố biển Nha Trang, mọi người sẽ được thưởng thức một bữa trưa ngon miệng, cảnh đẹp tuyệt vời, nước biển trong xanh, tất cả sẽ có tại Đảo Yến Hòn Nội', '20 tháng 7, 2018', CURRENT_TIMESTAMP);

