    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Minh Trần', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 4, 'Tháp Po Klong Garai là cụm đền tháp Chăm Pa cổ kính, được bảo tồn nguyên vẹn và đẹp nhất tại Việt Nam. Tọa lạc trên đồi Trầu (TP Phan Rang - Tháp Chàm), nơi đây mang đến sự kết hợp hoàn hảo giữa kiến trúc nghệ thuật độc đáo, văn hóa tâm linh và trải nghiệm ngắm nhìn toàn cảnh từ trên cao.', '15 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
