    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trang T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/bb/default-avatar-2020-65.jpg?w=100&h=-1&s=1', 5, 'Có xe điện chở từ cổng lên đến đỉnh. Chị hướng dẫn viên giải thích rất hay. Các công trình kiến trúc nhìn rất đẹp và thú vị. Theo lời chị hướng dẫn viên, nơi đây là rất linh thiêng đối với dân bản địa. Trên đường xuống còn có phòng trưng bày các tranh ảnh, trang phục, v.v. của văn hóa thời xa xưa', '29 tháng 10, 2024', CURRENT_TIMESTAMP);

