    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/66/7d/b9/tom-hum-h-p-t-i-nha-hang.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoang Hoa V', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng đầu tiên ở NT với phong cách này ! Sẽ trở lại !. Nhà hàng này của khách sạn Hoàn Mỹ mới “tách ra riêng”nhưng vẫn ở bên cạnh hotel. Tạo cho khách một không gian trải nghiệm ẩm thực cao cấp hơn, tiêu chuẩn quốc tế hơn, tránh bị chìm trong những đoàn náo nhiệt ! Chúng tôi ăn tối, dược đề nghị một con cá cho 2. Nửa làm sashimi - rất tươi, rất ngon, trình bày ok. Nửa kia nướng. Đầu bếp chế biến món ăn tinh tế. Phòng ăn thoáng, lịch sự, không ồn ào. Nhân viên kín đáo, phục vụ rất tốt. Giá cả theo chất lượng kể trên. Chỉ mong là nhà hàng sẽ giữ được như vậy lâu dài !', '25 tháng 2, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tran Triet', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 5, 'tuyệt vời. Tình cờ ghé nhà hàng vì gần khách sạn. Quán thoáng mát, sạch sẽ và ấm cúng ngay bãi biển, nhân viên nhiệt tình, món ăn ngon, giá rẻ', '29 tháng 7, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Đạt S', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/2e/default-avatar-2020-67.jpg?w=100&h=-1&s=1', 5, 'Đã đến biển Bình Sơn,Ninh Thuận thì nhất định phải ghé nhà hàng Hải Âu!. Hải sản tươi ngon!thức ăn được chế biến đạt tiêu chuẩn,đẳng cấp mà lại rất rẻ nha!
Khung cảnh tuyệt đẹp với không gian thoáng đảng hướng tầm nhìn ra biển lộng gió!
Nhân viên nhiệt tình và chuyên nghiệp.
Tôi sẽ quay trở lại đây và sẽ giới thiệu nhà hàng để bạn bè gần xa cùng đến!', '21 tháng 7, 2019', CURRENT_TIMESTAMP);

