    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/27/c5/3f/90/pizza-le-napoli-phan.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/a1/07/2f/photo4jpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/57/46/02/photo0jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'JEAN C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'ĐỪNG BỎ LỠ !. Tôi đã ra lệnh giao pizza vì chúng tôi có một bữa tiệc gia đình vào tối hôm đó.
Tất cả 7 chiếc pizza đều nổi bật.
Bột là đặc biệt, nứt và ngon.
Toppings là tươi và hào phóng.
Lần tới chúng tôi sẽ có một bữa tối tại nhà hàng với cả gia đình và thưởng thức các khóa học khác, như mì ống. . . . Mà tất cả nhìn cũng ngon.
Một lần nữa xin cảm ơn Le Napoli đã đóng góp rất độc đáo để làm cho ngày của chúng tôi trở nên đặc biệt', '3 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Rach', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/bb/default-avatar-2020-65.jpg?w=100&h=-1&s=1', 5, 'Thật là một viên ngọc. Sau 2 tuần ở Việt Nam, chúng tôi rất thích một số món ăn phương Tây. Bánh pizza ở đây là một số bánh pizza ngon nhất tôi đã ăn trong đời! ! Dịch vụ cũng tuyệt vời! Thất vọng tôi chỉ ở Phan Rang trong 1 đêm và có thể trở lại', '17 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kimberly', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1d/89/bd/bf/kimbro5684.jpg?w=100&h=-1&s=1', 5, 'Thơm ngon. Pizza thật tuyệt vời! Dừng lại vào ngày cuối cùng của chúng tôi trở lại các tiểu bang và thực phẩm là tuyệt vời! ! Chúc chúng ta sống gần hơn!', '10 tháng 8, 2019', CURRENT_TIMESTAMP);

