    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'phu0ngle2017', NULL, 5, 'Ngon, nhiều loại hải sản. Hải sản ở đây tươi sống, nhiều loại để lựa chọn (quên không chụp hình lại).. vào nhà hàng thì đừng bao giờ mong đợi giá rẻ bèo kiểu ở quán vỉa hè bình dân, nhưng nó vừa tầm với một nhà hàng như vậy. Không gian rộng, có thể ngồi bên trong quán, hoặc đặt bàn ngay ngoài bãi biển cho thoáng mát hơn. Ngoài ra quán có chỗ đậu xe rất rộng
Tối hình như họ có dịch vụ karaoke loa kẹo kéo nữa))', '13 tháng 10, 2018', CURRENT_TIMESTAMP);

