    VALUES (gen_random_uuid(), v_place_id, 'Thanh Vân', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 5, 'Cát rất mịn, đi cùng bạn bè trượt ván rất vui', '4 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'OnAir33830037079', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 4, 'Đồi Cát Trắng Mũi Né là một điểm đến rất đẹp và ấn tượng. Cảnh quan rộng lớn, cát trắng trải dài, đặc biệt đẹp vào sáng sớm hoặc chiều muộn. Mình rất thích không khí thoáng đãng và cảm giác ngắm hoàng hôn giữa đồi cát. Đây là nơi khá lý tưởng để chụp ảnh và trải nghiệm khi du lịch Mũi Né.', '16 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
