    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/dd/8d/6e/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Asahi Dương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/e0/37/00/caption.jpg?w=100&h=-1&s=1', 4, '• Điểm cộng: Khung cảnh biển buổi sáng sớm tuyệt đẹp với hàng trăm chiếc thuyền thúng rực rỡ sắc màu, rất thích hợp để chụp ảnh check-in. Hải sản tại đây vừa được đánh bắt lên nên siêu tươi ngon, giá thành lại rẻ và có thể nhờ người dân chế biến, thưởng thức tại chỗ.• Điểm trừ: Khu vực bờ biển bám mùi tanh đặc trưng và còn tình trạng xả rác thải, vỏ hải sản gây mất mỹ quan, hoàn toàn không thích hợp để tắm biển. Du khách mua đồ ở đây cũng nên chủ động mặc cả để tránh bị nói thách.', '12 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'thùy trang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/99/default-avatar-2020-40.jpg?w=100&h=-1&s=1', 5, 'Mặt trời mọc ở làng chài. Phong cảnh tuyệt vời, thuyền, chợ câu cá. Địa điểm ngắm mặt trời lặn đẹp nhất mà tôi biết và cũng là điểm checkin chụp ảnh lý tưởng', '18 tháng 5, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lâm Thuỷ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 4, 'Cảnh đẹp, đồ ngon nhưng dễ bị chặt chém giá nếu bạn không nắm rõ giá Hải sản. Cần mặc cả nhiều. Sáng sớm và hoàng hôn rất đẹp để thăm.', '17 tháng 6, 2021', CURRENT_TIMESTAMP);

