    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'luongthanhh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/10/d2/d3/luongthanh-n.jpg?w=100&h=-1&s=1', 5, 'Thích hợp đi phượt hoặc nghỉ dưỡng, vừa  có biển, vừa có núi, dù là chỗ du lịch cũ từ hai ba chục năm nhưng vẫn rất ok để khám phá. Bạn nên thuê thêm xe jeep để leo cồn cát, cực kỳ thú vị. Và ký ức làm mình nhớ mãi không quên đó là leo cồn cát chưa bao giờ leo tới đỉnh.', '11 tháng 9, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lam P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/59/default-avatar-2020-49.jpg?w=100&h=-1&s=1', 1, 'Chúng tôi từ mũi né về bxmt, nhưng khi lên xe có vài bịt bánh oxi dành cho bé nhưng chưa sử dụng . Vì ngăn cặp không đủ chỗ chứa nên đã mang cùng túi xách . Nhưng khi lên tài xế 1 mực k cho đem bắt bỏ lại gầm xe , chúng tôi đã giải thích sẽ không sử dụng gây mùi trên xe , nhưng tx vẫn tỏ vẻ khó chịu và bắt để ngay trước xe mới chịu . Dịch vụ xe kém khi lên k có khăn hoặc nước . Xe ngồi vé 190k nhưng k điều khiển được .', '4 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'tran', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/08/0e/f6/caption.jpg?w=100&h=-1&s=1', 4, 'Resort 4 sao có bãi biển riêng hồ bơi cho trẻ em và hồ bơi tràn cho người lớn . buffer sáng có nhiều sự lựa chọn đặc sản địa phương cũng có ở tại quầy phục vụ ăn sáng cho khách , tuy nhiên cá nhân tôi không thật sự hợp khẩu vị nhà hàng khu vực ngồi ăn sáng nằm sát bờ biển mang lại cho tôi cảm giác thư giãn khi nghỉ dưỡng tại đây . một số bức ảnh tôi đã chụp tại đây các bạn có thể tham khảo .', '7 tháng 5, 2024', CURRENT_TIMESTAMP);

