    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kieu Oanh P', NULL, 3, 'Nhóm mình đến lúc chiều, đi xe riêng chứ ko đi tour. Tới nơi mới biết là giờ không còn cho thuê xe ở đó nữa mà phải thuê xe từ trong thành phố của các công ty du lịch. Giờ chỉ còn đi dạo và trượt cát. Hơi buồn', '28 tháng 7, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Du Lịch Mũi Né', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Điểm chụp ảnh tuyệt vời, đặc biệt là ngắm bình minh và hoàng hôn. Ngoài ra còn có thể chơi trò trược cát thú vị cùng bạn bè.', '16 tháng 7, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'kiều mai', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Bãi cát đẹp, có thể nói không có bãi cát nào đẹp bằng bãi cát ở Bình Thuận. Mình đến vào buổi chiều và có thể ngắm nhìn hoàng hôn với ánh nắng mặt trời tuyệt đẹp', '18 tháng 5, 2022', CURRENT_TIMESTAMP);

