    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/0e/28/b5/good-restaurant-in-mui.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Son', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/5a/53/f2/jasonnguyen133.jpg?w=100&h=-1&s=1', 3, 'Được tìm hiểu sâu hơn về lịch sử nước mắm Phan Thiết, từ cách thịnh hành phát triển từ thời xa xưa cho đến những con người có công trong việc hình thành nó.Tuy nhiên bảo tàng không tạo cho người những trải nghiệm đáng giá, với việc phải trả giá vé tham quan 100.000,00 VND/ người nhưng du khách không được tham gia các hoạt động về cách làm hay những hoạt động tương tự. Bên cạnh đó, người hướng dẫn tour đi rất nhanh về các vấn đề, về các hiện vật nên một tour như vậy chỉ mất có 10'' hoặc ít hơn là hết bảo tàng, còn lại là du khách lại phải trải qua "tour" shopping về nước mắm. Không xứng đáng với giá phải trả, quá mắc.', '6 tháng 8, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Duy Anh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/6a/default-avatar-2020-47.jpg?w=100&h=-1&s=1', 5, 'Một địa điểm du lịch thật sự thú vị, tôi đã được trải nghiệm không gian làng chài, tìm hiểu lịch sử nước mắm, văn hoá chămpa và có thật nhiều bức ảnh xưa thật độc đáo 😊', '24 tháng 6, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyễn Hiền', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Xem hình ảnh và bài viết nhiều rồi. Nhưng phải đi vào thực tế bên trong mới cảm nhận đúng được sự thú vị của nơi này. Nơi người già có thể tìm lại được cảm xúc ngày xưa, tuổi trẻ thì khám phá lịch sử. Thật sự thú vị.', '24 tháng 6, 2020', CURRENT_TIMESTAMP);

