    VALUES (gen_random_uuid(), v_place_id, 'Bianca E', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2a/fd/97/avatar.jpg?w=100&h=-1&s=1', 5, 'Ngôi đền này gần với cồn cát trắng. Có thể đến thăm cả hai cùng một ngày. Các khu vườn và phật là tinh tế. Tôi thích sự yên tĩnh của nơi này. Thật là yên bình và tuyệt vời.', '11 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sara A', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/6d/29/3c/sara-a.jpg?w=100&h=-1&s=1', 4, 'Một bagoda đẹp với rất nhiều điều thú vị. Chắc chắn giá trị tham quan, hãy nhớ không bước trên ngưỡng cửa và cởi giày của bạn. Quan trọng để che vai của bạn cũng!', '14 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Valdemaras69', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/b0/a6/a7/avatar.jpg?w=100&h=-1&s=1', 5, 'Nếu bạn dành thời gian ở Mũi Né, hoặc gần, Bạn phải ghé thăm nơi này. Yên tĩnh. Tốt đẹp. Không có gì thực sự đặc biệt, nhưng thực sự tốt đẹp. Templ giáo viên thực sự. Ngủ Buda 25 mét. Aura thực sự tốt đẹp!', '6 tháng 1, 2018', CURRENT_TIMESTAMP);

