    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/37/be/60/g-i-bo-s-t-thai.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'rikdjong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/f7/c0/21/rikdjong.jpg?w=100&h=-1&s=1', 2, 'Chúng tôi đã ghé thăm chợ vào một buổi sáng và mặc dù rất thú vị khi thấy cá địa phương và sản xuất theo yêu cầu, nó chỉ quá đông đúc và xô đẩy nên chúng tôi phải đi. Một vài ngày sau, chúng tôi trở lại vào khoảng thời gian ăn trưa khi tất cả cá và sản phẩm đã biến mất và tìm thấy một nơi bẩn thỉu với cùng một thứ plasic Trung Quốc rẻ tiền. Hãy bỏ lỡ.', '29 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'John W', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/10/default-avatar-2020-8.jpg?w=100&h=-1&s=1', 4, 'Trong tất cả các doanh nghiệp phục vụ cho du khách nước ngoài, đây thực sự là một lát cắt của cuộc sống địa phương đích thực. Đó là bận rộn, đông đúc và đầy màu sắc. Các sản phẩm để bán là tươi - một nơi tốt để mua trái cây. Một số quầy hàng phục vụ các bữa ăn đơn giản và đồ ăn nhẹ bao gồm cả yêu thích của tôi, một phụ nữ thích tán tỉnh, làm cho ph rẻ, ngon.', '19 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Patsy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/96/74/1b/patsy1962.jpg?w=100&h=-1&s=1', 3, 'Chúng tôi đã đi đến các chợ MũiNe vì nghiêm túc là rất nhiều xung quanh MũiNe hoặc Phan Thiết trong cách mua sắm. Có thêm một vài quầy hàng với quần short adidas hoặc trẻ em mặc vv, nhưng don rất mong đợi. Các sản phẩm tươi là một mắt mở cho những người trú ẩn đã trải nghiệm cách một số quốc gia sống! ! !', '18 tháng 7, 2019', CURRENT_TIMESTAMP);

