    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/d6/ad/ad/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Food & Drink Junkie', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, 'Trong khi đi nghỉ, chúng tôi tìm thấy vàng. Trong khi đi nghỉ, chúng tôi đã gặp Modjo và tôi rất vui vì chúng tôi đã làm vậy. Nhóm bốn người, chúng tôi đã có một bữa ăn 4 món với 3 chai rượu vang đỏ. Món bít tết rất tuyệt, và bảng phô mai chỉ là món ngon nhất tôi có ở Việt Nam. Tôi đã sống ở Việt Nam hơn 3 tháng tại TP HCM và tôi cũng là một đầu bếp từ quê nhà ở Anh. Các hóa đơn là rất tốt đối với thực phẩm. Các nhân viên đã được tại chỗ!
Chắc chắn sẽ trở lại!
Làm tốt lắm Modjo

Trân trọng

Đầu bếp Jay
nước Anh', '15 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Charlotte G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Thơm ngon!. Chúng tôi đã có đĩa phô mai và thịt và nó rất ngon! Dịch vụ tuyệt vời và không khí! Chắc chắn sẽ đề nghị!', '11 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Louise and Derek', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 5, 'Xuất sắc. Chúng tôi đã có một bữa ăn tuyệt vời và khung cảnh và bầu không khí rất tinh vi.
Chúng tôi có thể nhìn xuyên qua nhà bếp và nó là không tì vết.
Các nhân viên thân thiện và hiệu quả.
Giá trị lớn cho tiền được trình bày và chất lượng cao của thực phẩm.
Chúng tôi chắc chắn sẽ trở lại sau trong chuyến đi của chúng tôi', '8 tháng 11, 2019', CURRENT_TIMESTAMP);

