    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/03/cb/f7/20181012-182401-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Daniel', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'Thực phẩm và dịch vụ tuyệt vời!. Chúng tôi ở lại khu vực này trong 5 ngày và ăn tối ở đây gần như mỗi đêm, mặc dù chúng tôi đã thử những nơi khác, chúng tôi vẫn tiếp tục quay lại nơi này. Khu vực foodcourt có một bầu không khí tuyệt vời và có rất nhiều chich khác nhau, nhưng cái này là tốt nhất! Hét lên cho nước chanh của họ! ! Chúng tôi thực sự khuyên bạn nên thử nơi này!', '16 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'taffbryn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 5, 'Thịt bò tiêu đen cay cay. Tôi yêu cầu nó cay và nhận được những gì tôi yêu cầu. Dịch vụ nhanh. Nằm trong khu ẩm thực Đông Vui. Rất đáng để ghé thăm. Cũng là một quán bar tuyệt vời bên cạnh', '16 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'MANTA-MuiNe', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/cd/af/c9/manta-muine.jpg?w=100&h=-1&s=1', 5, 'Tôi yêu nước chanh tự làm của họ!. Điểm dừng chân đầu tiên của tôi tại Food Court là đây - cho húng quế - nước chanh gừng - hoặc nước ép trái cây đam mê: sảng khoái nhất!

Một sự lựa chọn tuyệt vời của cơm chay, mì, cà ri quá', '7 tháng 11, 2019', CURRENT_TIMESTAMP);

