    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/31/0b/f2/76/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tue Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ba/5e/d9/caption.jpg?w=100&h=-1&s=1', 3, 'Thác đẹp tuy nhiên khai thác du lịch chưa hợp lý nên chưa làm nổi bật được vẻ đẹp của thác ở vùng tây nguyên xinh đẹp này.Làm du lịch hơi tự phát.', '1 tháng 9, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Paradise01332560798', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/16/f5/e7/caption.jpg?w=100&h=-1&s=1', 4, 'Cảnh đẹp. Đường dễ đi. Đi thôi mn ơi. Không khí măng đen dễ chịu. Không xô bồ như những nơi khác. Ngoài thác pa sỹ chúng ta có thể tham quan ruộng bậc thang. Và nhiều điểm khác', '8 tháng 8, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'XUÂN LỢN MẸT TÂY BẮC', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/74/13/20/caption.jpg?w=100&h=-1&s=1', 5, 'Thật tuyệt vời cùng nhóm bạn trải nghiệm Măng đen- Con người thân thiện vô củng, thời tiết luôn mát mẻ chiều lòng người, đồ ăn thức uống tuy còn đơn sơ, nhưng cảm nhận các vị mới lạ so với vùng miền mình đang sinh sống. Khung cảnh đẹp tuyệt vời, vẫn giữ được nét hoang sơ của mẹ Thiên nhiên.Thác Pa sỹ nét đẹp tự nhiên của núi rừng.Đức Mẹ Măng đen thiêng liêng và huyền bíChùa Khánh Lâm khuôn viên thanh tịnh và đẹp hoang sơ với rừng hoa sim tím.… và còn rất rất nhiều cảnh đẹp, điểm đến đẹp và thơ mộng mình chưa đến được vì quỹ thời gian có hạn.Mình sẽ hẹn gặp Măng Đen vào ngày gần nhất.', '25 tháng 5, 2023', CURRENT_TIMESTAMP);

