    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/7c/1c/10/daniel-a.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/a2/86/0f/photo1jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Daniel A', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/7c/1c/10/daniel-a.jpg?w=100&h=-1&s=1', 3, 'Đó là một nơi để kiểm tra nếu bạn đang chán và gần Busan Station. Nó không phải là một nơi phải đi. Có một số nhà hàng và một số thứ văn hóa để làm ở đó. Nhà thông tin du lịch thực sự là niềm vui cho con tôi vì chúng có bút chì và phòng vệ sinh sạch. Nhưng thực sự không phải là rất nhiều để làm trừ khi bạn muốn một massage. Tôi mang theo con tôi và chúng tôi đi bộ qua nhanh chóng.', '17 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Danis L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 5, 'Có rất nhiều việc để làm ở Busan thư giãn hơn nhiều so với Seoul. . Rất nhiều nhà hàng hải sản và nhà hàng trên bãi biển. . . .', '8 tháng 10, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Leonie A T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 2, 'Nơi đáng thất vọng được gọi làKhu phố Tàu. Nó rất yên tĩnh và hầu như trống rỗng ngay cả vào ban ngày và cả vào buổi tối mà tôi đã đến thăm. Nhiều cửa hàng đã đóng cửa và không thể tìm thấy một nhà hàng tốt nào cả. Có một số nhà hàng hoặc cửa hàng không phải của Trung Quốc mà là của Nga, bạn có thể hiểu điều này từ tên của cửa hàng hoặc bảng chữ cái mà họ đã sử dụng.', '22 tháng 8, 2022', CURRENT_TIMESTAMP);

