    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/e2/0c/4a/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Westheath', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Rất vui vì chúng ta đã đặt tour ''VIP''. Hướng dẫn viên của chúng tôi đã kéo chúng tôi ra khỏi hàng người và chuyến tham quan của chúng tôi bắt đầu đúng 10 giờ sáng. Tòa nhà rất đẹp. Chuyến tham quan diễn ra rất tốt, hướng dẫn viên của chúng tôi cực kỳ am hiểu và thật tuyệt khi có thể đặt câu hỏi và nhận được câu trả lời thực tế. Chúng tôi đã có thể đứng giữa vòng bò nơi hướng dẫn viên vỗ tay. Âm thanh thật tuyệt vời. Chúng tôi hiểu nhiều hơn về đấu bò bây giờ. Có nhiều điều hơn thế mà chúng ta nhận ra và mặc dù tôi vẫn không muốn xem một buổi biểu diễn trực tiếp, tôi vô cùng kính trọng lịch sử/văn hóa/thể thao này. Chắc chắn là một điểm nhấn lớn trong chuyến đi Madrid của chúng tôi.', '28 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Chris D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Đáng khuyên tour này. Lelia đã cho chúng tôi một câu chuyện thú vị và đầy thông tin về tất cả các khía cạnh của chiến đấu bò. Cô ấy rất vui khi được ở bên.', '28 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'JLWK2015', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2e/70/60/avatar038.jpg?w=100&h=-1&s=1', 5, 'Một trải nghiệm độc đáo, tôi luôn luôn muốn xem một cuộc chiến bò sát trực tiếp, chúng tôi may mắn được ở Madrid cho một cơ hội, đây là những con bò sát trẻ, khoảng 500 Kgs và matador trẻ. Đơn giản là pomp và truyền thống. Sẽ không giới thiệu cho những người squeamish, nhưng tôi muốn xem các truyền thống.', '26 tháng 6, 2026', CURRENT_TIMESTAMP);

