    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Oliver Touri', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'gà nướng cơm lam. Gà nướng ngon và ra đồ ăn cực nhanh.Xôi hơi cứng', '15 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lê Đỗ Hoàng Long', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Bữa ăn ngon nhất ở Măng Đen. Tôi đi Măng Đen 2.5 ngày với bà xã, thì đây là bữa ăn ngon nhất. Gà nướng rất khéo, vừa tới mà không bị khô, ăn giòn rụm & ngon. Cơm lam cũng ngon, thịt xiên cũng ngon.

Bạn nào đến ăn thì có thể chủ động ghé mua & tự bưng ra chỗ mình ngồi, vì nhà hàng khá đông, nếu đợi phục vụ thì có thể hơi lâu xíu', '16 tháng 2, 2022', CURRENT_TIMESTAMP);

