    VALUES (gen_random_uuid(), v_place_id, 'Oliver Touri', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Thác nước chảy mạnh,Phù hợp đi phượt.', '16 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Linda Sz', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/8b/7a/f3/lindaszyi.jpg?w=100&h=-1&s=1', 5, 'Chắc chắn là xứng đáng để đến thăm và thư giãn! Chỉ cần một ít tiền cho bãi đậu xe tay ga. Bạn có thể thấy nhiều người dân địa phương đến để nướng một số bữa ăn dưới tán cây dưới chân thác. Nơi bình yên!', '9 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phuong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/1c/13/14/avatar.jpg?w=100&h=-1&s=1', 3, 'Cách trung tâm thành phố Pleiku 50 km, bạn có thể đến Công viên giải trí Phú Cường, nơi thác nước là điểm thu hút chính. Công viên này sẽ tốt hơn nếu bố trí dễ tiếp cận hơn cho người già đi xuống để xem nước. Đi một nửa ngày tới đây là một chuyến đi khá dễ chịu vì đường, Quốc lộ 14, thực sự tốt để lái xe.', '9 tháng 3, 2020', CURRENT_TIMESTAMP);

