    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mây Nguyễn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/06/7a/e0/thu-van-n.jpg?w=100&h=-1&s=1', 4, 'Mình đến đây lần thứ 2, trời trong xanh nắng đẹp hơn lần đầu mưa lất phất, chỗ nhà mát lúc trước được xây dựng lại có đặt tượng Phật Quan Âm và được chỉnh trang đẹp hơn. Hồ vẫn đẹp và xanh, nguồn cung cấp nước cho cả thành phố  Pleiku xinh đẹp. Nói chung nếu đến Pleiku bạn nên ghé thăm điểm này.', '2 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
