    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thùy Linh Đ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, '🌋 Núi lửa Chư Đăng Ya (cách trung tâm 17km - là 1 ngọn núi lửa đã tắt hàng triệu năm) Y vì chưa vào mùa hoa màu (đẹp nhất là vào độ tháng 10-12) nên chỉ có đất cằn sỏi đá, nhưng cũng may mắn vì bắt gặp được cây cô đơn trên nè lúc hoàng hôn.Đường leo lên đỉnh tương đối dễ đi (có độ cao tầm 500m so với mực nước biển) tuy chỉ có đoạn leo 🧗‍♀️ bậc thang (không rõ bậc lắm nên rất lúc xuống khá trơn trượt, đoàn mình có mấy bạn nhanh trí tìm luôn nhành cây khô quanh đó làm gậy chống)', '19 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Quỳnh Hội', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 4, 'Một điểm đến rất hoang sơ với núi lửa và những người dân bản địa trồng cây củ chuối để chế biến ra miếng dong và một số dân trồng khoai lang trên những triền núi nhìn rất đẹp tuy nhiên sự đầu tư cho du lịch và các dịch vụ phục vụ cho du khách vẫn còn nhiều thiếu thốn ,cần phải quan tâm đầu tư nhiều hơn nữa.', '13 tháng 3, 2019', CURRENT_TIMESTAMP);

