    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khanh H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/cb/96/79/khanh-h.jpg?w=100&h=-1&s=1', 5, 'Vườn quốc gia Kon Ka Kinh nằm trong khu vực giữa Đông và Tây của dãy Trường Sơn, ở thung lũng sông Ba. Vườn Kon Ka Kinh lấy tên đỉnh núi cao nhất, cao 1.748m so với mực nước biển cùng tên làm tên gọi. Đỉnh núi này còn được mệnh danh là “nóc nhà của tỉnh Gia Lai”. Kon Ka Kinh là một trong số 27 vườn của khu vực Đông Nam Á được công nhận là di sản ASEAN.Đây là nơi thích hợp cho các du khách thích khám phá thiên nhiên.Đến đây, bạn sẽ phải tuân thủ các quy định về bảo vệ rừng và tài nguyên, chỉ để lại dấu chân, không được xả rác và phá phách.Hy vọng bạn sẽ đặt chân đến đây một lần.', '24 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trần Minh Hội', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/74/default-avatar-2020-68.jpg?w=100&h=-1&s=1', 5, 'đây là khu rừng nguyên sinh được bảo tồn , nơi đây còn nhiều động vật quí hiếm , mình đến đây trong chuyến khảo sát với các bạn du lịch cộng đồng Việt nam , hồ nước trong xanh -thác nước đẹp vô cùng chỉ có điều là phải đi bộ mới tới các điểm này nếu như xe ô tô tới được thì thì sẽ thu hút được nhiều du khách .', '16 tháng 3, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
