    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Voyage49809763705', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 5, 'Hoàng hôn buông xuống Biển Hồ như một bức tranh thủy mặc khổng lồ. Mặt trời đỏ rực từ từ lặn xuống phía chân trời, nhuộm cả mặt hồ một màu cam rực rỡ. Những tia nắng cuối cùng còn sót lại chiếu xuống mặt nước, lấp lánh như dát vàng. Xa xa, những chiếc thuyền đánh cá của ngư dân chầm chậm trôi, tạo nên một khung cảnh thanh bình, yên ả.', '27 tháng 7, 2025', CURRENT_TIMESTAMP);
