    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/cb/96/79/khanh-h.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Gialai Ecotourist Co., Ltd', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/41/be/3e/gialaiecotourist.jpg?w=100&h=-1&s=1', 5, 'Cỏ Hồng hay còn gọi là cỏ lông heo chỉ có từ tháng 11 - 01 hàng năm, là thảm cỏ thấp trong gần các  rừng thông.  Màu của cò phụ thụ vào nhiệt độ, ành sáng, sương. Nếu bạn muốn có những bức ảnh đẹp chuyến đi trãi nghiệm thú vị xin hãy liên hệ  Gialai Ecotourist Co,. Ltd  0913157462 Ms Nga - 0976144977 Ms Anh chuyên tour Tây Nguyên.', '31 tháng 5, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khanh H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/cb/96/79/khanh-h.jpg?w=100&h=-1&s=1', 5, 'Đồi cỏ hồng tọa lạc ở huyện Đắc Đoa, Gia Lai.Cỏ hồng là một loại cỏ dài, được nhiều người biết đến với tên gọi khác là cỏ đuôi chồn. Vào mỗi dịp đầu đông, thời tiết trở lạnh, những bông hoa cỏ sẽ đổi sang một màu hồng tím vô cùng hút mắt. Những cánh đồng cỏ trải dài càng tạo nên một khung cảnh nên thơ, mơ mộng.Có 3 địa điểm ngắm cỏ hồng đẹp nhất ở Gia Lai: một là thung lũng cỏ hồng ở xã Glar, huyện Đak Đoa, cách trung tâm thành phố Pleiku khoảng 20km; địa điểm thứ hai là ở Núi Đá, thành phố Pleiku; và địa điểm thứ ba là hai bên rừng thông trên đường đi cửa khẩu Lệ Thanh, huyện Đức Cơ.Hãy đến để hòa mình vào thiên nhiên và có những bức hình thật đẹp cho bản thân nhé.', '25 tháng 11, 2019', CURRENT_TIMESTAMP);

