    VALUES (gen_random_uuid(), v_place_id, 'Tưởng Hữu Lộc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/ae/1f/40/caption.jpg?w=100&h=-1&s=1', 5, 'Bữa ăn tối tuyệt vời tại Gia Lai và Tây Nguyên. Quán ăn phục vụ những món ăn Tây Nguyên ngon tuyệt và ông chủ rất thân thương, nhiệt tình! Sẽ còn quay lại đây nhiều lần nữa. 
Đặc biệt là món gỏi lá và gà nướng ngon tuyệt!', '7 tháng 7, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Gialai Ecotourist Co., Ltd', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/41/be/3e/gialaiecotourist.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng nhà tôi  điểm đến trong hành trình về phố núi Pleiku. Đến Nhà Tôi du khách nên thưởng thức nón gỏi lá- một trong những đặc sản độc dáo Tây Nguyên. Món ăn không chỉ là sự hòa quyện hương vị lá cây cùng nước chấm  được làm từ xương & gan cá mà còn là sự kết hợp của các lá cây thảo dược. Vế  Nhà Tôi trong không khí đón tiếp nồng hậu của anh chị chủ Nhà Tôi, thưởng thức bầu không khí trong lành thoáng mát', '21 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoàng Thuyên', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/71/ca/b3/photo0jpg.jpg?w=200&h=200&s=1', 5, 'Chỗ ở tuyệt vời với giá  bình dân. Chỗ ở tuyệt vời với giá vô cùng bình dân. Đồ ăn phong phú và đặc biệt hấp dẫn với món Gỏi lá và lẩu Xìn Đạt! Không gian nhà hàng rất rất tuyệt!!! Nhất định sẽ quay lại!!!! (Ps: gặp được ông chủ siêu nhiệt tình sẽ có điều bất ngờ❤️❤️❤️)', '20 tháng 12, 2020', CURRENT_TIMESTAMP);

