    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/18/12/5e/20190409-092837-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mai Dang', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/ee/eb/36/caption.jpg?w=100&h=-1&s=1', 5, 'Cà phê Lápamant trong thị trấn. Đây là một trong những loại cà phê tốt nhất trong thị trấn theo ý kiến của tôi. Trang trí đơn giản nhưng đẹp với cà phê - liên quan - định hướng. Đồ uống rất đa dạng với nhiều loại cà phê & đồ uống khác, họ thậm chí còn có cà phê decaf cho những người không thể tiêu thụ cafein :)
Nơi cà phê fav của tôi để đi khi đến thăm Pleiku', '6 tháng 10, 2019', CURRENT_TIMESTAMP);
