    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lê Toan', NULL, 5, 'Quán đẹp ở Gia Lai. Tôi được con gái mừng nghỉ lễ mời mẹ và gia đình đi cà phê. Quán đẹp, sang trọng, phù hợp với người lớn tuổi gặp mặt hay tán gẫu. Tôi thích nơi đây', '11 tháng 1, 2019', CURRENT_TIMESTAMP);

