    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Quỳnh Hội', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 3, 'Quán ăn ngon của pleiku. Đây là 1 trong những quán ăn ngon của pleiku -quán có sức chứa khá lớn có nhiều khu nhà riêng tư .món ăn phong phú,anh chị chủ quán là người có tâm trong lỉnh vực ẩm thực', '16 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khanh H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/cb/96/79/khanh-h.jpg?w=100&h=-1&s=1', 4, 'Thức ăn ngon, quán đẹp. Đây là một địa điểm có thể dẫn gia đình, bạn bè, thực khách đến thưởng thức mỗi dịp cuối tuần tại Pleiku.
Quán đẹp, rộng rãi thoáng mát, nhiều cây xanh. Tọa lạc tại Lê Qúy Đôn, Pleiku, Gia Lai.
Quán có ưu thế về các món Tây Nguyên, gà nướng cơm lam, heo sọc dưa, cá sông Sesan.
Mức giá không phải bình dân, nhưng cũng hợp lý, không đắt lắm.
Tôi hài lòng !', '9 tháng 3, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thuý Loan N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0e/2b/24/fc/thuy-loan-n.jpg?w=100&h=-1&s=1', 4, 'Quán ngon. Là một trong những quán có thiết kế nhà hàng sân vườn. Đồ ăn ngon và phục vụ nhanh chóng! Thích món gà bó xôi. Có sẳn đàn guitar nếu khách yêu cầu!', '21 tháng 7, 2017', CURRENT_TIMESTAMP);

