    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/92/96/ff/kap-bistro.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/96/a5/b3/kap-bistro.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/92/93/d6/m-y-cua-toi-r-t-thich.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/92/96/58/kap-bistro.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Abc H', NULL, 1, 'Trải nghiệm của mình và nhóm bạn ở quán KAP Bistro. Mình rất thất vọng về buổi trải nghiệm hôm nay ở quán. Tuy là trang trí noel rất đẹp, có một số món như: pizza, trà sữa,… khá ngon nhưng thái độ phục vụ của các bạn nhân viên rất tệ. Mình có đặt bàn trước và đã gọi 2 món pizza, nhưng khi tới thì quán thì bọn mình phải chờ 15-20 phút thì mới có một cái pizza. Đến 15-20p sau, mình chờ lâu quá nên đã hỏi quán về chiếc pizza thứ 2, quán chỉ nói một câu: “Em giao lộn bàn rồi ạ” mà không có một lời xin lỗi. Mình có gọi thêm 1 số món nữa, trong đó có cả món salad cá hồi, mình đã dặn là “Đừng bỏ rau cải mầm nhé” vì bọn mình không ăn đc do nó có vị khá hăn và cay. Mà tới khi đem ra vẫn có rau cải mầm???! Ủa là sao vậy tr? Làm cho mọi người rất khó ăn, thậm chí mình còn ko ăn đc dù chỉ một nửa. Nói chung là quán có thái độ phục vụ hời hợt và rất tệ, bạn nào có ý định ghé quán thì nên cân nhắc trc nhé!!!!!!!!!!', '17 tháng 11, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyen H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/59/default-avatar-2020-49.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn. Đồ ăn khá ngon nhân viên nhiệt tình phong cách châu âu nhìn sang trọng rất đáng để ghé thăm có bia cafe', '23 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lê Y', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/59/default-avatar-2020-49.jpg?w=100&h=-1&s=1', 5, 'Tuyệt vời. Quán có không gian thoải mái mát mẻ. Đồ ăn khá ngon đặc biệt món Âu và món Thái. Nhân viên nhiệt tình', '23 tháng 3, 2023', CURRENT_TIMESTAMP);

