    VALUES (gen_random_uuid(), v_place_id, 'Tue Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ba/5e/d9/caption.jpg?w=100&h=-1&s=1', 5, 'Tuyệt vời khi Việt Nam sở hữu một bảo tàng tư nhân như thế này. Tôi luôn muốn trở lại nơi này và tự hào khi người Việt Nam làm được công trình như này. Rất thần tượng chủ tịch Nguyên Vũ của Trung Nguyên.', '30 tháng 7, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Đặng Ngọc Phương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2d/f0/8f/72/odyssey37730622238.jpg?w=100&h=-1&s=1', 5, 'Bảo tàng được thiết kế với cảm hứng từ nhà dài Tây Nguyên, thể hiện nét đặc trưng của văn hóa bản địa nhưng vẫn mang vẻ hiện đại, tối giản. Các tòa nhà được liên kết như một tổ hợp không gian mở, với mái vòm cao và ánh sáng tự nhiên, tạo nên sự gần gũi nhưng đầy tính nghệ thuật. Lối kiến trúc này không chỉ làm nổi bật giá trị truyền thống mà còn tạo nên một không gian mang tính quốc tế', '25 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Fearless13724423322', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Mang máy ảnh và một mẫu đẹp, 3 chai nước ! vậy là ổn. Nếu có thể nên mang thêm đồ ăn cho mèo ở khu zen ! rất cảm ơn.', '10 tháng 4, 2023', CURRENT_TIMESTAMP);

