    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'NguyenVanSon', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/ae/40/5c/caption.jpg?w=100&h=-1&s=1', 5, 'Khu sinh thái Ko Tam là một điểm ấn tượng không thể bỏ sót khi du khác đã đến Buôn Mê Thuột.Khu vực trung tâm của khu khoảng chừng 17 ha. Ngoài ra khu sinh thái còn liên kết mở rộng với đồng bào dân tộc buôn xã EaTu với diện tích vô cùng lớn khoảng 200 ha.Khu du lịch sinh thái KoTam mang đến vẻ đẹp đậm chất núi rừng Tây Nguyên, với hệ sinh thái đa dạng kết hợp nhiều khu nhân tạo nơi đây trở thành điểm đến thú vị của khách du lịch khi đặt chân đến mảnh đất Buôn Mê Thuột.', '21 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
