    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bun Trâm', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/22/8e/15/fb/bun-t.jpg?w=100&h=-1&s=1', 4, 'Một địa điểm du lịch khá hấp dẫn, không khí mát mẻ và trong lành. thưởng thức các món ăn đặc sản ngon, có khu vui chơi và hồ bơi cho trẻ nhỏ. Rất thích hợp để đi thư giãn cùng gia đình.', '18 tháng 3, 2022', CURRENT_TIMESTAMP);

