    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/df/e8/2f/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Dropbiz.vn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 4, 'Trải nghiệm văn hóa BMT. Giá nước ở đây cao, dạng như giá ở khu du lịch cao cấp, nhưng nguyên liệu pha nước thì rất ngon, cà phê máy có tỉ lệ Arabica cao, ca cao kem trứng uống cũng rất lạ miệng, có vị chua thanh nhẹ, đắng nhẹ của cacao, thơm ngon lạ miệng hơn nhiều so với đồ uống thông thường bên ngoài, có lẽ ở đây chuyên bán cacao, cacao cũng đã được lên men tự nhiên nên có vị chua nhẹ. Mình có thử tinh dầu, ở đây có 3 mùi, cà phê; cam,quế,hồi và sả chanh. Mình thấy mùi tinh dầu ở đây cũng khác so với chỗ khác, kể cả mùi sả chanh cũng khác, nói chung mùi nào cũng thơm, nhưng mình thích nhất mùi cam, quế, hồi nên mua 1 chai kỉ niệm, mùi nó làm mình nhớ tới resort An Lâm mà hồi xưa mình làm nhân viên ở đó (resort 5 sao nên cao cấp lắm 🤣).
Đồ ở đây giá chưa bao gồm VAT, nếu ăn uống thì còn tính thêm 5% phí dịch vụ nữa. Điểm trừ là mình sẽ không được báo trước về những khoản trả thêm này, lỡ mua xong  phát hiện không đủ tiền thì sao 😂.
Menu đẹp và nhiều món, hình ảnh hấp dẫn, sau 10h30 sẽ bắt đầu phục vụ đồ ăn, giá đồ ăn cao từ 65k đến vài trăm nghìn', '12 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
