    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Navigator67322400176', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/73/default-avatar-2020-13.jpg?w=100&h=-1&s=1', 5, 'Quán hang động độc lạ ở Buôn Ma Thuột. Quán phong cách độc lạ tại Buôn Ma Thuột, mình đi du lịch tiện ghé ngang nhưng thấy món khá là ngon. Mình đi 2 người bill hết tầm 600k, món ăn khá ngon. Không gian hẹn hò lãng mạn, chụp được nhiều hình đẹp. Sau có về BMT sẽ quay lại', '4 tháng 8, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
