    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Traveler38295491716', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, '1 địa điểm nên trãi nghiệm khi đến BMT. Đầu tiên là không gian quán rất lạ, rất Tây Nguyên. Menu thì đa dạng, mình rata thích món beefsteak sốt dâu tằm ở đây, lạ là ngon. Nv phục vụ nhiệt tình, nước uống trang trí đẹp mắt, mình sẽ quay lại', '22 tháng 7, 2023', CURRENT_TIMESTAMP);

