    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/5a/38/8f/20180317-213805-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lam D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng nổi tiếng với "C? M h? N". Ấn tượng đầu tiên của tôi khi tôi đến đó được nồng nhiệt chào đón. Tôi đến đây lúc 9 giờ 15 giờ tối và tôi là khách hàng cuối cùng trước khi họ đóng cửa nhưng họ rất hạnh phúc và phục vụ tôi một bữa ăn nóng và ngon. "C? M h? N" là thức ăn đặc biệt ở đây và bạn phải thử. Và với rượu vang địa phương đặc biệt của Yokdoni 17. 5% cho bữa ăn của bạn sẽ đầy đủ với thức ăn địa phương. Giá rượu hợp lý của Yokdoni là 110. 000 VND một chai và "C? M h? N" là khoảng 60. 000 đồng một bộ. Tôi nghĩ đây là một nhà hàng tốt ở Buôn Mê Thuột', '17 tháng 3, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'viannie2014', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'ăn lần nhớ hoài. trong một chuyến lên Buôn Ma Thuột du lịch với gia đình, trong đầu mình đặt rất nhiều dấu chấm hỏi rằng mình sẽ ăn gi, ở có đặc sản gì...cũng được các vị quân sư đi trước truyền tai lại các địa điểm ăn uống ngon tại Đak lak, y như những gì được truyền tai, Các món ăn ở Đak lak chủ yếu là đặc sản của các vùng miền, rất đa dạng, trong lúc dắt gia đình lên Siêu thị Coopmark buôn ma thuột mình rất ấn tượng với nhà hàng Cơm Hến Quyên Quyên đối diện siêu thị . nên dẫn cả nhà vô ăn thử. không ai nghĩ đến đak lak mà lại được thưởng thúc các món ăn rất HUẾ, món nào cũng tuyệt cú mèo. nhân viên thì thân thiện, được biết chủ nhà hàng này là người gốc Huế nên các món ăn ở đây ngon cũng ko có gì là lạ nữa. ngoài ra còn có các món hải sản cũng chẳng biết chê vào đâu. Đặc biệt ở đây còn có loại rượu Vang nghe nói là làm từ trái Nhàu ,hình như tên là Yokdoni, được biết do chính Nhà sản xuất thì phải. uống 1 lần mà giờ lúc nào mình cũng mua trữ sẵn o nhà .
nói chung nhà hàng này món nào cũng ngon cả Like ......lần sau chắc chắn sẽ quay lai. Bạn nào có dịp lên đak lak ko tin thì cứ ghé qua ăn thử nhé, đảm bảo ko hối hận đâu', '16 tháng 6, 2014', CURRENT_TIMESTAMP);

