    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/18/51/c8/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Peter G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2e/70/89/avatar010.jpg?w=100&h=-1&s=1', 4, 'Sau khi đọc một đánh giá trước đó, mức độ mong đợi của tôi khá thấp so với chỗ ở. Phòng và phòng tắm sạch sẽ không tì vết - - không, nhưng chắc chắn là chấp nhận được. Mặc dù tôi không thấy muỗi trong phòng thích hợp được cung cấp lưới. Mặc dù không mạnh mẽ như một số điều hòa đã làm việc và quạt hoạt động khá tốt. Thức ăn ở nhà hàng rất tươm tất. Chỉ dành một đêm và một buổi sáng tuyệt vời của sinh học trong công viên.', '18 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'datdoclub', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Rừng còn nhiều thảm thực vật đa dạng, giữa tiết trời tháng 2 này cũng khá dễ chịu, 20km cũng ko là vấn đề gì hết... Nhóm Đất Đỏ Club của mình cũng khá quen với những chương trình như thế này rồi... thật thú vị', '27 tháng 2, 2018', CURRENT_TIMESTAMP);

