    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/7b/53/e2/linh-a.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Eddie Tran', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/e9/f5/20/caption.jpg?w=100&h=-1&s=1', 5, 'Chuyến đi ý nghĩa, nhân văn và thân thiện với môi trường.Ngoài ra chủ cũng rất tốt đối đãi với khách như người nhà.Rất phù hợp cho gia đình nhỏ trải nghiệm nơi đây.Gđ check in 9/6 - out 12/06.Sẽ ghé lại nếu có cơ hội.Điểm trừ: nhiều côn trùng và muỗi, tuy nhiên gia đình có thể trang bị các loại xịt muỗi.Sẽ rất phù hợp nếu như gđ thích ngắm và trải nghiệm môi trường thiên nhiên và xinh đẹp này.', '11 tháng 6, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'lingmy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/7b/53/e2/linh-a.jpg?w=100&h=-1&s=1', 5, 'Đến giờ Tà Đùng vẫn cho mình nhiều ấn tượng đẹp và Freedom Green Village cũng vậy. Cám ơn A Hùng, C Thương, A Thành đã mang đến Tà Đùng một nơi dừng chân bình yên hiếm nơi đâu có được và giúp mình cũng như rất nhiều đoàn khách khác hiểu hơn về cuộc sống nông nghiệp bền vững.Mình và các bạn tuy chỉ ở 1 đêm do Làng đã kín lịch đặt phòng, chúng mình vẫn nhận được những trải nghiệm khó quên, dạo chơi trong Làng, tắm lá thảo mộc, ăn cơm cùng các bạn TNV, và gặp gỡ nhiều gia đình thú vị từ Bắc vào Nam,...', '29 tháng 1, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thuong T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Ngoài việc được biết đến cảnh đẹp thơ mộng, Tôi thấy khá thích thú về khu vườn thuận tự nhiên này. Tuy không có 1 nề nếp nào nhưng tất cả các loại rau đã nương tựa vào nhau phát triển 1 cách tự nhiên nhất. Tư duy này rất tốt đáng để phát huy và duy trì. Ngoài việc tham quan nghĩ dưỡng còn được tận hưởng rau củ quả được trồng thuận tự nhiên không hóa chất thì quá tuyệt vời. Chúc cho khu vườn ngày ngày luôn tươi tốt và đẹp hơn.', '15 tháng 5, 2019', CURRENT_TIMESTAMP);

