    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Yen Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/4a/default-avatar-2020-42.jpg?w=100&h=-1&s=1', 5, 'Với một khoản phí vào cửa tối thiểu, du khách có thể khám phá những cánh đồng rộng lớn và đậm chất điện ảnh, lối đi bộ và những con dốc thoai thoải của những ngọn đồi thông tuyệt vời của Đà Lạt. Bạn cũng có thể tham gia vào các hoạt động giải trí dân tộc thông qua các màn hình tương tác tại triển lãm dân tộc thiểu số bản địa bên trong làng.', '3 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Linh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/9a/25/7f/caption.jpg?w=100&h=-1&s=1', 5, 'Khoảng cách từ thành phố Đà Lạt đến Village khá xa, vòng vèo qua những rừng thông nhưng thay vào đó, hiện trước mắt chúng tôi là 1 ngôi làng rộng lớn, sừng sững trước mặt. Khung cảnh thật hùng vĩ, cứ như Đà Lạt thu nhỏ vậy, vườn hoa cẩm tú cầu bao la, bát ngát. Những cây cầu làm bằng tre cũng rất chắc chắn,kiểu dán thật bắt mắt người nhìn. Tóm lại chỉ trong 1 ngôi làng mà chứa đựng tất cả mọi thứ: vườn hoa cẩm tú cầu, những cây cầu, những ngôi nhà dân tộc - cồng chiêng, các phong tục tập quán vùng miền, có khu vui chơi, quán coffee, nhà hàng, .... nhiều quá k kể hết qua những dòng văn được 🥰🥰.  Thật sự ở đây mọi thứ rất tuyệt, tôi sẽ giới thiệu cho người thân về nơi đây🌸🌸👆👆.', '16 tháng 6, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Táo Lê', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/5d/default-avatar-2020-32.jpg?w=100&h=-1&s=1', 4, 'Cảnh đẹp. Nhưng đi dưới vực nên hơi nóng, bên cạnh đó xế chiều hay bị mưa, đi bộ thì mệt thôi rồi khuyến cáo nên mua áo mưa trước khi bước chân xuống nơi đây', '10 tháng 5, 2019', CURRENT_TIMESTAMP);

