    VALUES (gen_random_uuid(), v_place_id, 'Jess P', NULL, 4, 'Một chút tuyệt vời tìm thấy chỉ 10 phút đi bộ từ Air BnB của chúng tôi ở Okubo. Lối vào phòng tập thể dục thông thường chỉ 400 yên cộng với bạn phải thuê giày thể thao với giá 200 yên khác (trừ khi bạn mang trong nhà - chỉ có giày sạch). Mua vé cho mỗi người sử dụng máy bán hàng tự động tại khu vực tiếp tân - hãy hỏi nhân viên để được giúp đỡ nếu bạn có thể đọc tiếng Nhật - và đăng nhập tại quầy lễ tân.Phòng tập thể dục không lớn lắm và hơi cũ, nhưng hoàn hảo về chức năng và có các thiết bị cơ bản để tập luyện vững chắc. Thêm vào đó, nó không mở cửa đến 9 giờ sáng, điều này khá muộn đối với tôi. Nhưng với giá cả và sự dễ dàng tiếp cận với đội ngũ nhân viên thân thiện, nó chắc chắn đáng giá nếu bạn đang tìm kiếm một phòng tập thể dục!', '2 tháng 6, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'SimonSays', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/f1/a8/fc/avatar.jpg?w=100&h=-1&s=1', 4, 'Giá rẻ, vui vẻ và có mọi thứ bạn cần.', '29 tháng 4, 2019', CURRENT_TIMESTAMP);

