    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Relax18291244443', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 5, 'Bãi biển đẹp nhất trên đảo Nó thực sự là đẹp chất lượng của nước, bãi biển là rộng và có các dịch vụ khác nhau cung cấp cho bạn đồ uống và bữa ăn từ chringuitos và các nhà hàng gần đó, có palapas công cộng và bạn cũng có thể thuê nhà vệ sinh và ô, nó thực sự là tốt nhất', '27 tháng 9, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Edward', NULL, 5, 'Cát mềm đến chân, nước lặng và ấm, hoàng hôn thật tuyệt vời; trên tất cả các kinh nghiệm là áp đảo.', '24 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jody-Lynn', NULL, 4, 'Con gái tôi và tôi đã rất vui mừng khi có cơ hội đến thăm một trong những bãi biển đẹp nhất thế giới! ! Buổi sáng chúng tôi đến Eagle Beach mát mẻ, mưa và gió. Đó là một bãi biển đẹp và chúng tôi đã tận dụng tối đa.', '23 tháng 3, 2020', CURRENT_TIMESTAMP);

