    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thanh Mỹ', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/48/default-avatar-2020-15.jpg?w=100&h=-1&s=1', 4, 'Gigamall rộng rãi, nhiều cửa hàng và khu ăn uống để lựa chọn. Không gian sạch sẽ, phù hợp đi chơi cuối tuần cùng gia đình hoặc bạn bè.', '27 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
