    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nhiênvjp', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/c7/c8/f5/caption.jpg?w=100&h=-1&s=1', 5, 'Trung tâm to rộng nhiều tiện ích cho bạn lựa chọn từ ăn uống vui chơi giải tríCuối tuần mình có ghé đi ăn và xem phim chung chỗ tiện ghê.Đều rất đông nên các bạn sắp xếpTrong có nhiều chỗ khu vui chơi trẻ em chụp hìnhCuối tuần nếu đii hẹn hò hay đi với gia đình cũng ok hết', '25 tháng 8, 2025', CURRENT_TIMESTAMP);

