    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/15/da/ec/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KING M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 5, 'bữa ăn, nhà tắm và dịch vụ khách hàng tuyệt vời. họ cung cấp cho bạn áo choàng kiểu yukata để mặc trong cơ sở khi bạn ở khu vực thư giãn.', '24 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tavi', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 1, 'Nhân viên rất phân biệt chủng tộc và thô lỗ, đặc biệt là những người bên trong phòng thay đồ.Họ đang săn lùng những gaijins đeo khăn che hình xăm hoặc đeo bất kỳ miếng dán nào để che vết thương, v.v. Ngay cả khi bạn không có hình xăm rõ ràng, họ sẽ đuổi người nước ngoài nếu bạn che giấu hình xăm. Sau khi nhìn thấy bạn, họ nói chuyện với bạn một cách cực kỳ thô lỗ và họ muốn xé miếng dán của bạn ra chỉ để xác nhận xem đó là hình xăm hay vết thương. Không thể tin được!', '23 tháng 8, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Oztravels7', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/0b/c0/cf/oztravels7.jpg?w=100&h=-1&s=1', 5, 'Thật là một suối nước nóng tuyệt vời! Tôi đã dành khoảng 3 giờ thư giãn ở đây! Có một chút vấn đề với tiếng Anh nhưng mọi người (nhân viên và khách hàng) đều rất thân thiện và hữu ích! Có rất nhiều phòng tắm bên trong và bên ngoài. Tôi đã sử dụng bồn tắm điện và OMG nó đã giảm đau lưng rất nhiều. Xe đưa đón miễn phí đến và đi từ nhà ga là một phần thưởng! Lời cảnh báo! Như truyền thống ở Nhật Bản, sử dụng onsen là trần trụi và vui lòng tuân thủ các yêu cầu vệ sinh!', '17 tháng 2, 2020', CURRENT_TIMESTAMP);

