    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/23/c1/93/yoshinoya-kurume-kamitsu.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Joan O', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 5, 'Ngôi đền này là một trong những thú vị nhất mà tôi đã thấy ở Nhật Bản. 203 ft. Bức tượng cao là ấn tượng và có thể nhìn thấy hàng dặm. Bạn có thể leo lên bức tượng nếu bạn muốn. Ngoài ra còn có một bảo tàng dưới ngôi đền rất thú vị. Có một khoản phí nhỏ để vào khu vực đền thờ (500 yên).', '5 tháng 4, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GregS_Sydney', NULL, 5, 'Chúng tôi bắt chuyến tàu đến ga Minami - Kurume và đi bộ khoảng 35 phút đến ngôi đền đáng yêu này. Đến qua rất nhiều người dân địa phương tuyệt vời và một số siêu thị địa phương ẩn đi. Đứng đầu bởi món súp đậu đỏ và mochi tuyệt đẹp tại quán cà phê chỉ 250 yên.', '20 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Higuma 2017', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/5a/df/30/higuma2017.jpg?w=100&h=-1&s=1', 4, 'Rất khó để đi từ Ga Kurume đến Naritasan và ngược lại. Vì vậy, tôi khuyên bạn nên nói chuyện với một tài xế taxi để đưa bạn và chờ đợi cho bạn ở đó. Một chuyến thăm đầy đủ không nên mất hơn 45 phút. Đó là một ngôi đền đáng yêu với một bức tượng Guanyn xinh đẹp. Các tài xế thường vui mừng chờ đợi và giảm giá cho bạn một cách tổng thể, vì sẽ không có khách hàng nào khác lái xe trở lại nhà ga.', '26 tháng 11, 2017', CURRENT_TIMESTAMP);

