    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/2c/94/55/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/d9/35/d6/ziubbq-k-bbq-since-2002.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Yi Qin', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/25/21/88/avatar.jpg?w=100&h=-1&s=1', 4, 'Cửa hàng bán tất cả các loại hàng hóa nhân vật Line đáng yêu, tốt để mua làm quà lưu niệm cho bạn bè. Tuy nhiên, các sản phẩm được bán tại cửa hàng có thể khá đắt tiền. Luôn có một hàng đợi để chụp ảnh với màu nâu lớn ở lối vào nhưng hàng đợi di chuyển khá nhanh.', '14 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Christoph L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/1d/28/ba/christoph-l.jpg?w=100&h=-1&s=1', 4, 'Là người dùng Line App, việc truy cập nhanh vào cửa hàng này là phải đi. Tôi đã từng gửi nhãn dán Brown và Cony hàng ngày, vì vậy tôi nghĩ sẽ rất tuyệt khi đến cửa hàng (thực ra đó là một trong số nhiều người ở Seoul nhưng dường như là lớn nhất). Và khi tôi hơn 50 tuổi, vợ tôi và tôi dường như là những người lớn tuổi nhất trong cửa hàng :), tôi thậm chí còn mua cho tôi một món đồ chơi âu yếm Brown.Nói tóm lại, nếu bạn biết các ký tự Line và thích chúng, vui lòng đi, nếu bạn thậm chí không biết Line là gì hoặc bạn không sử dụng nó, thì rõ ràng đó là Không dành cho bạn.', '14 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Serena', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/79/default-avatar-2020-21.jpg?w=100&h=-1&s=1', 5, 'Gần đây tôi đã đến Hàn Quốc vào tháng 6 này vì tôi đã nói rằng bạn sẽ hối hận nếu tôi chưa bao giờ đến đó một lần trong đời. Trước chuyến đi, tôi đã phục vụ internet để tìm kiếm một số địa điểm phải đến trong chuyến đi của mình. Khi tôi đang cuộn, tôi tìm thấy cửa hàng này và tôi quyết định đến đó.Tôi đến và mua nhiều sản phẩm bt 21 và chúng rất dễ thương! Tôi rất yêu nó!', '8 tháng 8, 2019', CURRENT_TIMESTAMP);

