    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/10/18/b2/de/in-the-morning.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/55/59/01/caption.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/58/78/8e/exercise-to-the-pagoda.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tue Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ba/5e/d9/caption.jpg?w=100&h=-1&s=1', 5, 'Chuyến đi tuyệt vời để ngắm núi nam bộ. Trên đỉnh núi có thể ngắm được thành phố Tây ninh. Đây có thể là địa điểm du lịch tâm linh lớn nhất miền Nam.Cáp treo giá cả hợp lý. Lên đỉnh núi có rất nhiều góc tuyệt vời để chụp hình. Không khí trong lành rất dễ chịu', '14 tháng 8, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Dream22049865304', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Thật thú vị vì từ trên cao nhìn xuống phía dưới là đồng bằng xa xa, nhìn về hướng đông lại thấy Hồ Dầu Tiếng. Cảm giác rất khó tả, linh thiêng và đầy ma mị với Tôi, chắc chán tôi sẽ quay trở lại Bà Đen một lần gần nhứt.', '21 tháng 12, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DianneJM', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'Kể từ chuyến thăm của tôi vào tháng 12, cáp treo hiện đang mở. Một vé người lớn trở về là 200, 000.Tôi cũng đã đi tàu lượn Alps đã bị đóng cửa để bảo trì chuyến thăm cuối cùng.Thật không may người bán vé không có tiếng Anh. Xin lưu ý rằng tốt nhất là đi bộ hoặc đi cáp treo nhỏ hơn đến đền thờ và chỉ sử dụng tàu lượn siêu tốc Alphine cho chuyến đi xuống. Một cách là 95, 000 và lãng phí tiền để bắt nó lên đồi. Tàu lượn siêu tốc duy nhất tôi biết ở Việt Nam không phải là một chuyến đi khứ hồi.Bỏ qua chuyện đó, Black Virgin Mountain một ngày tuyệt vời. Ngày càng nhiều để làm với mỗi chuyến thăm.', '9 tháng 3, 2020', CURRENT_TIMESTAMP);

