    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Julien LD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/2e/45/42/julien-d.jpg?w=100&h=-1&s=1', 5, 'Địa điểm đẹp, thức ăn ngon, đầu bếp đẹp. đã ở La Dem Bistro 2 lần, luôn là khoảnh khắc tuyệt vời với đầu bếp Laurent, món burger ngon nhất trong thị trấn và là một trong những món burger đẹp và ngon nhất so với Hồ Chí Minh.
Cảm ơn bạn đã dành thời gian và đề nghị của bạn,
Nếu bạn cần một món ăn tuyệt vời hãy đến La Dem Bistro ở Tây Ninh,', '19 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anothony Scott', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/19/98/d1/bd/picayunemicroblading.jpg?w=100&h=-1&s=1', 5, 'Kinh ngạc. Chủ sở hữu dịch vụ tuyệt vời và thức ăn ngon. Tôi chắc chắn sẽ đến đây một lần nữa. Nếu bạn chưa bao giờ thử? hay bánh mì kẹp thịt? trước đây là vị trí!', '7 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roy Hobson', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Thực phẩm và không khí tuyệt vời. Thức ăn tuyệt vời và không khí Nhân viên và đầu bếp cực kỳ thân thiện và hữu ích. Pizza là tuyệt vời, nó chỉ là tốt nếu không tốt hơn bất kỳ bánh pizza phương Tây. Tôi rất muốn giới thiệu nếu bạn đang ở Tây Ninh!', '13 tháng 10, 2019', CURRENT_TIMESTAMP);

