    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Andrewpdc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'Giá cả hợp lý, bánh ngon,giao hàng nhanh. Pizza rất xuất sắc nhé mọi người. Hương vị rất hợp khẩu vị với người dân địa phương. Shipper thì rất là nhanh , chủ tư vấn nhiệt tình nhanh nhẹn , buôn bán gọn lẹ, shop online nhưng không ất ơ như bọn mua đi bán lại. Chuyên nghiệp,nghe đâu anh chủ là dân bếp chuyên nghiệp nên khá kỹ tính trong chất lượng cũng như chịu lắng nghe nhu cầu khách. Rất đáng để thử nếu như bạn là fan của fusion food. Muốn authentic thì nên đặt trước', '26 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
