    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'My N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/66/default-avatar-2020-53.jpg?w=100&h=-1&s=1', 1, 'Nhân viên ở đây rất thô lô, chửi khách bức hiếp khách hàng đến khu du lịch.Order gần 1 triệu đồng thức ăn mà hỏi mấy đôi đũa mà tụi nó bảo đũa ở đây cho miễn phí,Mà mình chỉ nói mua không đưa đũa vậy ăn bằng gì? nó là bảo là nếu cần thì 2000đ 1 đôi mình bảo mua bán kiểu vậy ai giám ăn lần nữa.Nó bảo là tui bị điên à? Thế mày không ăn sao mày mua? Vì lúc đó mình thanh toán tiền rồi chứ không thì không muốn làm cho chúng nó giàu với Thái đô lỗ hung hăn bức hiếp như vây.Thôi từ đây tẩy chay Khu Du Lịch này .', '26 tháng 8, 2023', CURRENT_TIMESTAMP);
