    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Fearless42734683661', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 1, 'Mình đi làm và ghé mua một ít mỹ phẩm. Lúc về thì mình có lỡ de xe trúng 1 chiếc xe gắn máy và không may là chiếc xe đó bị ngã. Mình cũng đã xuống xe và chuẩn bị dựng xe lên cho chủ. Sau đó thì 4-5 anh bảo vệ cao to chặn lại lập biên bản, chụp hình, quay video lại làm bằng chứng, yêu cầu đưa CCCD và thông tin cá nhân. Mình không rồ ga bỏ chạy, vẫn đứng đợi để gặp chủ xe sau khi bảo vệ siêu thị phát loa để tìm chủ nhân và sẵn sàng bồi thường vết trầy trên xe. Dù gì cũng là lỗi của mình đã không cẩn thận nhưng dịch vụ của bảo vệ khiến mình rất hoảng sợ.', '13 tháng 1, 2025', CURRENT_TIMESTAMP);

