    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Henrychef', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1d/9c/c1/37/henry-l.jpg?w=100&h=-1&s=1', 5, 'Hotel đẹp tiện ích cho công việc, hồ bơi đẹp, đồ ăn ngon, cocktail hơi bị pheeeeeeee.!. Trải nghiệm tuyệt vời từ khách sạn cho tới nhân viên, tác phong chuyên nghiệp từ bộ phận FO, F&B, HK rất nhiệt tình hỗ trợ các thông tin hữu ích, đồ ăn cực ngon, hồ bơi đẹp, phòng tập gym hiện đại 😍🥰😗', '26 tháng 6, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
