    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trương Thi Vân', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Không có gì để chê. Nhà hàng cũng cấp các món ăn Nhật bản, rất ngon. Nhân viên thì siêu kute, rất vui vẻ và phục vụ khách rất nhanh. Quán decor quá đẹp, đúng phong cách Nhật.
Hy vọng quán thì thoảng có sale để mình còn qua ăn !!!', '20 tháng 6, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Diệu Hà', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/b1/80/e6/akataiyo.jpg?w=200&h=200&s=1', 5, 'Tưởng không ngon mà ngon không tưởng. Bạn mua về cho ăn, lúc đầu thấy đồ sống còn chê, sau ăn nhiều hơn cả bạn. Đã thế thèm quá, mấy ngày sau lại rủ bạn qua ăn ở quán luôn.
Mê đồ ăn, mê luôn cả không gian quán. Thiết kế đúng kiểu nhật bản. Lại vô cùng sạch sẽ.
Sẽ ủng hộ quán dài dài', '1 tháng 3, 2021', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bich Loan Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn ngon. Phục vụ rất thân thiện và ra món rất nhanh. Đồ ăn siêu ngon làm mình tốn kha khá. Lần tới nhất định sẽ thử các món khác của nhà hàng. Mong nhà hàng thường xuyên khuyễn mãi', '11 tháng 11, 2020', CURRENT_TIMESTAMP);

