    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Traveler55155162356', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/68/default-avatar-2020-9.jpg?w=100&h=-1&s=1', 5, 'Ai yếu tim thì có dòng sông lười nằm phè chill chill. Mẹo hay: nên chơi King Cobra buổi sáng trước 11h hoặc sau 3h chiều để tránh xếp hàng lâu. Nằm ngửa, tay khép sát người sẽ trượt nhanh hơn. Dòng sông lười đông nhất 2h-4h chiều, muốn thoải mái thì đi sớm. Nhớ tránh ăn no trước khi chơi trò mạnh kẻo mệt. Có thể thuê áo phao nếu lo lắng', '14 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Excursion49169638292', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/24/default-avatar-2020-60.jpg?w=100&h=-1&s=1', 5, 'Amazing World với zipline và leo núi trong nhà siêu phê. Trải nghiệm VR cũng rất đáng tiền. Hai nhà hàng Phúc Lâm Môn đồ ăn ngon, nhất là hải sản tươi sống ở Phúc Lâm Môn 2. Resort nghỉ dưỡng được vui chơi không giới hạn là điểm cộng lớn. Còn chờ gì nữa mà không đi', '14 tháng 6, 2025', CURRENT_TIMESTAMP);

