    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'HuynhThucHieu', NULL, 4, 'Bạn có thể chuận bị mốt số đồ ăn, thức uống (Lưu ý tính tiện dụng). Sau đó kết hợp vừa tham quan, vừa tổ chức ăn trưa tại các thảm cỏ mát./', '10 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TravelTravelTravel', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/7b/default-avatar-2020-56.jpg?w=100&h=-1&s=1', 4, 'Tôi đã thích nó. Mất 6 tiếng để đến Biên Hòa. Sau đó là khoảng 15 phút từ trung tâm của thị trấn. Nó không phải là một trang web hàng đầu cho khách du lịch đi qua, nhưng nó phù hợp cho những người dành một tháng trở lên ở HCM và muốn hòa mình vào thiên nhiên. Có quá nhiều nhựa ở đó nhưng không khó để thoát khỏi nó và có được cảm giác bạn chỉ có thể lấy từ nước, không khí trong lành và đi bộ tốt. Tôi mất ba giờ để đi bộ quanh hồ, dừng lại để uống nước và rất nhiều hình ảnh. Chi phí 100, 000 để đi vào.Đối với những người có gia đình, nó có rất nhiều việc phải làm cho trẻ nhỏ.Đối với tôi thật là sảng khoái khi tránh xa những chiếc xe đạp và xi măng ở HCM. Đó là lát cắt gần nhất của thiên nhiên mà tôi đã tìm thấy cho đến nay.', '19 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ban1245', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 5, 'Đến Bửu Long chơi thật đẹp. Cảnh giống như Hạ Long thu nhỏ. Có nhiều khu vui chơi cả cho người lớn và em bé. Đặc biệt thích đạp thiên nga giữa hồ rất mát.', '26 tháng 12, 2018', CURRENT_TIMESTAMP);

