    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/1e/5f/0b/valet.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/1e/5f/46/porte-cochere.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/6c/e3/92/photo4jpg.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/ea/99/da/hoa-vien-tiec-cuoi-79.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'LeeinDubai', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/f6/bd/fb/leeindubai.jpg?w=100&h=-1&s=1', 4, 'Một trong những sân golf tốt nhất tại TP HCM (nếu không phải là tốt nhất). Bố trí tuyệt vời với nhiều biến thể và thách thức. Hãy chắc chắn yêu cầu các caddies nói tiếng Anh Tôi đã đưa bạn đến khóa học nếu không sự hiểu biết về khóa học của bạn sẽ gặp nhiều thách thức.Nhà hàng là một sự thất vọng lớn với chất lượng thực phẩm mờ nhạt không có bất kỳ ý nghĩa của dịch vụ. Xem xét làm thế nào các khóa học khác ở TP HCM xuất sắc trong F & được cung cấp, Long Thành có một chặng đường dài để đi. Điều đáng tiếc.', '16 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Andy P', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/eb/default-avatar-2020-27.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đã có trận đấu đầu tiên tại Việt Nam tại câu lạc bộ này khi bắt đầu chuyến tham quan golf Việt Nam. Thực sự rất thích ngày. Có hai khóa học gọi là The Hills và The Lakes. Chúng tôi đã chơi Hills và nó thực sự tốt đẹp. Một số lỗ rất khó và một số dễ hơn nhưng một khóa học công bằng. Hai caddie của chúng tôi có chất lượng hàng đầu và tôi có thể đọc các tác phẩm như một chuyên gia. Muốn giới thiệu alll golf để chơi ở đây.', '21 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mark F', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/42/db/2b/mark-f.jpg?w=100&h=-1&s=1', 5, 'Chơi ở đây như là một phần của tour du lịch Việt Nam 7 khóa học của chúng tôi. Họ có 2 khóa học và tôi đã chơi 9 khóa sau trên Hills Course và sau đó là 9 khóa trước của Lakes Course. Tôi đã chơi như một người độc thân với vợ tôi trong khóa học với tôi. Mọi người rất hữu ích và caddy tôi có rất tuyệt. Tôi trình bày đẹp mắt khóa học và đó là một thách thức. Rất khuyến khích.', '24 tháng 8, 2019', CURRENT_TIMESTAMP);

