    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Voyager63671922911', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/68/default-avatar-2020-9.jpg?w=100&h=-1&s=1', 4, 'cửa hàng pizza. Got Pizza là một địa điểm lý tưởng cho những ai yêu thích pizza chuẩn vị Ý. Không gian quán ấm cúng, nhân viên phục vụ nhanh nhẹn và thân thiện. Menu đa dạng với nhiều loại pizza hấp dẫn. Đế bánh giòn rụm, nhân đầy đặn và phô mai béo ngậy. Đặc biệt, pizza hải sản ở đây rất tươi và đậm đà. Giá cả hợp lý so với chất lượng. Nếu bạn đang tìm một quán pizza ngon để tụ tập bạn bè hay hẹn hò, Pizza House chắc chắn là một lựa chọn đáng thử!', '24 tháng 3, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
