    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lily.Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Món mới lạ về Bò cần phải thử ngay. Ai thích ăn món BÒ nhúng giấm nổi tiếng; thì cần phải thử ngày những vị sốt lạ miệng của quán này nha!!! Nước sốt là thứ điểm đặc trưng nhất của quán: vị chanh dây, sốt tiêu đen là 2 sốt mình thích nhất. Thịt bò tươi và mềm; À ai thích ăn hương vị quê nhà thì ăn ngay Lẩu Cua Đồng nha. Nước uống như chà tranh Hoa Đậu Biếc lạ mà thanh mát cực', '28 tháng 5, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Luan', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Thích ăn bò thì nên thử Bò Nằm Nhúng. Thịt bò tươi ngon kèm với các loại sốt quen mà lạ, ăn vào ngon lắm! Mình thích nhất là món bò sốt tiêu xanh, món này có vị tiêu cay nồng, nước sốt béo béo, thịt bò mềm tươi,   ngon hết sẩy luôn. Không gian ấm cúng rất thích hợp với nhóm bạn, cặp đôi, gia đình. Nhân viên thì chu đáo, dễ thương lắm. Nói chung là vote 5 sao nha!', '26 tháng 5, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'K-be', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/03/75/ee/caption.jpg?w=100&h=-1&s=1', 5, 'Good Food and friendly. Món đặc sắc của quán là các món Nhúng với nước sốt tự nhiên và ăn ngay trên chảo nóng, 
Món mình thích là bò nhúng chanh dây và lẩu bò cay. Các món nước như trà chanh hoa đậu biếc và soda hoa đậu biếc rất lạ', '28 tháng 12, 2019', CURRENT_TIMESTAMP);

