    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/db/3a/2a/h-i-daikin-club-bien.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thuy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f6/0d/default-avatar-2020-34.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng. Nhà hàng có nhiều món. Mình hay tiếp khách ở đây. Mình ăn ở đây cũng nhiều lần. Có bưởi trắng miệng khá ngon.ở Biên Hòa thì ko có quá nhiều sự lựa chọn', '9 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Denis V', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 3, 'đáng để đi theo nhóm. Cao cả, rộng rãi, ồn ào, hành động chật cứng, với dịch vụ nhanh chóng - tất cả đều tốt ngay cả trước khi bạn đến chỗ ăn. Bãi đậu xe rất an toàn và một nơi dễ tìm. Nó có thể làm với một ''mọc lên'' hoặc thậm chí loại bỏ rác sẽ giúp ích nhưng đó là Việt Nam vì vậy thực phẩm đứng đầu tất cả các cân nhắc khác', '3 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'brendanstetson', NULL, 5, 'Nhà hàng hải sản Việt Nam rất ngon. Chắc chắn là nhà hàng tốt nhất trong thành phố, nhưng không mong đợi một bầu không khí sang trọng! ! Đó là một nhà hàng lớn, giống như một nhà máy, rất lớn, với những bàn rất lớn và các nhóm khách hàng Việt Nam đang kỷ niệm một cái gì đó to lớn. Ông có ao ở lối vào để chọn cá tươi của bạn. Chúng tôi ăn rất ngon (cá sống, tôm sống, cá mòi trong xà lách, ếch với nước sốt cà ri); Tất cả các loại nước sốt đều rất ngon. Nhân viên hiệu quả nhưng gặp khó khăn trong việc nói tiếng Anh. Ngoài ra, nó không phải là đắt tiền. Yêu thích !', '26 tháng 1, 2018', CURRENT_TIMESTAMP);

