    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0e/86/23/5d/photo4jpg.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/26/6c/0a/nha-vien-quan.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/26/6c/23/nha-vien-quan.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/bd/d0/5f/the-beautiful-scenery.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Minh Hậu N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/91/default-avatar-2020-62.jpg?w=100&h=-1&s=1', 1, 'Quán tệ, nhân viên xấc xược bất cần khách. Nghe bạn bè nói quán có khung cảnh đẹp, nên tụi mình mới đến. Ấn tượng ban đầu không mấy tốt đẹp từ anh bảo vệ giữ xe có thái độ không muốn khách đến. Vào tới trong lại gặp cảnh nhân viên bên trong khi biết mình đi 2 người lại không muốn tiếp (mặc dù còn trống 3-4 bàn) và có thái độ xua khách đi qua các khu khác của quán mà tìm chỗ ngồi. 
Với thái độ khinh thường khách đến như thế, tụi mình đi về thẳng và tự nhủ rằng có lẽ những người chủ của quán này chưa bao giờ họp nhắc nhở nhân viên về cách ứng xử mà chỉ đặt yêu cầu về doanh thu (bằng chứng là những cái bàn đó không hề có khách đặt trước và những nhân viên đó cũng từ chối tiếp 2 cặp đôi khác để nhận 1 cặp đôi khi nghe cặp này nói đi 8 người và họ đi trước - haha nhục mặt vì trọng doanh thu)', '12 tháng 2, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'BluePlanet76', NULL, 2, 'Trông rất tuyệt nhưng. Đã đến đó vào tối chủ nhật, chúng tôi là chiếc bàn duy nhất trong bữa ăn.
 1. bàn của chúng tôi đã không được làm sạch đúng cách, vẫn còn một số thức ăn thừa khi chúng tôi ngồi xuống và không có hành động làm sạch thêm từ nhân viên, đã đi trực tiếp để đặt hàng.
 2. một trong những món ăn được nướng tôm, đáng ngạc nhiên nó được phục vụ một cách nhanh chóng, chủ yếu là đẹp và ấm áp nhưng đầu của đầu và đuôi được mát mẻ. Có thể họ nấu trước khi nướng.
 3. thường đối với mỗi món ăn VN, sẽ có một loại nước chấm khác nhau để ngâm, chúng tôi chỉ được cung cấp 1 (muối tiêu) cho tất cả, trong khi đó, nhân viên chỉ nói chuyện và hát với nhau.
 4 . chúng tôi đã không đi với bất kỳ người dân địa phương VN lần này, nhân viên không thể giao tiếp bằng tiếng Anh hoặc tiếng Trung Quốc, vì vậy chúng tôi đã cố gắng hết sức để giao tiếp bằng tiếng Việt. nó phổ biến cho một người VN không cố gắng hơn để đoán / hiểu những gì một người nước ngoài với người nghèo nói tiếng Việt, một chút thất vọng.

bằng cách này, chế độ xem / thiết lập thật tuyệt vời', '28 tháng 9, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Minh H', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 3, 'Thực phẩm tốt. Tôi đã có ớt, ăn chay và ngon, và bánh mì tròn và pho mát kem thì là từ Common Roots là hoàn toàn tuyệt vời. Bãi đỗ xe khá hạn chế với khoảng năm điểm ở phía sau, nhưng nếu bạn đang di chuyển, bạn sẽ không cần phải ở lại lâu hơn một vài phút', '3 tháng 3, 2017', CURRENT_TIMESTAMP);

