    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khánh Tuyền M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 5, 'Ai mê súng và lịch sử phương Tây nên ghé nhé, nhân viên nhiệt tình, có phòng máy lạnh.Gia đình mình đến sớm hơn giờ check in khách sạn nên đã ghé bảo tàng tầm 12:30 trưa vào thứ 7. Lúc này bảo tàng không quá đông, tầm 10-15 khách khác cũng tham quan, nhưng do có nhiều toà nhà nên chia raChủ bảo tàng đã sưu tập rất nhiều vũ khí cổ và hiếm. Có album hình của chủ thời ông còn trong hải quân. Do chủ là tư nhân nên được chụp hình thoải mái, mỗi phòng/ tầng có nhân viên thuyết minh bằng tiếng ViệtVé chỉ 100k/ người nên mình thấy rất đáng với trải nghiệm. Gia đình mình nghe hết thuyết minh nên đã ở khu này tầm 2.5 tiếng, có quán nước giải khát với giá rất bình dânĐược mặc đồ lính hoặc công chúa, hoàng hậu để chụp hình nữa, quầy lưu niệm có giá khá ok, họ dùng lợi nhuận để làm từ thiện', '18 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
