    VALUES (gen_random_uuid(), v_place_id, 'HappinessPhule', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/6a/default-avatar-2020-47.jpg?w=100&h=-1&s=1', 5, 'vietnam có một công trình vĩ đại đẹp,leo ra cánh tay nhìn cả thành phố', '23 tháng 8, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'GoPlaces60093384583', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/79/default-avatar-2020-21.jpg?w=100&h=-1&s=1', 4, 'Mình đã có dịp tham quan Jesus Christ Statue trong chuyến đi Vũng Tàu gần đây và thật sự rất ấn tượng. Để lên tới tượng, mình phải leo hơn 800 bậc thang, khá mệt nhưng bù lại phong cảnh trên đường đi rất đẹp, có thể nhìn thấy biển và thành phố từ trên cao.Khi lên tới nơi, không gian rất yên tĩnh và mang cảm giác linh thiêng. Điểm đặc biệt là du khách có thể leo vào bên trong tượng để lên phần vai, từ đó ngắm toàn cảnh Vũng Tàu rất đẹp và thoáng đãng.Tuy nhiên, mình thấy có một số lưu ý như phải mặc trang phục kín đáo và cầu thang bên trong khá hẹp, nên hơi khó di chuyển nếu đông người.Nhìn chung, đây là một địa điểm rất đáng để tham quan khi đến Vũng Tàu, vừa có ý nghĩa tâm linh vừa có view đẹp để check-in.', '27 tháng 3, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'May Ly', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2e/ad/20/b1/caption.jpg?w=100&h=-1&s=1', 1, 'Chúng tôi vừa  đến cổng bị bảo vệ đuổi, dùng lời nói nặng. Khi vào đến  bên trong  cũng nói rất to tiếng,  vì trong  đoàn có 1 chị mặc quần ngắn. Bảo vệ (Béo)  ý thức kém, ko văn mình, đạo đức kém...', '12 tháng 5, 2024', CURRENT_TIMESTAMP);

