    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Alexandra-Marei... M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 4, 'Thực phẩm biển giá rẻ & Tivoli với Hội chợ vui nhộn và Vòng đu quay, Tháp nâng, Hình xăm henna, trái tim sét lớn cho ảnh tự sướng tình yêu.', '9 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Michael L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/02/ea/54/84/michael-l.jpg?w=100&h=-1&s=1', 4, 'Điều này chắc chắn là đáng xem, chỉ cần lưu ý, chúng tôi đã thay đổi thực đơn của chúng tôi thành một trong đó có giá cao hơn từ menu ban đầu của chúng tôi. Nó vẫn còn rẻ, nhưng nó đã làm phiền chúng tôi một chút. Dù sao cũng đáng xem, có một cái nhìn tốt xung quanh và nhận được một số giá trước khi cam kết.', '14 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Epic-Traveller', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/d2/63/22/caption.jpg?w=100&h=-1&s=1', 5, 'Nó không đặc biệt là một thị trường, mặc dù có một số bán tat và một số đánh bắt trên biển.Nó giống như một loạt các nhà hàng thức ăn đường phố lớn, nổi bật.Chỉ sau khách sạn Imperial và Imperial Plaza. Chúng tôi đã không dừng lại để kiếm thức ăn, nhưng mùi chắc chắn đã cám dỗ chúng tôi.', '19 tháng 6, 2019', CURRENT_TIMESTAMP);

