    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ali68Kent', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/23/default-avatar-2020-28.jpg?w=100&h=-1&s=1', 3, 'Có một giờ ở đây là quá đủThị trường châu Á bẩn thỉu bẩn thỉuMọi cách chúng tôi biến các quầy hàng đều giống nhauCó một số quầy hàng trang sức thú vị với giá cả hợp lý nếu đó là điều của bạn', '14 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Janet S', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 3, 'Điều đó thật thú vị - các nhà cung cấp đã không làm phiền chúng tôi, vì vậy về mặt đó thì tốt. Giá không rẻ hơn nhiều so với các cửa hàng trong thị trấn, và tôi nghĩ rằng Hà Nội có lẽ đắt hơn.', '2 tháng 5, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'kitesurfing les... v', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1c/96/d2/d3/kitesurfing-les-v.jpg?w=100&h=-1&s=1', 4, 'Chợ trung tâm Vũng Tàu là nơi tất cả người dân địa phương đi mua những thứ đa dạng nhất. Nó luôn luôn là một ý tưởng tốt khi bạn không có gì đặc biệt để làm để đi bộ xung quanh và xem những thứ họ có để bán. Trong ảnh của tôi, một bông hoa và một nhà cung cấp trái cây ở lối vào của thị trường', '23 tháng 8, 2018', CURRENT_TIMESTAMP);

