    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DLinh N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, 'Cuối tuần làm chuyến xuống vũng tàu, trốn cái nóng và bụi bẩn của sài gòn. May quá là lựa ngày đi không mưa gió, trời quang đãng, mát mẻ. Tắm bãi sau thì biển khá êm, không có sóng lớn', '10 tháng 12, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
