    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Explorer31425269752', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Nếu như bãi sau mang trong mình vẻ đẹp hiền hòa, đắm mình trong ánh nắng đặc trưng của miền khí hậu nhiệt đới thì bãi trước lại đẹp theo một cách khác sôi động hơn, mang đậm trong mình hơi thở của cuộc sống phồn hoa sung túc, là khu vực tập trung các tiện ích vui chơi giải trí... Biển đẹp, mát mẻ, nhiều đá hơn bãi sau khách tắm ở đây cũng đông hơn thích hợp để chụp ảnh và khi đến đây có thể ngắm trọn vẹn cảnh hoàng hôn trên biển, được thưởng thức nhiều món ăn ngon và nhiều dịch vụ tốt. Hi vọng mọi người có thể đến Bãi trước trải nghiệm một cách trọn vẹn!', '4 tháng 12, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'David D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/ba/74/ca/david-d.jpg?w=100&h=-1&s=1', 3, 'Nó không có bãi biển đẹp nhất ở Vũng Tàu nhưng nếu bạn đến bằng phà và don thì muốn mạo hiểm quá xa thì đây là khoảng cách đi bộ. Cát không phải là tốt nhất nhưng nước sạch một cách hợp lý và có một vài quán cà phê gần đó.', '26 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vũ Ngô', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/a1/8a/68/vu-n.jpg?w=100&h=-1&s=1', 5, 'Nơi tập trung vui chơi hợp lý, đông đúc. Nơi có thể hoạt động những trò chơi ngoài trời. Có khu ăn uống hả sản tuơi sống. Buổi tối có thể đi dạo biển', '16 tháng 10, 2019', CURRENT_TIMESTAMP);

