    VALUES (gen_random_uuid(), v_place_id, 'Ni', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Tốt. No cành hông là có thiệt. Ngon, đỉnh, giá cũng ok nha. Lần đầu tiên mình đến nhà hàng vào buổi trưa nhưng trải nghiệm tốt. Tuy nhiên toilet hơi hầm hơi một chút', '25 tháng 10, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Navigator10495743274', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/42/default-avatar-2020-20.jpg?w=100&h=-1&s=1', 5, 'Vitamin sea😘. Mức giá có thể nhỉnh hơn quán bình dân một, nhưng so với độ tươi ngon, kích cỡ hải sản và cách phục vụ tận tâm của nhân viên (tư vấn món nhiệt tình), thì hoàn toàn xứng đáng từng đồng. Đây không chỉ là một bữa ăn, mà là một trải nghiệm ẩm thực trọn vẹn. Nếu bạn là tín đồ của hải sản và coi trọng sự cân bằng giữa chất lượng-giá trị, thì đây chính là nơi bạn nên đến trải nghiệm!”', '13 tháng 10, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Trip10655481273', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 5, 'Ăn tối. Đồ ăn ngon, bia ngon, phục vụ tốt. Gia đình mình có dịp trải nghiệm ăn uống tại quán ấn tượng khá tốt về đồ ăn ngon, bày trí đẹp và giá cả hợp lý', '4 tháng 10, 2025', CURRENT_TIMESTAMP);

