    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/35/0f/c9/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Anny', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/a2/52/0c/caption.jpg?w=200&h=200&s=1', 1, 'Trải nghiệm cực kỳ khó chịu. Trải nghiệm rất tệ cho lần quay lại này, mình đi thứ hai đầu tuần mà đợi món hơn 45p trong khi món chỉ là món hấp, mình có nói với nhân viên nhưng mà không thấy sự phản hồi, mình rất nhiều lần dùng bữa tại nhà Hàng GH1 và có book bàn trước nhưng từ nay sẽ không quay lại. Nếu ai có ý định ăn ở đây mà dư thời gian đợi thì nên nha, còn nếu như hong dư thời gian đợi thì mình khuyên không nên đến. Và lúc mình thanh toán gặp bạn quản lý nhưng cũng không nghe bạn nói xin lỗi về vấn đề mình gặp lúc dùng bữa. Làm trong ngành dịch vụ đây là lần đầu mình gặp tại một nhà hàng có tiếng xử lý tình huống như vậy', '22 tháng 6, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Culture05306046923', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 5, 'Bữa ăn gia đình @. Nhà hàng nhiều món ngon view đẹp món ăn trang trí đẹp nhân viên phục vụ nhiệt tình cần đặt bàn trước khoảng 1 hoặc 2 ngày vào dịp cuối tuần và các dịp lễ Tết 😍😍😍😍😍😍', '8 tháng 12, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Camper23383018792', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 5, 'Trãi nghiệm đáng nhớ !. Nhà hàng rất chỉnh chu , món ăn rất ngon , (món mực sữa chiên nước mắm ) view sát biển rất đẹp ,tôi sẽ giới thiệu với bạn bè và người thân. Sẽ quay trở lại !', '5 tháng 11, 2025', CURRENT_TIMESTAMP);

