    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'DayTrip18754126804', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/11/default-avatar-2020-23.jpg?w=100&h=-1&s=1', 1, 'Đồ ăn kém tươi. Đồ ăn lèo tèo vài ba món hải sản, không tươi. Bên mình đặt gói vip với tôm hùm - đã dặn trước là muốn dùng nóng mà khi đến tôm hùm lạnh ngắt như đã được dọn ra từ lâu. Quầy hải sản được khoảng 4 loại hải sản gồm hàu, tôm càng xanh, ốc hương, ghẹ, thì trong đó ghẹ ôi đến độ có mùi, chỉ có món hàu là tươi nhưng siêuuu bé. Nói chung là thất vọng tràn trề. Không bao giờ quay lại lần 2', '17 tháng 1, 2026', CURRENT_TIMESTAMP);
