    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/fe/39/6c/pandan-leaf-saigon-rolls.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'annette m', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi yêu thích thị trường vì vậy chúng tôi đã nỗ lực để đi bộ và tìm thấy nó. Thị trường không lớn và khá thoáng và nóng. Bạn cảm thấy như bạn đang ở trong bất kỳ cửa hàng xử lý quân đội nào, nhưng có một viên ngọc nhỏ của một cửa hàng được giấu ở phía sau, bạn chỉ cần đi qua và tìm thấy nó. Chỉ cần lên kế hoạch đi bộ và 30 phút bên trong để xem nhanh. Nó sắp xếp các tour du lịch lịch sử của Việt Nam.', '19 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Marek_Majko', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/68/default-avatar-2020-9.jpg?w=100&h=-1&s=1', 5, 'Tôi nghĩ rằng nơi này đáng để ghé thăm, nhưng tôi sẽ không mua thuốc chống hăm, đừng nghĩ hàng hóa bán của bạn thực sự cổ điển.', '12 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'rrwashing', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f6/0d/default-avatar-2020-34.jpg?w=100&h=-1&s=1', 4, 'Thực sự có tất cả mọi thứ ở đó. Tôi thích đi bộ xung quanh và nhìn thấy tất cả các biệt danh. Bạn thực sự có thể nhận được bất cứ điều gì ở đó. Mặc dù không có gì là nguyên bản (''di tích'' và ''cổ vật'')', '3 tháng 9, 2019', CURRENT_TIMESTAMP);

