    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/5a/72/8e/banh-mi-ba-huynh-madam.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Camper44945171798', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, 'Trung tâm mua sắm thật sự ấn tượng . Đầu tiên, vị trí của trung tâm rất thuận tiện, nằm ngay giữa trung tâm thành phố,  vị trí thuận lợi, mà còn là sự đa dạng của cửa hàng và thương hiệu. Từ các cửa hàng thời trang hàng đầu đến những thương hiệu. Chất lượng sản phẩm. Nhân viên phục vụ rất thân thiện và nhiệt tình. Họ luôn sẵn lòng hỗ trợ và giúp đỡ khách hàng trong mọi tình huống.', '17 tháng 4, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nguyen L', NULL, 5, 'Nằm trong khu phố rất không du lịch của khu tây ba lô, chợ không quá lớn nhưng cũng giống như một mê cung như các quầy hàng, xe được sắp xếp theo một trật tự hỗn độn. Mùi đặc trưng của thị trường Sài Gòn. Cuộc sống hàng ngày với thực phẩm địa phương, rau, trái cây, quần áo. Tất cả là cực kỳ địa phương. Sẽ không có nhiều thứ để bạn khám phá, nhưng để tận hưởng trải nghiệm địa phương đích thực, chẳng hạn như để xem người bản xứ bán và mua mọi thứ như thế nào, mọi người sống cuộc sống bình thường như thế nào từ những gì họ mặc. Thật vui với tôi.*** Phải - thử ẩm thực:. Mi Quang ~ ít hơn $ 2. Bun Thit Nuong ~ ít hơn $ 2. Bánh Mì ~ $ 0. 5. Đồ uống ngọt ~ ít hơn $ 0. 5Tất cả đều rẻ và ngon! Rất Việt Nam!', '21 tháng 6, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'telcom3', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 4, 'Thị trường địa phương cho mọi thứ; quần áo, phụ kiện quần áo, thực phẩm tươi sống, thực phẩm khô, trái cây tươi, thực phẩm chế biến, phần chợ cá, chợ thịt bên trong, họ thậm chí còn có một gian hàng đậu phụ. Bán rau, hoa quả ở bên ngoài tòa nhà chính dưới lều. Ồn ào và đông đúc, giá rẻ, nhiều người dân địa phương mua sắm ở đây. Rất ít khách du lịch tại chợ này.', '17 tháng 5, 2018', CURRENT_TIMESTAMP);

