    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tuấn Toàn T', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Tham quan city tour. Mình ghé nhà hàng vào tháng 8-2025. Nhân viên phục vụ nhiệt tình và nhanh nhẹn. Đồ ăn lên nhanh và nóng, thức ăn nóng, vị rất vừa ăn', '21 tháng 8, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Phuong N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/7a/default-avatar-2020-25.jpg?w=100&h=-1&s=1', 5, 'Gia đình rất thích. Thức ăn Việt Nam rất ngon, đặc biệt là chả giò, bánh xèo, phở xào. Các bạn nhân viên thì phục vụ cực kì nhiệt tình. Gia đình chúng tôi rất thích', '6 tháng 6, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sightseer12035174275', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/77/ae/default-avatar-2020-2.jpg?w=100&h=-1&s=1', 5, 'Đánh giá 5 sao. Tôi đặc biệt ấn tượng với cách trình bày món ăn, rất đẹp mắt và hấp dẫn. Mỗi món ăn đều được chuẩn bị cẩn thận và trình bày một cách chỉnh chu.
Không chỉ có vậy, nhân viên phục vụ tại nhà hàng cũng rất thân thiện và chu đáo. Họ luôn sẵn sàng giúp đỡ và tư vấn cho khách hàng về các món ăn và đồ uống.Tổng thể, tôi đánh giá nhà hàng 5 sao', '1 tháng 6, 2025', CURRENT_TIMESTAMP);

