    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mopo123', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Tham quan Santa Teresa là một trong những trải nghiệm yêu thích của chúng tôi ở Rio, và có một hướng dẫn viên địa phương đã làm cho nó trở nên đặc biệt hơn nữa. Chúng tôi đã có thể dành thời gian, khám phá những con phố quyến rũ, chiêm ngưỡng những tòa nhà đầy màu sắc và học được rất nhiều về lịch sử và văn hóa của khu phố.Điều tôi thích nhất là có thể nhìn thấy những địa điểm và chi tiết nhỏ mà tôi có thể dễ dàng bỏ lỡ nếu tự mình đi. Hướng dẫn viên của chúng tôi thân thiện, am hiểu và làm cho toàn bộ trải nghiệm trở nên thư giãn và thoải mái.', '30 tháng 8, 2026', CURRENT_TIMESTAMP);
