    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/ca/9c/70/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Go Went Korn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/db/61/18/caption.jpg?w=100&h=-1&s=1', 5, 'Bảo tàng lịch sử đền Seosomun: Khu bảo tồn của sự im lặng và thiết kế đạt giải thưởng bên dưới Seoul', '9 tháng 3, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Wi1s0n', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Một viên ngọc ẩn tuyệt đối. Trong khi bảo tàng/phòng trưng bày này kỷ niệm các sự kiện rõ ràng rất có ý nghĩa đối với người Công giáo, bạn không cần phải theo đạo để bị ấn tượng và xúc động bởi cả sự thanh bình và quy mô của nơi này. Đây là một ví dụ điển hình về kiến trúc hiện đại và có các tác phẩm nghệ thuật sắp đặt đạt tiêu chuẩn cao nhất. Chúng tôi thực sự tình cờ thấy nó và rất vui vì chúng tôi đã làm. Rất khuyến khích!', '22 tháng 7, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Annette F', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/e3/default-avatar-2020-59.jpg?w=100&h=-1&s=1', 5, 'Đây là một bảo tàng rất khác thường ngoài con đường bị đánh đập trong khu phố Seosomun của Seoul. Nó ban đầu là một nhà để xe và được xây dựng lại như một bảo tàng dưới lòng đất. Mục đích chính là để kỷ niệm và kỷ niệm lịch sử đàn áp người Công giáo tại Hàn Quốc. Thêm vào không gian rất hiện đại là một triển lãm tuyệt vời của nghệ thuật đương đại. Đó là giá trị một chuyến đi để tìm bảo tàng mới này.', '24 tháng 2, 2020', CURRENT_TIMESTAMP);

