    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Brad 🇭🇰', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/8e/66/7e/caption.jpg?w=100&h=-1&s=1', 3, 'Một danh sách hơi lạ ở đây trên TripAdvisor nhưng có lẽ sẽ có ích cho du khách trong tương lai. Bape Kids là cửa hàng bán lẻ quần áo trẻ em. Họ có một cửa hàng tại Lee Gardens ở Causeway Bay (HK Island) và tại đây trong khu Ocean Terminal của Harbour City (TST).Cửa hàng gần Shake Shack ở cấp độ OTG. Giờ mở cửa là 11 giờ sáng đến 9 giờ tối. Bạn sẽ tìm thấy khá nhiều cửa hàng quần áo, sách và đồ chơi trẻ em khác trên cùng một tầng, vì vậy bạn có thể muốn mua sắm một chút trên tầng này nếu bạn quyết định đến trung tâm mua sắm cụ thể này để mua sắm quần áo trẻ em.', '11 tháng 3, 2022', CURRENT_TIMESTAMP);

