    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/ba/ad/d6/photo0jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nga Tran', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/23/4d/ba/03/ngatran90.jpg?w=100&h=-1&s=1', 5, 'Chùa được xây dựng từ thế kỷ 19 thời vua Minh Mạng. Thực ra chùa tên là Vĩnh Trường có ý nghĩa là "Vĩnh cửu đối sơn hà, trường tồn tề thiên địa". Mà người dân quen gọi là Vĩnh Tràng rồi.Kiến trúc ở đây pha trộn giữa Á & Âu. Đặc biệt là chánh điện được xây dựng theo kiểu nhà tổ ko giống với những nơi khác. Và nơi này cũng được công nhận là di tích lịch sử văn hóa cấp quốc gia cần được giữ gìn. Trong nhà có 18 tượng La Hán được tạc từ thế kỷ 20. Ngoài sân thì có 3 tượng Phật khổng lồ: Phật ngồi, Phật đứng và Phật nằm. Trước chùa có hoa viên cũng có tượng Phật lớn lun nha. Có dịp thì ghé thử nè.', '19 tháng 5, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'SallyFranz', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/6e/5c/95/sallyfranz.jpg?w=100&h=-1&s=1', 5, 'Phải xem. Một ngôi chùa trang trí công phu, chùa cao 7 tầng và 3 tượng phật cao 4 tầng. Những khu vườn và đền thờ đều gây kinh ngạc và thiền định. Một ngôi đền làm việc với các nhà sư thực hiện các dịch vụ làm cho hình ảnh tuyệt vời.', '21 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roland B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/2b/b6/fa/r0landbrunner.jpg?w=100&h=-1&s=1', 4, 'trên đường đến hoặc từ đồng bằng sông Cửu Long, bạn sẽ đi qua Mỹ Tho. Điều duy nhất (và duy nhất) nhìn thấy là Đền Vinh Trang. Đầu tiên nó là một ngôi đền cũ, rất đẹp. Và thứ hai (và cho khách du lịch đầu tiên) có ba bức tượng Phật lớn bên cạnh ngôi đền. thời gian hình ảnh.', '9 tháng 1, 2020', CURRENT_TIMESTAMP);

