    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sightseer46418077171', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Cơm Poke và bánh Crepe ngon và mới lạ,đã được trải nghiệm món Pháp ngay ở Mỹ tho, sẽ trở lại lần tới. Cơm Poke và bánh Crepe ngon và mới lạ,đã được trải nghiệm món Pháp ngay ở Mỹ tho, sẽ trở lại lần tới', '7 tháng 9, 2023', CURRENT_TIMESTAMP);
