    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2b/cb/01/86/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'helenwilling', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/ea/default-avatar-2020-63.jpg?w=100&h=-1&s=1', 5, 'Bữa trưa nhóm tuyệt vời. Nhà hàng tuyệt vời, chúng tôi đã thưởng thức một bữa trưa tuyệt vời với cá voi và các đặc sản khác chặt chẽ bên cạnh sông Mê Kông. Muốn giới thiệu nơi này là một nhóm 18 người nhưng có những cặp vợ chồng ở đây cũng rất thích đồ ăn và địa điểm', '26 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bellatako', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/57/05/cb/christina-c.jpg?w=100&h=-1&s=1', 4, 'Vị trí đẹp trên mặt nước. Bóng gạo căng phồng. Có một bữa ăn trưa ngon miệng ở đây trong vọng lâu riêng của chúng tôi trên mặt nước. Bầu không khí yên bình. Họ làm bánh tráng cuộn cá cuộn rất ngon. Nhưng yêu thích của tôi là bóng gạo căng phồng. Bán ngọt. Thơm ngon', '1 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'PAULHCMC', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, 'Trứng rồng trên Đảo @ Mekong Taste. Mekong Taste là một nơi ẩn náu tuyệt vời, giá cả phải chăng, sạch sẽ ở đồng bằng sông Cửu Long. Nó nằm bên bờ sông Cù Lao Thới Sơn, một trong những hòn đảo trên sông Mekong vẫn là một phần của tỉnh Tiền Giang.

Bạn có thể đến đây thuận tiện trong khi băng qua cầu Rạch Miễu bằng xe hơi / xe buýt hoặc trong khi đi thuyền qua cầu tàu chính thức của họ.

Nếu bạn đang thực hiện một chuyến đi đường bằng xe máy, bạn cũng nên nghỉ đêm tại khu nghỉ mát kiểu cắm trại của họ và tận hưởng môi trường xung quanh và đặc biệt là cho hòn đảo Longan nổi tiếng này.

Nó cũng không được gọi là Mekong Taste cho không có gì. Nó là quá hấp dẫn không thử tất cả các món ăn đơn trên thực đơn khu vực đích thực của họ. Đối với tôi như nổi bật là những quả trứng rồng (cơm chiên rán) mà cũng có kỹ năng rất đặc biệt để chuẩn bị.
 
Tôi yêu cá voi Voi chiên, cũng là một món ăn đặc trưng của địa phương. Thêm cá ngon, mọng nước vào cuộn giấy gạo của bạn với các loại thảo mộc và gia vị khác, cuộn nó, nhúng nó và ăn nó bằng ngón tay của bạn và tất cả.

Và nhiều món ăn ngon hơn bạn nên thử.

Nhân viên của họ thân thiện và chu đáo và nó chỉ là một ốc đảo để lấy lại cảm giác của bạn sau một tuần làm việc đầy đủ trong sự nhộn nhịp của thành phố lớn', '27 tháng 8, 2018', CURRENT_TIMESTAMP);

