    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'nhu m', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/b8/default-avatar-2020-26.jpg?w=100&h=-1&s=1', 5, 'tuyệt vời. Món ăn ở Benaras rất đậm vị Ấn, thơm nồng mùi gia vị đặc trưng, ăn lạ miệng nhưng càng ăn càng cuốn. Curry ở đây ngon, đậm đà, ăn với bánh naan là hết sẩy. Có vài món hơi nồng với người chưa quen nhưng rõ ràng là đúng chất Ấn thật sự. Không gian quán ấm cúng, nhân viên nhiệt tình, đi ăn thử cho biết thì rất đáng', '6 tháng 6, 2025', CURRENT_TIMESTAMP);
