    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jason B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/e7/default-avatar-2020-37.jpg?w=100&h=-1&s=1', 5, 'Bánh xèo đích thực. Gia đình ít kinh doanh. Thức ăn ngon, bia lạnh. Một đoạn đi bộ ngắn dọc theo kênh từ Chợ Mỹ Tho về phía sông. Thú vị nhất', '10 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'kc j', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/7f/7b/aa/kc-j.jpg?w=100&h=-1&s=1', 3, 'Một nhà hàng đẹp. Chúng tôi muốn ăn chay. Hướng dẫn của chúng tôi đã đưa chúng tôi ở đây.
Tôi nghĩ rằng việc tìm kiếm thực phẩm chay không phải là rất dễ dàng ở Việt Nam.
Nhà hàng này đã phục vụ chúng tôi một số thực phẩm chay phong nha.
Một món đồ mới mà chúng tôi có ở đây là một viên cơm nếp khổng lồ. Đó là một quả bóng phồng khổng lồ mà chúng tôi phải ăn bằng cách vỡ thành những mảnh nhỏ.
Chúng tôi cũng đã có mì Việt Nam và đậu phụ với rau chuẩn bị.
Cuối cùng, chúng tôi đã có Xôi, một món tráng miệng làm từ gạo nếp', '21 tháng 4, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoatg', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/02/75/28/caption.jpg?w=100&h=-1&s=1', 5, 'Bánh xèo chay tiền Giang " nhà làm". Món bánh xèo chay nhà làm với hương vị đặc sắc , thích hợp các mem ăn chay 
Team ăn chay 
Món chay mỗi ngày cho các bạn 🌮', '9 tháng 3, 2019', CURRENT_TIMESTAMP);

