    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hiền Ngô', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/5a/default-avatar-2020-36.jpg?w=100&h=-1&s=1', 4, 'Khá là nghèo làn về cơ sở vật chất và trưng bày. Không có gì nổi bật và thu hút cả. Đi một lần cho biết......................', '17 tháng 6, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roland B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/2b/b6/fa/r0landbrunner.jpg?w=100&h=-1&s=1', 3, 'đó là một tòa nhà thuộc địa đẹp, ngay bên cạnh khách sạn Vit Uc lớn, nhưng chuyến thăm không thực sự đáng giá, trừ khi bạn quan tâm đến lịch sử địa phương của cuộc chiến chống vi khuẩn địa phương. Bến Tre là điểm khởi đầu của cuộc nổi dậy và vì thế rất quan trọng.', '8 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Rosemary650', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/05/fd/44/fb/rosemary650.jpg?w=100&h=-1&s=1', 3, 'Tôi yêu tòa nhà thuộc địa Bảo tàng Bến Tre được đặt trong đó và có lịch sử địa phương quý giá được ghi lại ở đây nhưng tôi rất buồn khi thấy sự thiếu cẩn thận dành cho các cuộc triển lãm. . . hình ảnh mờ dần các bức tranh bị trầy xước, mô tả không đầy đủ / bản dịch không đủ. Tôi hy vọng một số tiền có thể được tìm thấy để bảo tồn câu chuyện của Ben Tre.', '23 tháng 5, 2019', CURRENT_TIMESTAMP);

