    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'suoi Nge', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Ăn Bentre. Trải nghiêm tốt ,ăn ngon lắm.Gia đình đến đây qua cty Tourluk ở TPHCM', '25 tháng 7, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Debby C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/2d/16/1e/caption.jpg?w=100&h=-1&s=1', 4, 'Không khí thân thiện và tốt. Đây là một nhà hàng nhỏ đáng yêu để thưởng thức bữa trưa trong tour du lịch của chúng tôi. Món ăn truyền thống. Thực phẩm rất tươi và dịch vụ thân thiện. Cảm ơn bạn Giao hướng dẫn viên của chúng tôi đã tham gia với chúng tôi ở đó', '1 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mike Hutt', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/82/5f/36/photo0jpg.jpg?w=200&h=-1&s=1', 4, 'Ăn trưa gần sông Mê Kông. Một nhà hàng nông thôn xinh đẹp tôi ở giữa hư không. Bạn phải ba lấy ở đây để tìm nó! Các món ăn là tuyệt vời, dịch vụ tốt, giá cả rất hợp lý và môi trường xung quanh là tuyệt vời. Được đề xuất!', '2 tháng 4, 2018', CURRENT_TIMESTAMP);

