    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Departure32114499845', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/7b/default-avatar-2020-56.jpg?w=100&h=-1&s=1', 5, 'TUYỆT VỜI. Vị trí ngay trung tâm, món ăn ngon, giá cả hợp lý, phục vụ chu đáo, không gian mát mẻ, cảnh sông nước rất đặc trưng miền Tây!!!!', '15 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ngân N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e6/ea/default-avatar-2020-54.jpg?w=100&h=-1&s=1', 5, 'Địa điểm đáng trải nghiệm tại Bến Tre. Đồ ăn vị đậm đà, có nhiều món đặc trưng miền tây, không gian mát mẻ, nhân viên nhiệt tình. Mọi người nên thử nha', '14 tháng 1, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Voyager11664723444', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/91/default-avatar-2020-62.jpg?w=100&h=-1&s=1', 5, 'Nhà Hàng Nổi. Món ăn ngon đậm chất miền tây, nhân viên chu đáo vui vẻ, nhiệt tình. Không gian thoáng mát bên cạnh sông Hàm Luông tạo cảm giác quay về tuổi thơ mộc mạc nơi sông nước. Gía cả hợp lý so với chất lượng. Thực đơn phong phú đặc biệt món gỏi bò bông bần, cơm trong trái dừa , tép ram dừa, lẩu cá bông lau nấu bần đậm vị ....nói chung là đáng để trải nghiệm', '14 tháng 1, 2026', CURRENT_TIMESTAMP);

