    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/90/0b/f8/3d-coffee.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Justine D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/90/0b/f5/3d-coffee.jpg?w=200&h=200&s=1', 5, 'Bạch tuộc và mặt cười tốt nhất. Rất đáng để ghé thăm, nghĩ rằng chúng tôi đã thử hầu hết các menu - được hiển thị xung quanh khu vực nấu ăn rất hấp dẫn. Khu vực chỗ ngồi bên ngoài và ghế sofa bên trong. Dịch vụ thực sự thân thiện từ tất cả mọi người và kinh nghiệm hoàn toàn dễ chịu. Kem dừa là ngon nhất!', '30 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Naomidonc', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'Đồ ăn nhẹ tuyệt vời. Nơi thân thiện với sự rung cảm tuyệt vời, rất nhiều trẻ em đi chơi. Chúng tôi đã có món bạch tuộc nướng ngon nhất (có thể khó đánh bại trong tháng tới khi đi du lịch ở Việt Nam) chỉ với 50 đồng, cộng với bia và kem. Chỉ 5 phút đi bộ từ Oasis', '27 tháng 7, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kiwi1963', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/c9/2d/f5/kiwi1963.jpg?w=100&h=-1&s=1', 5, 'Cách khách sạn Oasis không xa. Chúng tôi đã có một số đồ ăn nhẹ ngon + đồ uống và tất cả đã lên đến khoảng 4 đô la Úc. 00. Chúng tôi đã thất vọng khi không trở lại đó. Nếu bạn đang đi du lịch với trẻ em, họ sẽ thích nó. Những con cá rất lạ trong bể sẽ giải trí chúng!', '11 tháng 6, 2019', CURRENT_TIMESTAMP);

