    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Amily Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ed/00/default-avatar-2020-4.jpg?w=100&h=-1&s=1', 5, 'Thức ăn ngon mà giá rất rẻ. Pizza ngon , mỳ ý ngon , hào nướng cũng ngon mà giá rất bình dân . Được phục vụ đá đậu rất mát ( miễn phí ) . Điểm 10 cho chất lượng', '10 tháng 7, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Thang Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/f1/37/4b/caption.jpg?w=100&h=-1&s=1', 4, 'Hiếm khi tìm thấy các bữa ăn phương Tây ở B? N Tre. Thức ăn tốt nhất ở B Tre.
B? N Tre không phải là thành phố hiện đại như M? Thơ, H? Thành phố Ch Minh, đó là lý do tại sao thật khó để tìm thấy thức ăn phương Tây ở đây.
Coco bạc hà là văn hóa ẩm thực pha trộn giữa phương Tây và phương Đông, không thực sự là thực phẩm phương Tây nhưng chấp nhận được.
Có thịt bò, hamburger, pizza, mì và đồ uống. Tất cả các bữa ăn đều ổn đối với tôi.
Chủ quán là người tốt bụng, thân thiện, người tư vấn mọi thứ về bữa ăn cho khách hàng. Ông cũng là đầu bếp.
Có không gian sạch sẽ, gọn gàng.
Giá rẻ, khoảng 2 - 10 usd. Thỉnh thoảng bạn có thể đặt thực đơn độc đáo cho riêng mình với đầu bếp cho bữa tiệc đặc biệt', '7 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Vicariously', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/07/d4/05/vicariouslytravels.jpg?w=100&h=-1&s=1', 5, 'Bạn sẽ không hối tiếc khi ăn ở đây. Chúng tôi rất thích ăn tại Coco Pizza Mint. Thực đơn rất đơn giản tuy nhiên đồ ăn ở đây rất tuyệt, pizza rất ngon, lớp vỏ được làm thủ công không giống như nhiều loại pizza mà chúng tôi đã thử từ trước đến nay ở miền Nam Việt Nam. Chúng tôi đã đặt hàng tối cao của họ bao gồm ngô, nấm, thịt xông khói, và một lượng phô mai vừa phải. Bên trong không phải là xa xỉ nhất nhưng bạn sẽ không hối tiếc khi ăn ở đây. Các chủ sở hữu rất thân thiện', '23 tháng 7, 2019', CURRENT_TIMESTAMP);

