    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/e0/ea/40/photo1jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tường Vy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 4, 'Mình thực sự rất thích tham quan những nơi có nét cổ điển. Chùa ở đây rất đẹp và có nhiều nơi sống ảo chụp hình khác so với nơi khác. Nên đi viếng thăm và thắp hương nơi đây nhé.', '13 tháng 3, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr. RaTha Tour Guide', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/23/3b/fd/ba/ratha-angkor.jpg?w=100&h=-1&s=1', 5, 'Đây là một nơi tốt đẹp để truy cập bởi vì nó có nhiều điều để khám phá và tận hưởng nó. Nhiều khách du lịch đến từ các quốc gia khác muốn đến thăm chùa Ang và bảo tàng Khmer. Họ thích nhìn những cây cổ thụ được trồng quanh hồ Ao Ba Om khiến nó trở nên đẹp và yên bình.', '14 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'LondonerAbroad29', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 4, 'Một ao mở xinh xắn nằm ở phía sau theo phong cách Khmer truyền thống. Các ngôi đền bên trong rất tuyệt vời với các nhà sư đi bộ xung quanh. A phải khi trong khu vực!', '30 tháng 3, 2018', CURRENT_TIMESTAMP);

