    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/c3/68/c5/la-vang-restaurant.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bá Dinh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e3/1f/default-avatar-2020-46.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng La VANG - Trà Vinh. Địa điểm dễ tìm có sẵn trên Google Maps, view đẹp, có chút cổ điển thích hợp cho mọi người check in, menu song ngữ Việt - Anh, giá cả niêm yết rõ ràng, chỉ từ 90k nhưng các món ăn nấu đậm đà, trình bày bắt mắt. Mình và gia đình ăn vừa miệng và thấy ngon. Ghé Trà Vinh các bạn cứ ghé thử', '18 tháng 8, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roland B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/2b/b6/fa/r0landbrunner.jpg?w=100&h=-1&s=1', 4, 'rất việt nam. Như toàn bộ Trà Vinh, La Vang cũng là một nơi rất Việt Nam. không có món ăn quốc tế, chỉ có bếp Việt Nam, nhưng có một bản dịch tiếng Anh trong menue, vì vậy ít nhất bạn biết những gì bạn đặt hàng. Nhà hàng lớn, rất sạch sẽ và đẹp. dịch vụ thân thiện, nhưng không ai nói tiếng Anh hoặc tiếng Pháp. Các món ăn được chế biến theo cách người Việt thích nó - và bạn sẽ thích nó, nếu bạn đã quen với nó. Đó không phải là nấu ăn phương Tây, mà là thực phẩm địa phương rắn. Có bia, nhưng không có rượu', '4 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Em O', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng cho gia đình ở thị xã Trà Vinh.. Nhà hàng La Vang thật đẹp. Có nhiều lựa chọn thực phẩm trong thực đơn. Tôi thích "c? M chi n ru? C", thức ăn đặc biệt! ??', '27 tháng 4, 2018', CURRENT_TIMESTAMP);

