    VALUES (gen_random_uuid(), v_place_id, 'Thanh Tú', NULL, 3, 'Nơi khá tốt để chụp ảnh. Rộng, thoáng mát chụp ảnh đẹp nhưng hơi ích chỗ để chơi, hi vọng sẽ phát triển nhiều thêm nữa. cảm ơn', '13 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Short94', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/32/default-avatar-2020-12.jpg?w=100&h=-1&s=1', 5, 'Nơi tuyệt vời cho bữa tối. Nơi này có môi trường xung quanh tuyệt đẹp bao phủ trong đèn cổ tích với rất nhiều con đường và cây cầu để khám phá trước hoặc sau bữa tối.

Thức ăn ngon và giá rất hợp lý. Có rất nhiều karaoke và bầu không khí thân thiện.

Người quản lý (Ryan) nói tiếng Anh thực sự tốt và đề nghị các món ăn ngon cho bạn tôi và tôi!', '23 tháng 4, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
