    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/e0/ea/3f/photo0jpg.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'SapphDapph', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/1b/a5/2d/sapphdapph.jpg?w=100&h=-1&s=1', 4, 'Thiết lập dễ thương. Đối với Việt Nam, giá cả rất đắt nhưng tôi thấy chúng khá hợp lý khi du khách đến từ Úc (20 000 - 35 000). Quán cà phê là một sự thay đổi hiện đại tốt đẹp từ các đường phố Việt Nam.

Các đồ uống khá ngọt tuy nhiên nếm thử ngon. Các nhân viên rất hữu ích và kiên nhẫn với mệnh lệnh của tôi (tôi không nói tiếng Việt).

Tôi khuyên bạn nên đến nơi này', '13 tháng 12, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, '6kerry g', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/db/default-avatar-2020-10.jpg?w=100&h=-1&s=1', 5, 'Nhân viên đặc biệt hữu ích. Chúng tôi kêu gọi cố gắng tìm kiếm sự giúp đỡ trong việc định vị chỗ ở của chúng tôi. Chàng trai trẻ đặc biệt hữu ích trong việc gọi điện thoại cho chúng tôi và dịch cuộc gọi.
Đã có một ly cà phê đá. . . rất tốt.
Đẹp sạch nhà vệ sinh phương Tây', '24 tháng 8, 2017', CURRENT_TIMESTAMP);

