    VALUES (gen_random_uuid(), v_place_id, 'DAVID L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ef/32/default-avatar-2020-12.jpg?w=100&h=-1&s=1', 5, 'Thật tuyệt khi đến thăm một nơi mà bạn biết rằng tiền du lịch có nguồn gốc sẽ trở lại để giúp đỡ và cải thiện người dân địa phương và cơ sở hạ tầng. Điều này khá ra khỏi cách Spot chỉ làm điều đó. Phụ nữ địa phương đã trình diễn sản xuất giấy gạo, máy tính xách tay, bưu thiếp, thư pháp và các sản phẩm đẹp khác. Đáng giá!', '29 tháng 11, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'scenichigh', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 5, 'Thật thú vị khi nhìn thấy mọi thứ đã được thực hiện như thế nào và phải thử một vài thứ thật ngon. Chuyến đi diễn ra rất nhiều cảnh quan, đáng yêu', '3 tháng 8, 2017', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'ndbob73', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/f0/1a/8e/ndbob73.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi đã được trình bày về ca hát và âm nhạc địa phương. Thú vị, mặc dù một chút du lịch. Người Việt chắc chắn đã học được kinh doanh.', '22 tháng 3, 2017', CURRENT_TIMESTAMP);

