    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Maxmax98', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 1, 'Trải nghiệm. Mình viết bài review này nhằm cho quân được cải thiện hơn. Về phần tốt của quán thì view rất đẹp, rất hiện đại kèm theo một chút truyền thống, menu cũng đa dạng, nhiều khu vực để lựa chọn, nhưng điểm trừ của quán là nước hơi tệ so với mình nghĩ, vấn đề điểm trừ là nhân viên phục vụ rất tệ, rất thái độ với khách, và 1 điểm trừ nửa là ngoài nước tệ ra thì mình k biết với cafe quán này có vấn đề khi đem 1 ly cafe ra và mình rất bất ngừ v nó k tới 1 ngụm uống. Đây là trải nghiệm của mình vào diệp tết, mong quán rút được kinh nghiệm và mình hy vọng là lần sau đến thì nó sẽ được thay đổi', '3 tháng 2, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'R C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi đã đi cho các mục menu Veg.. Có một nhà hàng chay trên đảo An Bình (dường như đã đóng cửa), và đây là nhà hàng Trip Advisor duy nhất ở Vĩnh Long thân thiện với rau. Nên chúng tôi đã đi. Họ có 4 món trong thực đơn song ngữ và chúng tôi đã chọn Mì sợi. Chúng rất tốt, mặc dù kích thước phần hơi nhỏ. Thực đơn đồ uống là tuyệt vời. Dịch vụ là tuyệt vời Có vẻ như họ đưa âm nhạc phương Tây cho chúng tôi. Trang trí rất hiện đại và hông. Làm sạch tất cả xung quanh', '9 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Companion52105334165', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/b8/default-avatar-2020-22.jpg?w=100&h=-1&s=1', 5, 'Nhà hàng ngon. Ở Vinh dài 3 ngày, bạn trai và tôi, chúng tôi đến ăn tối tại nhà hàng này mỗi tối.
Đồ ăn rất ngon, đồ uống thì tuyệt vời và giá rẻ. Và đội rất đẹp!', '5 tháng 1, 2020', CURRENT_TIMESTAMP);

