    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Julie B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/20/default-avatar-2020-31.jpg?w=100&h=-1&s=1', 4, 'Nhân viên tốt, thức ăn ngon. Nhân viên rất tốt, người đã dịch đơn bằng tiếng Anh cho chúng tôi. Chúng tôi có trứng với bánh mì và nước cam. Tất cả đều rất tốt. Họ bật quạt cho chúng tôi khi chúng tôi đến. Nhân viên chăm sóc, thức ăn ngon, địa điểm đẹp', '5 tháng 5, 2018', CURRENT_TIMESTAMP);

