    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'JR_Essex', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 4, 'Thực sự thú vị khi đi lang thang quanh khu chợ truyền thống này, vô số sản phẩm tươi, trái cây và rau quả tươi tuyệt vời. Rất nhiều sản phẩm sống, bao gồm cá, rắn, vịt, gà. Mọi người thực sự thân thiện, mặc dù chúng tôi cản đường! ! Có lẽ là một cú sốc cho những người mong đợi thực phẩm của họ được chuẩn bị trước và bọc trong nhựa!', '27 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
