    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Walt0305', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/a7/default-avatar-2020-44.jpg?w=100&h=-1&s=1', 4, 'Nếu bạn muốn thấy một thị trường địa phương THỰC SỰ với sự ưu tiên của người dân địa phương thực hiện việc mua bán thực phẩm hàng ngày của họ, thì đây là điều tốt nhất chúng tôi thấy trong 7 ngày dọc sông Mê Kông và các chuyến đi trong ngày đến Sài Gòn (Việt Nam) và Xiêm Riệp (Campuchia). Sự pha trộn hấp dẫn của tất cả các loại thịt - - bò, lợn, gia cầm, rắn, cá, côn trùng, ếch, và một số loại tôi không thể dễ dàng xác định - - và rau.', '16 tháng 1, 2020', CURRENT_TIMESTAMP);

