    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/c8/89/42/caption.jpg', 1, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/c8/89/44/caption.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/79/f8/ae/rodman100.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/d9/60/b3/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'cw f', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 5, 'Tất cả được khắc trên đá, những đường hầm này được dùng làm nơi chôn cất cho những con bò Apis thánh.Sarcophagus rất lớn vẫn còn tại chỗ. Du khách đi bộ trên sàn gỗ và có thể chiêm ngưỡng những tác phẩm độc đáo này. Toàn bộ khu vực này đã được cải tạo: một lối vào mới, sàn đi bộ bằng gỗ, những công trình sắt lớn để giữ cho tảng đá không rơi xuống trên chiếc tàu đá sarcophagus.Một chút tắt các bài hát bị đánh nhưng thú vị nhất.', '29 tháng 7, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Rodman100', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2c/79/f8/ae/rodman100.jpg?w=100&h=-1&s=1', 5, 'Đây là nơi mà phần còn lại của những con bò đực ướp xác được tìm thấy trong những năm 1850. Serapeum chỉ mới được mở 5 năm, có xấp xỉ. 24 viên đá granit sarcophagi có trọng lượng từ 50 - 70 tấn và được hạ xuống từ Aswan. Mỗi sarcophagi nằm trong phòng riêng của họ. Điều này được sử dụng giữa các triều đại thứ 19 và 26. Chiều dài của đường hầm là khoảng 350 mét. Người giám hộ đã cố gắng giải thích rằng chúng tôi không thể chụp ảnh, may mắn thay chúng tôi đã hướng dẫn với chúng tôi để nói rằng đây không phải là trường hợp, nhưng để xoa dịu anh ta, chúng tôi đã cho LE 20. Lệ phí nhập học là LE 100 riêng biệt với phí nhập cảnh LE 80 cho Saqqara', '14 tháng 6, 2017', CURRENT_TIMESTAMP);

