    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'places2seeplaces2go', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/fe/4b/e8/juliesbournemouth.jpg?w=100&h=-1&s=1', 4, 'Vì chồng là người hâm mộ chân, chúng tôi thường ghé thăm sân vận động trong các chuyến du lịchTôi nghĩ rằng sẽ rất thú vị khi ghé thăm sân vận động Olympic/sân vận động đi bộ của Campuchia.Nhân viên cho phép chúng tôi tự hỏi và chụp ảnh khi họ chuẩn bị cho trận đấu quan trọng vào cuối ngày.Hoạt động giải trí & hoạt động khác biệt ! !', '19 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Nikki_333_84', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2e/70/97/avatar023.jpg?w=100&h=-1&s=1', 4, 'Có rất nhiều công cụ đúc tại chỗ - rất ấn tượng và nếu bạn có cơ hội đọc về anh ấy / tòa nhà của anh ấy thì hãy làm - anh ấy đã sử dụng bê tông để làm việc với môi trường. Có lẽ đi trước khi nó bị phá hủy bởi những phát triển lớn trong khu vực.', '26 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
