    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/0f/f7/04/photo2jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roam55550840317', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Quán ăn có các món đồng quê rất ngon, đậm đà hương vị truyền thống. Không khí tại đây rất thoải mái, phù hợp để thư giãn. Quán ăn có các món đồng quê rất ngon, đậm đà hương vị truyền thống. Không khí tại đây rất thoải mái, phù hợp để thư giãn và thưởng thức ẩm thực. Nhân viên phục vụ nhiệt tình, chu đáo, tạo cảm giác gần gũi như ở nhà. Không gian được bày trí tinh tế, sạch sẽ, mang đến trải nghiệm ẩm thực trọn vẹn. Đây chắc chắn là địa điểm lý tưởng để quay lại nhiều lần', '9 tháng 1, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Roam55550840317', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'RẤT THÚ VỊ KHI THƯỞNG THỨC BỮA ĂN, MỌI NGƯỜI NHẤT ĐỊNH PHẢI THỬ KHI ĐẾN SA ĐÉC. NHÀ HÀNG SINH THÁI ĂN CÁC MÓN ĐỒNG QUÊ RẤT NGON, KHÔNG GIAN HỒ SEN RẤT THOẢI MÁI, RẤT THÚ VỊ KHI THƯỞNG THỨC BỮA ĂN, MỌI NGƯỜI NHẤT ĐỊNH PHẢI THỬ KHI ĐẾN SA ĐÉC', '1 tháng 10, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Back Street Crawler', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/9d/67/87/anthony-s.jpg?w=100&h=-1&s=1', 4, 'Nhà hàng độc đáo. Chúng tôi đến đây không biết nên trông đợi điều gì, và phát hiện ra một nơi độc đáo để đưa một nhóm đi dự tiệc hoặc đi chơi đêm
Rất đáng để ghé thăm', '16 tháng 10, 2019', CURRENT_TIMESTAMP);

