    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/3d/1a/66/hu-tieu-with-broth.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Dreamer53819362476', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/7c/01/default-avatar-2020-5.jpg?w=100&h=-1&s=1', 2, 'Trải nghiệm ko như mong đợi. Gia đình tôi ghé quán cho bữa trưa muộn. Quán rất nhỏ và nóng. Với giá 10 nghìn đồng 1 tô thì số lượng và chất lượng như vậy cũng tương xứng, không nên mong đợi quá nhiều. Bánh hủ tiếu dai ngon. Nếu đánh giá trên các trang là 4.3/5 thì hơi quá ưu ái', '25 tháng 2, 2024', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hai Phan (Francis)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/3a/b3/e4/caption.jpg?w=100&h=-1&s=1', 5, 'Mì gạo địa phương giá rẻ tuyệt vời. Nhà hàng địa phương nhỏ này đã có một câu chuyện dài, món ăn của họ là đơn vị và có hương vị riêng. Giá cực rẻ. Các món ăn là tuyệt vời. Nhà hàng rất nhỏ, bạn có thể phải chờ một chỗ và được phục vụ', '15 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Khoa', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 5, 'Ngon. Hủ tiếu Sa Đéc đã ngon nổi tiếng từ bao nhiêu năm nay nhưng khi đến với Hủ tiếu bà sẩm thì các bạn hết sức bất ngờ với giá chỉ 8k một tô, giá mà bây giờ hiếm có quán nào được giá đấy. Ngon mà Rẻ', '30 tháng 3, 2019', CURRENT_TIMESTAMP);

