    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sven M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/4a/default-avatar-2020-42.jpg?w=100&h=-1&s=1', 2, 'Phở không ngon. Bát ''phở'' mà tôi có là một trong những món tồi tệ nhất. Mặt khác, ''bun bo hue'' của vợ tôi trông đẹp hơn nhiều (và cô ấy nói nó cũng ngon', '29 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Peix M', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 5, 'Phở rất ngon. Nice staf và phở rất ngon, bạn có thể ăn bất cứ lúc nào. Phải đi sau khi đến thăm nhà của L’Amant. Thành phố cũng đẹp quá. ! ! ! !', '18 tháng 5, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Glen W', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/21/fb/7b/great-bowl-of-pho-here.jpg?w=200&h=200&s=1', 5, 'một nơi tuyệt vời cho một bát phở. Vợ tôi nói "phở ngon nhất". Tôi phải theo dõi điều đó với vợ tôi là "nhà phê bình thực phẩm khó tính nhất". Đủ để nói, đó là một bát phở bò ngon để bắt đầu một ngày. Chúng tôi đã ăn ở đây 5 năm trước nhưng không nhớ nó tốt như bây giờ. chúng tôi sẽ trở lại', '20 tháng 2, 2018', CURRENT_TIMESTAMP);

