    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr NHD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/89/19/3d/caption.jpg?w=100&h=-1&s=1', 5, 'Lần đầu tiên mình đến với khu du lịch Rừng tràm Trà Sư.Từ Châu Đốc, di chuyển xe máy tầm 30 phút là đến.Đường đi dễ dàng, ấn tượng là đoạn vào rừng tầm 4km, rợp bóng cây và nhà dân theo kiểu nhà sàn rất nhiều. Người dân hiền hoà & thân thiện.Rừng Tràm Trà Sư có nhiều hoạt động tham quan giải trí.Có phục vụ ăn uống nữa, nên sẽ là lựa chọn lý tưởng.Đi xuồng máy hoặc chèo tay, các bạn đều cảm nhận được sự hoang sơ nơi đây, nó gần gũi vô cùng với thiên nhiên.', '11 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
