    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KenMeKong', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/32/17/55/42/caption.jpg?w=100&h=-1&s=1', 4, 'Địa điểm đẹp, được trang trí với nhiều hoa và tiểu cảnh. Đi xuồng xung quanh ngắm thiên nhiên tuyệt vời. Tuy nhiên vào mùa khô thì không được đẹp lắm', '1 tháng 9, 2024', CURRENT_TIMESTAMP);

