    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KiranJ1303', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/91/default-avatar-2020-62.jpg?w=100&h=-1&s=1', 5, 'Ngay khi bạn vào chợ, thuyền của bạn bị tràn ngập bởi những người bán trái cây, đồ uống hoặc bữa ăn nấu cho bạn. Họ móc thuyền của họ vào của bạn và họ bị kéo theo khi thuyền của bạn di chuyển dọc. Đó là trải nghiệm tuyệt vời. Đây là một chợ bán buôn trên thuyền với các gia đình dùng bữa sáng trên thuyền của họ trong khi những người khác bán.', '14 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
