    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'JamesNav', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/13/3d/76/f7/jamesnav.jpg?w=100&h=-1&s=1', 3, 'Đây là một đánh giá sửa đổi và các ngôi sao. Vợ tôi và tôi không có kinh nghiệm tốt với nhân viên của Blue Cruiser ở phía biên giới Campuchia. Phía Việt Nam và nhân viên vẫn ổn. Thực hiện nghiên cứu để tìm ra lựa chọn hiệu quả nhất về chi phí cho việc đi ngược dòng sông.', '9 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Alex_Tallinn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/02/25/98/20/alex-tallinn.jpg?w=100&h=-1&s=1', 5, 'Công ty du lịch sẽ đưa chúng tôi lên một chiếc thuyền nhanh tiêu chuẩn 30 hành khách từ Châu Đốc đến Phnom Penh. Đi du lịch với một nhóm nhỏ (hai cặp vợ chồng) Tôi hỏi về việc nâng cấp lên một chiếc thuyền tư nhân VIP. Tổng chi phí chỉ thêm khoảng 300 đô la cho nhóm của chúng tôi, nhưng thật là một sự khác biệt rất lớn! Chúng tôi đã có một chiếc thuyền chở khách nhỏ hơn 10, một hướng dẫn tuyệt vời, sự chú ý cá nhân. Chúng tôi có thể ngồi bất cứ nơi nào chúng tôi muốn, di chuyển giữa bên trong và bên ngoài, hỏi hướng dẫn của chúng tôi bất kỳ câu hỏi. Nước, bia, trái cây và đồ ăn nhẹ đều được bao gồm. Chúng tôi đã thấy rất nhiều! Và rất thoải mái. Giá trị thực sự cho tiền.', '16 tháng 1, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'bcoombie1', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/b2/default-avatar-2020-69.jpg?w=100&h=-1&s=1', 5, 'mỗi người đến Châu Đốc, thuyền đáng tin cậy, cảm thấy rất an toàn. hãy chắc chắn rằng bạn có visa Việt Nam trước khi bạn rời đi. Một vài loại bia và một hành trình rất thư giãn vào Việt Nam. Một trong những điểm nổi bật của chuyến đi của chúng tôi đến Cambodia và Việt Nam.', '16 tháng 1, 2020', CURRENT_TIMESTAMP);

