    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/8d/8f/96/photo4jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Rose S', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/03/5b/58/46/rose-s.jpg?w=100&h=-1&s=1', 2, 'Không tốt . Sẽ không đi nữa. Dịch vụ kém. Bà già phục vụ chúng tôi gặp khó khăn trong việc hiểu những gì chúng tôi muốn. Cô không có kính nên dường như cô không thể đọc được thực đơn. Mì với thịt gà, Phần rất nhỏ và không nhiều hương vị. Chả giò ok, chồng tôi có lẩu cá. Ông thích nó và nghĩ rằng nó ngon.
Không có nước sốt trên bàn cũng không có muối và hạt tiêu.
Người phụ nữ không nghe thấy khi chúng tôi gọi cô ấy. Tôi cảm thấy tiếc cho cô ấy, đã đến lúc cô ấy nghỉ hưu.
Bữa tối của chúng tôi với 4 loại bia trong nước 1 chả giò, lẩu và mì là 300000 vnd', '11 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Greenclifflady', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/1c/03/1f/greenclifflady.jpg?w=100&h=-1&s=1', 2, 'Bữa ăn tồi tệ ở một nơi chật chội. Rất tiếc phải nói đây là một trong những bữa ăn tồi tệ nhất chúng tôi có ở Việt Nam. Dịch vụ chậm và không phụ nữ phục vụ nói tiếng Anh đầy đủ. Chúng ta thường có thể đối phó với điều đó, nhưng ít nỗ lực đã được thực hiện để hiểu những gì chúng ta muốn. Chả giò rất béo ngậy và bữa ăn chính của gà rán đã quá chín và vô vị. Rất đáng thất vọng', '30 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Luby_lu_222', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2e/70/7f/avatar066.jpg?w=100&h=-1&s=1', 4, 'Thức ăn ngon, không khí tuyệt vời. Đến ăn tối và không thất vọng. Nó cực kỳ bận rộn với chủ yếu là người dân địa phương, không khí rất sôi nổi, thực sự tốt đẹp.
Có một thực đơn tiếng Anh và một số nhân viên nói tiếng Anh. Thức ăn là tốt, đặc biệt là cá om là tuyệt vời', '30 tháng 11, 2019', CURRENT_TIMESTAMP);

