    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tuyết', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e5/2b/default-avatar-2020-52.jpg?w=100&h=-1&s=1', 5, 'Nhiều hàng quán, rất tiện lợi. Nhiều nhà hàng với nhiều lựa chọn khách nhau, có cả quán bia, spa,....Khá sạch sẽ so với các trung tâm khác.', '14 tháng 4, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kien', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/11/default-avatar-2020-41.jpg?w=100&h=-1&s=1', 4, 'Không gian đẹp, thức ăn ngon, phục vụ chuyên nghiệp và có tâm. Nếu có cơ hội sẽ tiếp tục ghé quán trong tương lai', '21 tháng 2, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jena Kim', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Uầy mình mới đến Phú Quốc lần đầu, trên đg đi chợ đêm thì gặp chỗ này tấp vào xong chơi cả tối bỏ đi chợ đêm luôn :))))) Mình có dùng món ở nhà hàng Pháp, đồ âu giá việt nhưng chất lượng rất tôt nha. xong vòng lên uống cf chỗ quán cuối đường, view rất chill đẹp. nước cũng được ko quá xuất sắc nhưng đc cái nvien nhiệt tình cực. Ưng ý nhất là quán bia tươi, góc nào chụp hình cũng đẹp với bia ngon. Nói chung nếu có dịp đi PQ lại thì mình vẫn sẽ ghé đây, ở khu trung tâm dương đông thì chỗ này chắc vui nhất bự nhất giồi.', '3 tháng 2, 2023', CURRENT_TIMESTAMP);

