    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Pioneer46868484336', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/ef/default-avatar-2020-66.jpg?w=100&h=-1&s=1', 5, 'Tui hôm trước có đi với gia đình qua đây. Tui book xe bên  https://thongthuongtravel.com/ ở nội ô cần thơ đi ucii lắm, nếu có thể mn cũng thử nha', '8 tháng 2, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'KENNY TOURGUIDE', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/30/9a/69/f3/caption.jpg?w=100&h=-1&s=1', 4, 'Điều thú vị là tôi được trải nghiệm 1 nét văn hóa chợ nổi vô cùng đặc biệt họ buôn bán ngay ở trên sông và sinh sống trên những chiếc ghe', '30 tháng 11, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'TLTourism', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2f/5e/07/c8/caption.jpg?w=100&h=-1&s=1', 4, 'Chúng tôi luôn sắp xếp thời điểm tham quan sáng sớm để cho khách tận hưởng không khí nhộn nhịp trong mua bán nông sản địa phương. Mặc dù hiện tại có rất nhiều bè nổi, hộ gia đình làm dịch vụ du lịch nhưng lại đánh mất đi nét tự nhiên nhất, giá trị văn hoá gốc vốn có của chợ nổi. Vì thế, chúng tôi luôn kết hợp các vườn trái cây, nhà dân, hoạt động trên đường làng, và chắc chắn phải có hướng dẫn viên chuyên nghiệp, kiến thức, hoạt náo, mới có thể kết nối mang sự trải nghiệm tuyệt vời nhất. Rất mong được sự ủng hộ của bạn bè gần xa trong thời gian tới !!!', '17 tháng 3, 2025', CURRENT_TIMESTAMP);

