    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'คุณตาตา', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e9/60/default-avatar-2020-64.jpg?w=100&h=-1&s=1', 5, 'theo lời dẫn của chú trông coi, ngôi nhà này đã 150 năm tuổi. Nhà xây theo kiến trúc Đông -Tây với 4 lối vào, bên trong có rất nhiều di vật cổ, hoa văn trên tường và cột nhà, thích nhất là có cây xương rồng to cao trên 40 tuổi và rất nhiều loại hoa lan, hồ cá non bộ ngay trước nhà, đẹp lắm👍', '14 tháng 10, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
