    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/84/e0/f7/photo0jpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Robert G', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e4/2d/default-avatar-2020-48.jpg?w=100&h=-1&s=1', 5, 'Một ngôi chùa rất đẹp, một nơi thờ cúng được tôn trọng. Cởi giày ra, bước qua ngưỡng không phải trên tấm ván chạy ngang. Trong tất cả các ngôi đền và chùa tôn giáo hỏi bạn có thể chụp ảnh không, những nơi này được xây dựng cho khách du lịch, họ là một phần của văn hóa và phục vụ nhu cầu của người dân, chúng tôi được cho phép ở đó. Nhiều ngôi chùa đẹp ở Việt Nam tất cả những nơi tốt để đi và chiêm ngưỡng cuộc sống của chính bạn và để cầu nguyện cho những người khác và thế giới nói chung. Đến đó với một trái tim tốt và sẵn sàng học hỏi và bạn sẽ đi tốt hơn cho trải nghiệm.', '16 tháng 12, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, '124kater', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-s/01/2a/fd/96/avatar.jpg?w=100&h=-1&s=1', 3, 'Đây là một ngôi chùa nhỏ nhưng đẹp. Đức Phật lòng thương xót được thờ ở đây cũng như tượng Trung Quốc tượng trưng cho sự thịnh vượng. Đáng để dừng lại ở đây - chưa đầy 10 phút trước khi đi bộ xuống thuyền để đến chợ nổi.', '9 tháng 8, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'rainchong77', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/06/default-avatar-2020-18.jpg?w=100&h=-1&s=1', 4, 'Đám cưới thích đến đây. Đối diện là tượng HO CHIH MIHN! Đi bộ thư giãn có quán cà phê Việt Nam nổi tiếng gần đó.', '7 tháng 8, 2019', CURRENT_TIMESTAMP);

