    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'phương uyên ko phải phương quyên', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/47/4d/fb/caption.jpg?w=100&h=-1&s=1', 5, 'dui dẻ hạnh phúc. đồ ăn ngon chứ k có cũng được, view chuẩn âu chứ k có hơi âu. Có rất nhiều loại rượu ngon chứ k phải 1 hay 2 loại, nói chung là mê!!', '25 tháng 5, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoa Nở Về Đêm', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 5, 'TUYỆT VỜI, CẢM ƠN BEER & WINE RESTAURANT. Nơi đầu tiên ở Cần Thơ tôi cảm thấy chuẩn Âu đúng nghĩa: từ bài trí món ăn, set up bàn ăn, cách phục vụ cho đến các vật dụng… 
Phòng ăn ấm cúng, món ăn rất ngon và đặc biệt rượu vang khá phong phú và giá cả hợp lý. Giá niêm yết trên chai tại showroom để bán mang đi và giá phục vụ trong nhà hàng là một giá, đó là điểm khác biệt giữa các nhà hàng khác. Điều này giúp tôi thưởng thức đúng nghĩa chai vang ngon đúng với giá tiền của nó. 
Tôi rất thích phong cách nhà hàng này. Các bạn có dịp nên ghé qua!', '25 tháng 5, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'nương', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/3f/67/60/caption.jpg?w=100&h=-1&s=1', 5, 'Vui ngon sạch. Không gian lãnh mạn, nhiều loại rượu vang đặc biệt và ngon. Phong cách âu vô cùng sang trọng. Nhân viên nhiệt tình dễ thương. Món pate gan ngỗng cực ngon! Hứa hẹn sẽ đến nhìu lần', '22 tháng 5, 2023', CURRENT_TIMESTAMP);

