    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/2a/37/4b/27/capti_r.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hà Thu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 4, 'Du lịch. Tôi và bạn của tôi đã được giới thiệu tới đây. Món ăn tạm ổn. Bông bí nhồi thịt chiên dòn ngon.  Bạn nên thử.có cơ hội sẽ trở lại sau', '25 tháng 5, 2022', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Macey L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/4f/1b/ee/macey-l.jpg?w=100&h=-1&s=1', 3, 'Không khí tốt nhưng không tốt cho bữa ăn. Hướng dẫn viên giới thiệu chúng tôi đến nhà hàng này. Thức ăn chỉ ở mức trung bình. Nếu chúng ta nhìn xung quanh mình thay vì làm theo hướng dẫn viên du lịch, chúng tôi chắc chắn sẽ chọn nhà hàng khác ở góc đường thay thế.
Chúng tôi đã đặt hàng tôm dừa mà chỉ cần đặt tôm lên dừa. Không có bất kỳ ưu đãi đặc biệt mà bạn mong đợi từ tôm. Những bông hoa bí ngô chiên giòn cũng thật đáng thất vọng. Có vẻ như không sử dụng nhiệt độ thích hợp để làm món chiên giòn.
Nhưng nhà hàng nằm ngay cạnh sông. Không khí thật thư giãn. Có lẽ cho một thức uống là tốt hơn cho bữa ăn tối', '8 tháng 2, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Katja W', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e7/99/default-avatar-2020-57.jpg?w=100&h=-1&s=1', 5, 'Siêu dịch vụ và thực phẩm. Ok một chút thức ăn phương Tây trên meny nhưng cũng địa phương. Trở lại đây hai lần liên tiếp cho bữa tối. Thức ăn và dịch vụ rất tốt. Năng lực và dịch vụ có đầu óc cá nhân', '8 tháng 1, 2020', CURRENT_TIMESTAMP);

