    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/15/39/a6/de/our-energetic-chef-tintin.jpg', 2, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/25/40/20/61/our-new-logo.jpg', 3, CURRENT_TIMESTAMP);
    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/28/50/a0/eb/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Sue C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ec/a2/default-avatar-2020-3.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi may mắn có được đầu bếp TinTin. Cô là một đầu bếp tuyệt vời, người hướng dẫn, nhà đàm phán thị trường và giáo viên. Cô ấy điều hành toàn bộ lớp một cách dễ dàng - từ đón đến đi thuyền, sau đó cho phép lớp nấu các món ăn Việt Nam sau những hướng dẫn dễ dàng của cô. Ai biết tất cả chúng ta có thể nấu ăn với lửa? ? ? Một món ăn đã được đốt cháy để caramen thịt bò. Cô chỉ đề nghị giúp đỡ ở chợ. Nếu không, tất cả chúng ta để lại như một đầu bếp món ăn có khả năng! !Lớp học ngoài trời rất gọn gàng và ngăn nắp. Tất cả nhân viên đều lịch sự và chuyên nghiệp.Đây là một tour du lịch thú vị. - XỨNG ĐÁNG!', '11 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Lise B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0a/64/b6/3d/lise-b.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi yêu thích lớp học nấu ăn hoàng hôn của chúng tôi! Chúng tôi chỉ ra những gì cần làm. Chúng tôi đều tham gia nấu ăn và đó là niềm vui. Thức ăn rất ngon và chúng tôi đã nhận được các công thức nấu ăn trong một cuốn sách nhỏ và đũa nấu ăn. Tôi rất khuyến khích!', '10 tháng 3, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Kevin B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/20/ce/6f/photo0jpg.jpg?w=100&h=-1&s=1', 5, 'Chúng tôi đến lớp học nấu ăn. Tintin là người hướng dẫn của chúng tôi. Cô ấy đón chúng tôi tại khách sạn và sau đó chúng tôi đi chợ để mua nguyên liệu. Tintin rất hiểu biết và hữu ích. Giải thích những gì chúng ta sẽ mua cho bữa ăn của chúng tôi. Khi chúng tôi đến địa điểm, cô ấy rất tuyệt khi chỉ cho chúng tôi và cho chúng tôi biết những gì chúng tôi sẽ làm và những gì chúng tôi sẽ chuẩn bị. Cô ấy luôn sẵn sàng giúp đỡ và đưa ra hướng dẫn. Lớp học thật tuyệt và thức ăn mà chúng tôi đã chuẩn bị, với sự giúp đỡ của cô ấy, có hương vị tuyệt vời. Ngả mũ với Tintin, muốn giới thiệu chuyến tham quan này cho bất cứ ai và tất cả mọi người! !Kevin', '10 tháng 3, 2020', CURRENT_TIMESTAMP);

