    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Switch B', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ea/2e/default-avatar-2020-67.jpg?w=100&h=-1&s=1', 4, 'A. khu chợ nơi bạn có thể mua đồ ăn và quần áo tuyệt vời, bánh kẹo mọi loại, một trải nghiệm mua sắm tuyệt vời! Thdy cũng có một khu vực làm đẹp nơi bạn có thể được chăm sóc mặt, cắt móng, cắt tóc! vân vân!', '10 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Bobbi S', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/34/02/35/73/caption.jpg?w=100&h=-1&s=1', 4, 'Đây không phải là - chợ khổng lồ nằm ở trung tâm khu dân cư đô thị của Phnom Penh. Giống như bất kỳ chợ buổi sáng nào, nơi đây cực kỳ đông đúc, nhỏ gọn, hơi tối vì các tòa nhà và tháp trên cao, nhưng bạn sẽ tìm thấy gần như mọi thứ bạn cần, bao gồm rau củ, trái cây, cá tươi, chỉ ăn thịt cắt, vịt, lợn, gia cầm, quần áo làm theo yêu cầu, và chỉ - đồ ăn nấu để mang về. Đây thực sự là chợ của người dân địa phương nhưng ai cũng có thể đến.', '15 tháng 12, 2025', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ly Ching', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f1/79/default-avatar-2020-21.jpg?w=100&h=-1&s=1', 4, 'Tôi đã đến Chợ ORUSSEY với mẹ để mua hành lý , và ở đó tôi đã ăn KUY TEV tại ORUSSEY MAKET KUY TEV rất ngon nhưng rất đắt , và tôi và tôi đã mua rất nhiều hành lý.', '14 tháng 7, 2025', CURRENT_TIMESTAMP);

