    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1d/e0/84/75/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Dreamer29759519801', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f2/eb/default-avatar-2020-27.jpg?w=100&h=-1&s=1', 1, 'Tại sao lại quấy rối tôi sau khi tôi đã đưa đúng vé vì tôi vô tình lấy nhầm một vé cũ ra trước, cứ như thể đang cố tình lén lút vậy', '13 tháng 10, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Daniel D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/df/2b/default-avatar-2020-39.jpg?w=100&h=-1&s=1', 1, 'Các xe buýt ghi là chạy mỗi 7 - 10 phút thực tế lại chạy mỗi nửa giờ một chuyến. Và các tài xế xe buýt cố gắng hết sức để KHÔNG đón hành khách. Đã đợi rất lâu trong giờ cao điểm để chờ xe buýt mà tài xế lại không dừng. Sau đó, tài xế xe buýt tiếp theo đã cố gắng đóng cửa vào mặt tôi trước khi tôi kịp lên. Khi tôi nắm lấy cánh cửa và mở ra, anh ấy đã trở nên hoảng loạn. TTC không phải là một phương tiện giao thông đáng tin cậy. Không ai có đủ khả năng mua xe hơi hoặc gọi Uber sẽ bao giờ đi vì mất hơn một giờ để đến một nơi bạn có thể lái xe đến trong 15 phút.', '15 tháng 9, 2026', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'James L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/ee/68/default-avatar-2020-9.jpg?w=100&h=-1&s=1', 1, 'Xe buýt ttc trên đại lộ Wilson tệ nhất, họ không chờ hành khách nữa, họ dừng cách biển dừng xe buýt ttc và không đón hành khách, họ chỉ đi vào giao thông và bỏ lại tất cả hành khách đang chờ ở trạm xe buýt. Điều này xảy ra mọi lúc. Nếu đây là xe buýt của bạn thì bạn muốn làm gì thì làm, nhưng nếu đây là công việc của bạn thì hãy làm nó một cách đúng đắn.', '10 tháng 9, 2026', CURRENT_TIMESTAMP);

