    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/12/ef/ec/d3/20180429-105427-largejpg.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mark R', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/08/72/f7/5a/mark-r.jpg?w=100&h=-1&s=1', 5, 'Tôi đã học về Đức Quốc xã ở trường cho đến Đại học. Tôi đã từng đến trại tập trung và nhiều trận chiến và nghĩa địa chiến tranh. Tôi biết lịch sử WW 2 của tôi. Vì vậy, khi tôi nghiên cứu về một chuyến đi đến Nuremburg và phát hiện ra tòa án nơi Đức Quốc xã xét xử vẫn ở đó và mở đầu bằng một bài thuyết trình, nó giống như một danh sách lựa chọn đang được bật. Đó là một tòa nhà rất ấn tượng, khắc khổ và tuyệt vời. Phần trình bày bằng âm thanh cũng rất xuất sắc, cung cấp cái nhìn sâu sắc về kết quả và ý nghĩa của các cuộc thử nghiệm đối với sự trừng phạt rộng rãi hơn của bốn thế lựcvà Tây Đức. Chắc chắn đề nghị trong một vài giờ.', '29 tháng 9, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'kpiddy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/18/d3/7f/kpiddy.jpg?w=100&h=-1&s=1', 5, 'Triển lãm kích thích tư duy tuyệt vời', '17 tháng 9, 2023', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Meander39480541724', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f3/e4/default-avatar-2020-30.jpg?w=100&h=-1&s=1', 5, 'Lần thứ 2 ở đây. Nhớ rằng nó đáng giá nên tôi cố gắng giết thời gian trong cái nóng trong ngày. Làm việc hoàn hảo. Là người duy nhất nói tiếng Anh, tôi dựa vào âm thanh (đã bao gồm phí vào cửa) cho mọi thứ. Bạn có thể dành 2 - 3 giờ nếu nghe hết mọi thứ. Tôi để lại một ít cho lần sau và 1 của tôi. 5 giờ là hoàn hảo. Tôi đi bộ từ phố cổ (~ 30 phút) NB lần trước nó đã đi bằng U Bahn… hoặc hoạt động tốt. Không thú vị cho tất cả mọi người nhưng lịch sử tốt đẹp nếu bạn tìm hiểu chi tiết về các thử nghiệm.', '9 tháng 9, 2023', CURRENT_TIMESTAMP);

