    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1b/58/d4/d7/img-20200509-131623-largejpg.jpg', 2, CURRENT_TIMESTAMP);
