    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0e/90/aa/9b/photo-prise-par-guy-lazignac.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'gat_lontok', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/4e/99/23/external-avatar.jpg?w=100&h=-1&s=1', 5, 'Tôi đến Sóc Trăng quá muộn và phải hủy kế hoạch đến thăm nơi này vào chiều muộn. Vì vậy, tôi đã phải làm chuyến thăm của tôi vào sáng hôm sau.Tôi đến sớm đến mức tôi thực sự ở cổng khi nhà sư mở khóa nó. Nơi này là thanh thản và yên tĩnh tiết kiệm cho một số âm nhạc truyền thống bùng nổ từ bên ngoài. Sau đó tôi phải tìm những con dơi (nơi này được gọi là chùa Bát, phải không?). Bởi vì đó là ban ngày, chúng ít hoạt động hơn và bạn cần nỗ lực để hình dung chúng treo lơ lửng trên cành cây. Chúng được ngụy trang bằng những chiếc lá và không dễ nhận thấy. Tuy nhiên, bằng cách đi xung quanh khu phức hợp, người ta có thể chiêm ngưỡng kiến trúc phật giáo. Có một bảng hiệu đề cập đến các sinh vật là "cáo bay" - điều này hứa hẹn cho tôi nghiên cứu và thấy rằng', '15 tháng 10, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hoatg', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/02/75/28/caption.jpg?w=100&h=-1&s=1', 4, 'Nét đẹp và sức thu hút của Chùa Dơi sóc trăng là cảnh quan gần gũi với thiên nhiên, với một quần thể kiến trúc mở, hoà quyện với môi trường sống của con người. Thực vật, động vật nơi đây đã gắn bó với con người từ lâu đời. Hơn nữa, cộng đồng dân cư ở đây có sự giao lưu giữa ba dân tộc Kinh, Khmer và Hoa kết hợp với tinh hoa văn hoá, nghệ thuật trong cuộc sống.', '28 tháng 3, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Ninh_Ha', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/14/1d/60/1f/haninh164.jpg?w=100&h=-1&s=1', 4, 'Mình không hiểu lắm về tín ngưỡng của đồng bào Khmer, nhưng khi đến chùa Dơi, mình đã rất thích bởi vẻ đẹp rất tự nhiên, thật thú vị khi tìm lũ dơi ngủ ngày trong những tán cây cao. Một điểm rất nên đến thăm.', '3 tháng 12, 2018', CURRENT_TIMESTAMP);

