    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'AnHuy', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/eb/a3/default-avatar-2020-38.jpg?w=100&h=-1&s=1', 1, 'Đi 1 lần không dám đi nữa. Tôi bị giật mất dây chuyền. Cướp giật ghê lắm. Đừng ai đi nữa. Toàn phe cướp của tụi nó không hà. Đi để cúng chùa ai ngờ mất của thì đi làm chi. Kêu cũng không ai giúp hết', '11 tháng 3, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'garry2504', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/11/cd/eb/a8/photo0jpg.jpg?w=100&h=-1&s=1', 4, 'Rất thú vị nơi, rất nhiều tác phẩm điêu khắc để xem, rất yên bình cũng có, chúng tôi đã thuê một chiếc xe tay ga để đến đó chỉ có 15 phút từ Sóc Trăng', '18 tháng 1, 2018', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hưng C', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e8/5b/default-avatar-2020-61.jpg?w=100&h=-1&s=1', 5, 'Nơi đây là một ngôi chùa rộng lớn nhất Sóc Trăng tính đến thời điểm này, có rất nhiều cảnh đẹp và tượng phật cùng với các bức tượng miêu tả về các câu truyện cỗ tích ngày xưa, nếu các bạn có dịp đi ngang Sóc Trăng thì tuyệt đối phải đến đây một lần, các bạn sẽ không thất vọng khi bước chân vào chùa.', '17 tháng 3, 2017', CURRENT_TIMESTAMP);

