    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jakob D', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f0/d5/default-avatar-2020-17.jpg?w=100&h=-1&s=1', 5, 'Ẩn địa phương nhỏ. Đó là kinh nghiệm địa phương khá thú vị. Chúng tôi đã đến thăm nơi này vào buổi tối. Nơi này có mùi buồn cười khi bắt đầu nên chúng tôi tự hỏi liệu mọi thứ có sạch sẽ không. Người phục vụ có thể nói tiếng Anh kém nên chúng tôi cpuld gọi món gì đó. Chúng tôi không mong đợi điều này. Nhưng may mắn thay, có một số người dân địa phương mà chúng tôi đã thấy thức ăn được ăn như thế nào. Thức ăn thật tuyệt. Chúng tôi đã gọi món Đậu phụ, rau, mì và những thứ tôi không thể nhớ. Bạn chỉ cần cuộn mọi thứ trong bánh tráng mỏng này. Dù sao nó đã rẻ và rất tốt', '6 tháng 3, 2020', CURRENT_TIMESTAMP);

