    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mr NHD', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/89/19/3d/caption.jpg?w=100&h=-1&s=1', 5, 'Chùa với tên gọi mà người dân vẫn hay truyền tai nhau gọi là Mẹ Nam Hải.Hướng xoay ra biển như để nhìn và cứu độ ngư dân đi biển, cho họ luôn được bình an.Chùa khá rộng rãi và đông đúc người dân thập phương đến đảnh lễ và chiêm bái Mẹ Nam Hải.Có cả bãi giữ xe miễn phí, cơm nước miễn phí cho mọi người đến đây.', '25 tháng 9, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
