    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Young L', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/06/d0/ed/e9/young-l.jpg?w=100&h=-1&s=1', 4, 'Khi chúng tôi đi du lịch ở Bạc Liêu, chúng tôi dừng chân nhanh chóng sau khi viếng thăm Nhà thờ Trường Bửu Diệp, chúng tôi dừng lại ở Phát Bá Quán Âm. Đó là vào buổi tối, nhưng đám đông vẫn còn lớn vì nó đã được ngay sau khi năm mới.', '27 tháng 4, 2018', CURRENT_TIMESTAMP);

