    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Tiendungkieu', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/e2/e6/default-avatar-2020-45.jpg?w=100&h=-1&s=1', 4, 'Quán ăn thiết kế đẹp mắt.. đúng với tên gọi thuyền trăng, phía sau nhà hàng là một chiếc thuyền được thiết kế nổi trên sông khiến cho du khách ngồi ăn có cảm giác như mình đang ngồi trên một chiếc thuyền lênh đênh trên sông đối ẩm cùng trăng. Tuy nhiên do chúng tôi đến vào mùa mưa nên quán khá nhiều muỗi. Nhân viên phải dùng nhang muỗi để khách có thể thưởng thức món ăn được ngon hơn. Tay nghề của đầu bếp cũng không tệ và nhân viên nhiệt tình phục vụ', '7 tháng 9, 2017', CURRENT_TIMESTAMP);
