    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Toàn N', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/16/fd/06/bun-nu-c-leo-ca-d-ng.jpg?w=200&h=200&s=1', 5, 'Bún nước lèo Út Mén bạc liêu, vị ngon trứ danh. Tuyệt vời khi đã đến vùng đất nắng và gió biển bạc liêu, lại được thưởng thức một tô bún nước lèo có thể nói ngon nhất từ trước đến này mà mình dùng. Chủ quán là một cô chủ xinh đẹp và hiếu khách, từng cọng rau con cá con tép đều hoàn toàn tự nhiên, rau đồng cá đồng tép biển. ôi bạc liêu giấc mơ tình yêu', '27 tháng 6, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
