    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Hai Phan (Francis)', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/18/3a/b3/e4/caption.jpg?w=100&h=-1&s=1', 4, 'Mảnh lịch sử đẹp. Một nơi để có một số kinh nghiệm của thời xưa ở Bạc Liêu và đồng bằng sông Cửu Long. Ngôi nhà được bảo trì tốt với rất nhiều hạng mục lịch sử', '14 tháng 2, 2020', CURRENT_TIMESTAMP);
