    INSERT INTO place_photos (id, place_id, photo_url, display_order, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/29/8a/9b/ac/caption.jpg', 4, CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Mây Nguyễn', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0d/06/7a/e0/thu-van-n.jpg?w=100&h=-1&s=1', 5, 'Nếu đã từng check in các điểm cực của Tổ Quốc thì đây sẽ là điểm phải đến, còn nếu không phải để check in như trên thì đây cũng là điểm nên đến ít nhất một lần để hiểu hơn về đất nước mình. Bạn nên thuê ca nô (chở được 10 người, giá 1.250k / 60 phút) để khám phá rừng ngập mặn và bãi bồi. Cano chạy tốc độ cao len lỏi qua các khu rừng ngập mặn cảm giác rất thú vị. Cano sẽ dừng ở giữa biển để bạn có thể ngắm cảnh xung quanh, thấy tổng thể về vùng đất mũi. Để vào khu du lịch Đất Mũi bạn mua vé 30k / người. Nếu đi đông nên nhờ hướng dẫn viên tại điểm đưa  đi và giới thiệu để thêm yêu mến vùng đất này. Nếu đủ sức khoẻ, bạn nêu leo lên cột cờ với 245 bậc thang (11 tầng), từ trên cao nhìn xuống rất đẹp, gió mát tứ bề.', '28 tháng 10, 2020', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Jerjely', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/f4/d0/default-avatar-2020-33.jpg?w=100&h=-1&s=1', 4, 'Mũi Cà Mau - cực Nam Tổ quốc - nơi mà bất cứ người Việt nào cũng muốn tới thăm nếu có điều kiện.Vậy nhưng, hạ tầng và sản phẩm du lịch ở đây còn nghèo nàn: đường đến đất Mũi chật hẹp, cơ sở dịch vụ du lịch còn nghèo nàn.... chưa đáp ứng được nhu cầu của du khách thập phương...', '17 tháng 11, 2019', CURRENT_TIMESTAMP);
    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Van Nguyen', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0b/88/e9/23/van-n.jpg?w=100&h=-1&s=1', 4, 'Nơi này có ý nghĩa đối với người Việt Nam. Gia đình có thanh thiếu niên nên đến đây. Các bữa ăn rất ngon và rẻ!', '30 tháng 6, 2019', CURRENT_TIMESTAMP);

