    INSERT INTO place_reviews (id, place_id, author_name, author_avatar_url, rating, comment, relative_time_description, created_at)
    VALUES (gen_random_uuid(), v_place_id, 'Go19356088212', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/1a/f6/de/0a/default-avatar-2020-35.jpg?w=100&h=-1&s=1', 1, 'Chúng tôi đã đặt một chuyến tham quan tự hướng dẫn, nhưng không may ông tôi đã qua đời nên chúng tôi phải hủy chuyến đi Paris hoàn toàn. Bộ phận ''dịch vụ khách hàng'' yêu cầu giấy chứng tử để hoàn lại vé của chúng tôi. Không có lời chia buồn, không có suy nghĩ với chúng tôi, chỉ tập trung vào tiền bạc.Tôi đã nghĩ một nơi như thế này sẽ có nhiều đẳng cấp hơn. Đáng xấu hổ với bạn.', '19 tháng 10, 2026', CURRENT_TIMESTAMP);
